-- Correcciones de transcripción del himnario (ver content/correcciones.json).
-- No cambia updated_at: los celulares ya reciben estas correcciones con la app (catálogo v7).
update public.songs set title = 'Ven, ¡Oh Todopoderoso!', lyrics = 'Ven, ¡Oh, todopoderoso,
adorable creador!
Padre santo, cariñoso,
manifiesta tu amor.
A tu trono de clemencia
levantamos nuestra voz.
Tu presencia te pedimos,
nuestro padre, nuestro Dios.

Ven, ¡Oh salvador divino,
Dios de nuestra salvación!
En nosotros haz morada,
Vive en nuestro corazón.
Eres tú, Jesús, benigno,
eres infinito amor:
óyenos, te suplícanos.
Ven, bendícenos, Señor.

Ven, ¡Espíritu divino!
Danos tu precioso don;
Dios consolador, inspira
Paz en todo corazón.
De los santos la herencia
Déjanos hallar en ti.
Y la vida de los cielos
gozaremos ya aquí.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-1-ven-oh-todopoderoso/)' where id = 'sa-himno-1-ven-oh-todopoderoso';
update public.songs set title = 'Luz de Vida', lyrics = 'Luz de vida celestial,
fuego de divino amor,
brilla en mi corazón,
ven, inspírame fervor.
A cantar ayúdame
dignamente en honor
del cordero que murió
por salvar al pecador

Digno, digno de honor
es mi redentor Jesús,
quien al mundo redimió
por su muerte en la cruz.
Gloria sea a Jesús,
gloria sea y loor,
y dominio eternal
a Jesús, mi redentor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-2-luz-de-vida/)' where id = 'sa-himno-2-luz-de-vida';
update public.songs set title = 'Alma Mía, No Delires', lyrics = 'Alma mía, no delires,
ni suspires de dolor;
que posees en el cielo,
tu consuelo, tu Señor

Jesucristo, del pecado
te ha librado con la cruz
y derrama sobre el alma
gozo, calma, paz y luz.

El conoce tu conciencia,
tu dolencia y frenesí,
y con ansia te bendice
y te dice: “ven a mí”.

No más llanto, no más penas,
cosas buenas gozarás;
y en los brazos de tu dueño
dulce sueño dormirás', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-3-alma-mia-no-delires/)' where id = 'sa-himno-3-alma-mia-no-delires';
update public.songs set title = 'Yo por Cristo', lyrics = 'Yo, por Cristo defendido,
a tu nombre doy loor;
yo, con bienes proveído
que no tuvo mi Señor.

{soc}
Alabanzas
doy a ti, mi Salvador.
{eoc}

La pobreza y los dolores
este se dignó pasar;
y mi Dios con pecadores
no hallaba do posar.

{soc}
Alabanzas
doy a ti, mi Salvador.
{eoc}

A tu sombra Dios clemente,
yo tranquilo dormiré;
y a ti, omnipotente,
yo mi alma fiaré.

{soc}
Alabanzas
doy a ti, mi Salvador.
{eoc}

Yo indigno, tú piadoso,
sé no quieres desechar
al que viene presuroso
tu piedad a impetrar.

{soc}
Alabanzas
doy a ti, mi Salvador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-4-yo-por-cristo/)' where id = 'sa-himno-4-yo-por-cristo';
update public.songs set title = 'Cantemos Aquí', lyrics = 'Cantemos aquí con los santos en luz
con júbilo ellos te adoran, Jesús;
cercando el trono, te cantan loor;
millares sus voces, mas uno su amor

Los santos del cielo oímos decir:
“es digno el cordero de todo poder”;
cantemos nosotros con alma y voz:
“digno eres de gloria, cordero de Dios”.

Moriste queriendo a nosotros salvar,
y al cielo nos llevas contigo a reinar;
tú eres bendito querido Jesús,
la fuente de vida, riquezas y luz.

Se unen los cielos, la tierra y el mar,
al buen salvador Jesucristo a cantar
con ellos nosotros daremos loor,
con gran alegría a nuestro Señor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-5-cantemos-aqui/)' where id = 'sa-himno-5-cantemos-aqui';
update public.songs set title = 'Venid con Cánticos', lyrics = 'Venid, con cánticos, venid
del trono alrededor;
con ángeles loor rendid,
a Cristo el Señor.

De alabanzas digno es el,
que en la cruz bebió
la copa de amarga hiel
que vida al hombre dio.

Cantad mortales por doquier,
cantadle con ardor;
Él siempre es digno de poder,
dominio y honor.

Con gozo, pues, alzad la voz
alegre voz alzad
y con los ángeles de Dios,
a Cristo adorad.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-7-venid-con-canticos/)' where id = 'sa-himno-7-venid-con-canticos';
update public.songs set title = 'Venid Pecadores', lyrics = 'Venid pecadores,
que Dios por su amor
al cielo nos llama,
que es patria mejor,
do nunca la aurora
perdió su fulgor,
do brilla la gloria
del Dios creador.

{soc}
Sí, sí ¡venid, oh, venid!
al cielo, nos llama,
que es patria mejor.
{eoc}

Dejemos, hermanos,
aparte el dolor;
que allá en los cielos
el mundo cantor
de espíritus puros
proclama Señor
A Cristo Dios-hombre,
el gran redentor.

{soc}
Sí, sí ¡venid, oh, venid!
al cielo, nos llama,
que es patria mejor.
{eoc}

Trabajas y sufres
aquí pecador;
el pan que tú comes
regó tu sudor;
Mas Dios te reserva
Por suerte mejor,
primicias celestes
de eterno valor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-10-venid-pecadores/)' where id = 'sa-himno-10-venid-pecadores';
update public.songs set title = 'Oídlo, Pobre Pecador', lyrics = 'Oídlo, pobre pecador,
en Cristo hay perdón.
Confiad en él, confiad en él,
en él hay salvación

{soc}
Ven a Cristo, ven a Cristo,
ven a Emmanuel;
y la vida, y la vida,
hallarás en él.
{eoc}

Por redimirte el Señor
su sangre derramó,
y en la cruz, y en la cruz
tu redención obró.

{soc}
Ven a Cristo, ven a Cristo,
ven a Emmanuel;
y la vida, y la vida,
hallarás en él.
{eoc}

Camino cierto es Jesús,
que lleva a la paz;
venid a él, venid a él,
descanso hallarás.

{soc}
Ven a Cristo, ven a Cristo,
ven a Emmanuel;
y la vida, y la vida,
hallarás en él.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himnno-11-oidlo-pobre-pecador/)' where id = 'sa-himnno-11-oidlo-pobre-pecador';
update public.songs set title = 'Ven, Alma que Lloras', lyrics = 'Ven, alma que lloras, ven al salvador,
en tus tristes horas, dile tu dolor;
dile, sí, tu duelo, ven tal como estás.
Habla sin recelos, y no llores más.

Tu pena y tristeza dile a tu Señor;
cruel desventura, engaños y error;
en su tierno seno descanso hallarás;
ven, porque él es bueno, y no llores más.

Tú misma, al cansado, enseña la luz;
guía al angustiado hacia tu Jesús;
la bendita nueva de celeste paz
a los tristes lleva, y no llores más.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-13-ven-alma-que-lloras/)' where id = 'sa-himno-13-ven-alma-que-lloras';
update public.songs set title = 'No os Detengáis', lyrics = 'No os detengáis, seguid a Cristo.
Él nos guía con amor;
no os detengáis, por él ya listo
yo le sigo con valor.

{soc}
No os detengáis, no os detengáis
nunca, nunca, nunca;
Cristo por salvarnos dio
su sangre, cuando él murió.
No os detengáis, perdón recibe
quien confía en el Señor;
no os detengáis, que Cristo vive.
El precioso salvador.
{eoc}

{soc}
No os detengáis, no os detengáis
nunca, nunca, nunca;
Cristo por salvarnos dio
su sangre, cuando él murió.
No os detengáis, él ya ha muerto
por el triste pecador;
no os detengáis, camino cierto
es Jesús el salvador.
{eoc}

{soc}
No os detengáis, no os detengáis
nunca, nunca, nunca;
Cristo por salvarnos dio
su sangre, cuando él murió.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-14-no-os-detengais/)' where id = 'sa-himno-14-no-os-detengais';
update public.songs set title = 'Roca Abierta', lyrics = 'Roca abierta ya por mí,
dame abrigo siempre en ti,
es tu sangre, ¡oh, Jesús!
Derramada en la cruz,
el remedio eficaz,
por mi culpa contumaz.

Todo celo vano es,
vanas son mis lágrimas;
tú, ¡oh, Cristo salvador!
Sólo puedes perdonar;
vuestra cruz es perdón;
sólo en ti hay salvación.

Mientras tenga vida acá
en mi hora última
cuando te veré, Jesús,
en el trono de la luz,
roca abierta ya por mí
dame siempre abrigo en ti.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-16-roca-abierta/)' where id = 'sa-himno-16-roca-abierta';
update public.songs set title = 'Oh, Jesús Señor Divino', lyrics = '¡Oh, Jesús, Señor, divino!
Dame el perdón y paz,
oye mi ferviente ruego,
en la gloria do estás.
Eres tú la luz del mundo;
guíame, ¡oh, mi Jesús!
Por mí, con amor profundo,
tú moriste en la cruz.

{soc}
El Señor me ama a mí
y también te ama a ti,
vida dio en la cruz por mí
y por él yo soy feliz.
{eoc}

Gloria, gloria, paz, ventura
voy al cielo a gozar;
y de Cristo la ternura
voy allá a disfrutar.
A la patria, yo, cristiano,
me dirijo con fervor,
con certeza que salvado
soy por ti, mi buen Señor.

{soc}
El Señor me ama a mí
y también te ama a ti,
vida dio en la cruz por mí
y por él yo soy feliz.
{eoc}

Por tu muerte de cariño
me abriste, salvador,
amplio, único esplendor.
Él la gloria, felizmente,
al estar con mi Jesús,
de la pena yo ausente
viviré en dulce luz.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-17-oh-jesus-senor-divino/)' where id = 'sa-himno-17-oh-jesus-senor-divino';
update public.songs set title = 'Bondadoso Salvador', lyrics = 'Bondadoso salvador,
sé mi fiel amparador;
negras olas de aflicción
me amenazan destrucción.
De este espanto y terror,
sálvame. ¡oh, buen Señor!
Y mi barco sin quebrar
en el puerto hazlo entrar

Consternado de terror,
sin refugio, sin valor,
mi afligido corazón
clama a ti por salvación.
Muéstrame tu inmenso amor
mi benigno salvador;
sólo esperanza y luz
no me dejes, ¡oh, Jesús!

Compasivo redentor,
salva a un triste pecador;
vida eterna mora en ti;
rica gracia nace allí.
Lléname el corazón
con el don de salvación,
y seguro, sin temor,
gozaré de tu favor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-19-bondadoso-salvador/)' where id = 'sa-himno-19-bondadoso-salvador';
update public.songs set title = 'Mirad al Salvador', lyrics = 'Mirad al salvador Jesús,
el príncipe benigno,
por mí muriendo en la cruz,
por mí, tan vil, indigno.

{soc}
De amor la prueba, ¡he aquí!
El salvador murió por mí,
por mí, por mí,
Jesús murió por mí.
{eoc}

El sol su rostro encubrió
al ver su agonía;
la dura peña se partió
oídlo, alma mía.

{soc}
De amor la prueba, ¡he aquí!
El salvador murió por mí,
por mí, por mí,
Jesús murió por mí.
{eoc}

Y yo también al ver la cruz,
por ella soy vencido;
mi corazón te doy, Jesús,
a tu amor rendido.

{soc}
De amor la prueba, ¡he aquí!
El salvador murió por mí,
por mí, por mí,
Jesús murió por mí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-21-mirad-al-salvador/)' where id = 'sa-himno-21-mirad-al-salvador';
update public.songs set title = 'Confío Yo en Cristo', lyrics = 'Confío yo en Cristo
que en la cruz murió;
por esa muerte listo
a la gloria viajo yo.
Con sangre tan valiosa,
mis culpas lava él;
la derramó copiosa
por mí ya Emmanuel.

Me cubre su justicia
de plena perfección.
Eres Jesús delicia,
eres mi salvación.
Jesús, en ti descanso;
reposo tú me das;
con alma yo avanzo
al cielo donde estás.

A disfrutar invitas
contigo, mi Señor;
delicias infinitas,
y celestial amor;
espero yo mirarte,
oír tu dulce voz;
espero yo cantarte
mi salvador y Dios.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-22-confio-yo-en-cristo/)' where id = 'sa-himno-22-confio-yo-en-cristo';
update public.songs set title = 'De Heladas Cordilleras', lyrics = 'De heladas cordilleras,
de playas de coral,
de etiópicas riberas
del mar meridional,
nos llaman afligidas
a darle libertad,
naciones sumergidas
en densa obscuridad.

Nosotros alumbrados
con celestial saber,
¿a tantos angustiados
dejamos perecer?
A todos, pues, llevemos
gratuita salvación;
el Cristo prediquemos
que obró la redención

Llevada por los vientos
la historia de la cruz,
despierte sentimientos
de amor al buen Jesús;
prepare corazones,
enseñe su verdad
en todas las naciones,
según su voluntad.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-23-de-heladas-cordilleras/)' where id = 'sa-himno-23-de-heladas-cordilleras';
update public.songs set title = 'Yo Vil Indigno', lyrics = 'Yo, vil, indigno pecador,
mi alma llena de dolor,
perdón buscando, acudí
a Cristo que murió por mí.

{soc}
Murió por mí, murió por mí.
Jesús murió por mí.
{eoc}

Con humildad y contrición
le supliqué su compasión
postrado a sus pies pedí
perdón, porque murió por mí.

{soc}
Murió por mí, murió por mí.
Jesús murió por mí.
{eoc}

“perezco, sálvame, Jesús;
confío sólo en tu cruz;
¿a quién iré sino a ti?
Y tú me dices: ven a mí”.

{soc}
Murió por mí, murió por mí.
Jesús murió por mí.
{eoc}

Mi petición Jesús oyó
y del pecado me lavó
en esa fuente carmesí
que en la cruz abrió por mí.

{soc}
Murió por mí, murió por mí.
Jesús murió por mí.
{eoc}

Hallé en mi Jesús perdón,
alivio, paz y salvación;
y toda dicha conseguí
en Cristo que murió por mí.

{soc}
Murió por mí, murió por mí.
Jesús murió por mí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-24-yo-vil-indigno/)' where id = 'sa-himno-24-yo-vil-indigno';
update public.songs set title = 'Hay una Fuente Carmesí', lyrics = 'Hay una fuente carmesí,
que mi Jesús abrió
muriendo en la cruz por mí,
do limpio quedo yo.

En el Calvario él expió,
mi negra culpa ya;
y por la muerte que sufrió
la gloria me dará.

Después que yo su gran amor
en sus heridas vi,
en él confío con fervor
pues que murió por mí.

Y por tu mente en la cruz
en gloria celestial,
contigo allí, ¡oh, mi Jesús!
Seré yo inmortal.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-25-hay-una-fuente-carmesi/)' where id = 'sa-himno-25-hay-una-fuente-carmesi';
update public.songs set title = 'Yo Confío en Jesús', lyrics = 'Yo confío en Jesús
y salvado soy,
por su muerte en la cruz,
a la gloria voy.

Cristo dio por mí
sangre carmesí,
y por su muerte en la cruz,
la vida me dio Jesús.

Todo fue pagado ya.
Nada debo yo,
salvación perfecta da
quien por mí murió.

Cristo dio por mí
sangre carmesí,
y por su muerte en la cruz,
la vida me dio Jesús.

Todo hizo mi Señor;
me salvó ya él;
con ternura y amor,
él me guarda fiel.

Cristo dio por mí
sangre carmesí,
y por su muerte en la cruz,
la vida me dio Jesús.

Mi perfecta salvación
eres, mi Jesús;
mi completa redención,
mi gloriosa luz.

Cristo dio por mí
sangre carmesí,
y por su muerte en la cruz,
la vida me dio Jesús.

En el cielo te veré,
tierno salvador;
tu presencia gozaré,
¡oh, Jesús, Señor!

Cristo dio por mí
sangre carmesí,
y por su muerte en la cruz,
la vida me dio Jesús.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-26-yo-confio-en-jesus/)' where id = 'sa-himno-26-yo-confio-en-jesus';
update public.songs set title = 'Tal Como Soy', lyrics = 'Tal como soy; sin más que decir
que a otro yo no puedo ir
y tú me invitas a venir,
bendito Cristo, vengo a ti.

Tal como soy; sin demorar,
del mal queriéndome librar
me puedes sólo tú salvar,
bendito Cristo, vengo a ti.

Tal como soy; en aflicción,
expuesto a muerte y perdición,
buscando vida y perdón,
bendito Cristo, vengo a ti.

Tal como soy; en aflicción,
me vence y con grato ardor
servirte quiero, mi Señor,
bendito Cristo, vengo a ti.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-27-tal-como-soy/)' where id = 'sa-himno-27-tal-como-soy';
update public.songs set title = 'No Hay Otro Mediador', lyrics = 'No hay otro mediador
entre Dios y el pecador,
más que el salvador Jesús
que por él murió en la cruz.

Él su sangre derramó;
la amarga hiel bebió;
hizo plena expiación
para toda trasgresión

Dios promete recibir
al que quiera a él venir
en el nombre de Jesús.
Y confiando en su cruz.

Cristo dice: “a mi venid”.
Sólo a él, pues acudid;
escuchad su dulce voz,
y por él llegad a Dios.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-28-no-hay-otro-mediador/)' where id = 'sa-himno-28-no-hay-otro-mediador';
update public.songs set title = 'Si Yo Mis Pecados', lyrics = 'Si yo mis pecados
pudiera lavar,
ni sangre en pago
pudiera negar;
si obras valieran
en pago del mal,
no fuera Calvario
el solo caudal.

Mas, sé que no tengo
en mi santidad;
no puedo limpiarme
de tanta maldad;
ni santo, ni ángel,
ofrece audaz
quitar mis pecados
y darme solaz

¡Oh, Cristo bendito!
En ti es mi paz
tus obras, tu sangre,
caudal eficaz;
tú llamas las almas
muriendo de sed:
“en mí es la fuente,
venid y bebed”', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-29-si-yo-mis-pecados/)' where id = 'sa-himno-29-si-yo-mis-pecados';
update public.songs set title = 'Gozo Hay en el Cielo', lyrics = 'Gozo hay en el cielo, por la salvación
De un desdichado pecador,
Alegría en la celestial mansión,
Himnos de triunfo y amor.

Gloria, ángeles, cantad a Dios,
gloria a Jesús alzad la voz;
redentor de toda la humanidad;
a Jesús con júbilo cantad.

Gozo hay en el cielo; otro pecador
Hoy, humilde, viene a la cruz;
Salvación alcanza en el redentor,
Vida en la sangre de Jesús

Gloria, ángeles, cantad a Dios,
gloria a Jesús alzad la voz;
redentor de toda la humanidad;
a Jesús con júbilo cantad.

Gozo hay en el cielo, todos a Jesús,
hoy tributan gloria y honor;
al cordero manso que murió en la cruz
por salvar al pobre pecador.

Gloria, ángeles, cantad a Dios,
gloria a Jesús alzad la voz;
redentor de toda la humanidad;
a Jesús con júbilo cantad.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-30-gozo-hay-en-el-cielo/)' where id = 'sa-himno-30-gozo-hay-en-el-cielo';
update public.songs set title = 'Suenen Dulces Himnos', lyrics = 'Suenen dulces himnos, gratos al Señor,
y óiganse en concierto universal
desde el alto cielo baja el salvador
para beneficio del mortal

{soc}
¡gloria sea nuestro Dios!
¡gloria! Sí, cantemos a una voz.
Y el cantar de gloria que se oyó en Belén,
sea nuestro cántico también.
{eoc}

Montes y collados fluyan leche y miel
y abundancia esparzan y solaz;
gócense los pueblos, gócese Israel,
que a la tierra viene ya la paz.

{soc}
¡gloria sea nuestro Dios!
¡gloria! Sí, cantemos a una voz.
Y el cantar de gloria que se oyó en Belén,
sea nuestro cántico también.
{eoc}

Salte de alegría, lleno, el corazón
la abatida y pobre humanidad;
Dios se compadece viendo su aflicción,
y le muestra buena voluntad.

{soc}
¡gloria sea nuestro Dios!
¡gloria! Sí, cantemos a una voz.
Y el cantar de gloria que se oyó en Belén,
sea nuestro cántico también.
{eoc}

Late en nuestros pechos noble gratitud
hacia el que nos brinda redención;
y a Jesús el Cristo que nos da salud,
tributemos nuestra adoración.

{soc}
¡gloria sea nuestro Dios!
¡gloria! Sí, cantemos a una voz.
Y el cantar de gloria que se oyó en Belén,
sea nuestro cántico también.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-31-suenen-dulces-himnos/)' where id = 'sa-himno-31-suenen-dulces-himnos';
update public.songs set title = 'Concédeme, Jesús, Poder', lyrics = 'Concédeme Jesús poder
y gracia para comprender
cuán dulce es tu amor;
hazme, Señor, con santidad.
Del cielo la felicidad,
aún aquí gozar

La santa sed inspírame
de conocerte a ti; sabré
entonces la virtud
de tu perfecta salvación,
y gozará mi corazón
de amor la plenitud

¡oh, santifícame Señor:
llena mi alma de tu amor;
permíteme oír,
tu voz, tu rostro contemplar,
tu hermosura admirar;
y en ti, por ti, vivir.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-33-concededme-jesus-poder/)' where id = 'sa-himno-33-concededme-jesus-poder';
update public.songs set title = 'Siempre Hablamos', lyrics = 'Siempre hablamos del mundo dichoso,
de los goces que Dios nos dará,
del país halagüeño y hermoso;
mas, hallarnos allí, ¿qué será?

Siempre hablamos del triunfo y la gloria
que en los cielos sin fin reinará.
De los himnos de amor y victoria;
mas, hallarnos allí, ¿qué será?

Siempre hablamos del día esplendente
que en el santo país brillará;
de Jesús el cordero inocente;
mas hallarnos allí, ¿qué será?

Ni pecados, ni llanto, ni duelo,
ni pesares ninguno habrá
en la casa de Dios en el cielo;
mas hallarnos allí, ¿qué será?', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-34-siempre-hablamos/)' where id = 'sa-himno-34-siempre-hablamos';
update public.songs set title = 'Voy al Cielo', lyrics = 'Voy al cielo –soy peregrino-
a vivir eternamente con Jesús,
el nos abrió, ya, veraz camino,
cuando murió por nosotros en la cruz.

{soc}
Voy al cielo –soy peregrino-
a vivir eternamente con Jesús.
{eoc}

Muerte, duelos, amarga pena,
nunca, nunca se podrán sentir más allá,
preciosa vida de gozo llena,
el alma mía sin fin disfrutará.

{soc}
Voy al cielo –soy peregrino-
A vivir eternamente con Jesús.
{eoc}

Tierra santa, hermosa y pura,
entraré a ti, salvado por Jesús;
y gozaré célica ventura
viviendo siempre en la divina luz.

{soc}
Voy al cielo –soy peregrino-
a vivir eternamente con Jesús.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-36-voy-al-cielo/)' where id = 'sa-himno-36-voy-al-cielo';
update public.songs set title = 'Jerusalén', lyrics = 'Jerusalén, hogar feliz,
sagrado para mí;
mi llanto, ¿cuándo fin tendrá
en paz y gozo en ti?

¡oh!, ¿cuándo, ciudad de Dios,
a tus cortes subiré,
y en tus puertas salvación
eterna hallaré?

Con santos y con ángeles,
feliz seré allí;
¡oh, país dichoso! Con afán
camino hacia a ti.

La muerte yo no temeré,
ni sentiré dolor;
mas, gozo eterno hallaré,
en Cristo, mi Señor.

Jerusalén, hogar feliz,
sagrado para mí,
mi alma pronto hallará
eterna paz en ti.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-37-jerusalem/)' where id = 'sa-himno-37-jerusalem';
update public.songs set title = 'Hay un mundo feliz', lyrics = 'Hay un mundo feliz más allá,
donde cantan los santos en luz,
tributando eterno loor
al invicto glorioso Jesús

En el mundo feliz,
reinaremos con nuestro Señor.
En el mundo feliz
reinaremos con nuestro Señor.

Cantaremos también a Jesús;
al cordero que nos rescató,
y con sangre vertida en la cruz,
los pecados del mundo quitó.

En el mundo feliz,
reinaremos con nuestro Señor.
En el mundo feliz
reinaremos con nuestro Señor.

Y allá en el mundo feliz,
con los santos daremos honor
al invicto, glorioso Jesús,
a Jesús nuestro rey de amor.

En el mundo feliz,
reinaremos con nuestro Señor.
En el mundo feliz
reinaremos con nuestro Señor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-38-hay-un-mundo-feliz/)' where id = 'sa-himno-38-hay-un-mundo-feliz';
update public.songs set title = 'Pecador ven al dulce Jesús', lyrics = 'Pecador ven al dulce Jesús,
Y feliz para siempre serás,
Que si tu le quisieres tener
Al divino Señor hallaras.

{soc}
Ven a el, pecador,
Que te espera tu buen salvador.
Ven a el, pecador,
Que te espera tu buen salvador.
{eoc}

Si cual hijo que necio peco
Vas buscando a sus pies compasión
Tierno hermano hallaras en Jesús,
Y tendrás en sus brazos perdón.

Si de enfermo te sientes morir,
El será tu doctor celestial,
Hallaras en su sangre también
Medicina que cure tu mal.

Ovejuela que huyo del redil,
Vuelve ya a tu benigno Señor,
Y en sus brazos llevada serás
Por tan dulce y amante pastor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-39-pecador-ven-al-dulce-jesus/)' where id = 'sa-himno-39-pecador-ven-al-dulce-jesus';
update public.songs set title = 'Cantaré, Cantaré', lyrics = 'Cantaré, cantaré del hermoso país,
el lejano glorioso jardín,
donde ha de vivir el alma feliz,
mientras vuelan los siglos sin fin.

¡oh, la patria del alma! En sueños se ven
sus muros de jaspe y cristal,
y cercano parece el bello Edén,
radiante con luz celestial.

Y el árbol de vida florece allá,
y corre el río de amor;
y jamás en la santa ciudad entrará
ni la muerte ni amargo dolor.

¡Oh, cuán dulce será en el santo país,
pasadas las penas aquí;
volveremos a ver en la vida feliz,
que nos queda con Cristo allí!', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-40-cantare-cantare/)' where id = 'sa-himno-40-cantare-cantare';
update public.songs set title = 'El Salvador Está Aquí', lyrics = 'El salvador está aquí,
el amoroso Cristo
el que se entregó por mí,
bendito Jesucristo

{soc}
Nombre digno de honor,
nombre dulce de amor,
nombre de mi redentor,
Cristo, Jesucristo.
{eoc}

Os dice él: “venid a mí”
oíd la voz de Cristo,
seguidme poco tiempo aquí
y reinarás con Cristo.

{soc}
Nombre digno de honor,
nombre dulce de amor,
nombre de mi redentor,
Cristo, Jesucristo.
{eoc}

Doy gloria a mi redentor,
confío yo en Cristo;
su nombre me infunde amor,
su dulce nombre, Cristo.

{soc}
Nombre digno de honor,
nombre dulce de amor,
nombre de mi redentor,
Cristo, Jesucristo.
{eoc}

Venid, cantad, a nuestro Dios,
al glorioso Cristo;
cantad con corazón y voz
al santo nombre de Cristo.

{soc}
Nombre digno de honor,
nombre dulce de amor,
nombre de mi redentor,
Cristo, Jesucristo.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-41-el-salvador-esta-aqui/)' where id = 'sa-himno-41-el-salvador-esta-aqui';
update public.songs set title = 'Ved del Cielo Descendiendo', lyrics = 'Ved del cielo descendiendo
al triunfante redentor;
ya en majestad tremenda
aparece el Señor,
¡aleluya!
Dios en tierra reinará.

Vedle todo revestido
de divina claridad,
los que le habéis vendido,
los que con atrocidad,
y escarnio
le llamasteis malhechor.

Muestra ahora las heridas
que le dieron en la cruz,
las señales imprimidas
en su cuerpo, que en la cruz
de la gloria
encarecen su piedad.

Cristo, rey te adoramos
en tu alto tribunal;
gloria, honor te tributamos,
rey de reyes eternal;
juez divino
todos te adorarán.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-43-ved-del-cielo-descendiendo/)' where id = 'sa-himno-43-ved-del-cielo-descendiendo';
update public.songs set title = 'La Palabra', lyrics = 'La palabra hoy sembrada
hazla, salvador, nacer,
para darle crecimiento,
sólo tienes tú poder,
ricos frutos
tú nos puedes conceder.

¡Oh! Prepara muchas almas
al servicio del Señor
y salvadlas por tu gracia,
bondadoso salvador.
Tu iglesia
mostrará tu grande amor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-44-la-palabra/)' where id = 'sa-himno-44-la-palabra';
update public.songs set title = 'Meditad', lyrics = 'Meditad en que hay un hogar
en la margen del río de luz,
donde van para siempre a gozar
los creyentes en Cristo Jesús,
más allá, más allá,
meditad en que hay un hogar
más allá, más allá,
en la margen del río de luz.

Meditad en qué amigos tenéis,
de los cuales marchamos en pos,
y pensar que al fin lo veréis,
en el alto palacio de Dios,
más allá, más allá,
meditad en qué amigos tenéis
más allá, más allá,
de los cuales marchamos en pos.

En que mora Jesús, meditad,
donde seres que amamos están.
Y a la tierra bendita volad
sin angustias, temores, ni afán.
Más allá, más allá,
meditad, en que mora Jesús,
más allá, más allá,
donde seres que amamos están.

Reunidos a mis deudos seré,
mi carrera a su fin toca ya.
Y en mi hogar celestial entraré,
do mi alma reposo tendrá,
más allá, más allá.
Reunidos a mis deudos seré,
más allá, más allá,
mi carrera a su fin toca ya.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-47-meditad/)' where id = 'sa-himno-47-meditad';
update public.songs set title = 'Alma Cese Tu Dolor', lyrics = 'Alma, cese tu dolor;
todo consumó Jesús;
tu castigo padeció
expirando en la cruz.
Alma, ya no llores más
mira a Cristo y vivirás.

En el justo se cargó
toda su inquietud,
Jehová le condenó,
porque tengas libertad.
Mira, triste pecador,
Cristo es tu salvador.

Si te entregas todo a él
tú recibirás perdón,
hallarásle siempre fiel,
pronto a darte salvación.
Mira a Cristo por la fe,
sin demora mírale.

¡Ah, Señor! Propicio sé
a mí, pobre pecador;
heme aquí con poca fe,
dame más, ¡oh, salvador;
ven, te pido, salva, sí;
sollozando corro a ti.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-48-alma-cese-tu-dolor/)' where id = 'sa-himno-48-alma-cese-tu-dolor';
update public.songs set title = 'Heme Aquí', lyrics = 'Heme aquí, Jesús bendito,
agobiado vengo a ti,
y en mis males necesito
que te apiades tú de mí.
Yo no puedo con la carga
que me oprime sin cesar;
es mi vida tan amarga,
tan intenso mi pesar.

Por auxilio clamé en vano,
aunque lo busqué doquier,
ni el amigo, ni el hermano,
me han podido socorrer;
pero tú, Jesús, me invitas
con cordial solicitud,
simpatizas en mis cuitas,
y me ofreces salud.

Heme, pues, en tu presencia;
líbrame de mi ansiedad;
que es tan grande tu potencia
como es grande tu piedad,
y jamás ha recurrido
si buen éxito a tu amor,
por descanso el afligido
por perdón el pecador.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-49-heme-aqui/)' where id = 'sa-himno-49-heme-aqui';
update public.songs set title = 'En El Curso de Este Día', lyrics = '', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-51-en-el-curso-de-este-dia/)
Letra pendiente: la fuente publicaba por error la letra del himno 50 («Un Buen Amigo»).' where id = 'sa-himno-51-en-el-curso-de-este-dia';
update public.songs set title = 'En La Ciudad de Dios', lyrics = 'En la ciudad de Dios
no cabe el pecador;
puro es su brillo,
puro es su brillo,
sin mancha en su fulgor.

Perdona con bondad
al pobre pecador;
lava mis culpas,
lava mis culpas,
bendito salvador.

Tu hijo quiero ser
por siempre mi Señor;
tú eres mi amparo,
tú eres mi amparo,
contra el vil tentador.

¡Oh! Cuando arriba esté
salvado por tu cruz,
puro y sin mancha,
puro y sin mancha,
veré tu hermosa luz.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-52-en-la-ciudad-de-dios/)' where id = 'sa-himno-52-en-la-ciudad-de-dios';
update public.songs set title = 'Ni en la Tierra', lyrics = 'Ni en la tierra ni en el cielo
un nombre hay como Jesús,
sobre todo él solo reina;
él sólo es eterna luz.

Jesús cura el alma mía,
médico del corazón;
en su amor encuentro alivio
en las penas y aflicción.

Es Jesús mi gran riqueza,
hallo en él todo bien.
Valen más que todo el oro
los tesoros de su Edén.

Es Jesús mi gran sustento,
mi pan suave y celestial,
de mis dichas y mi gozo
es mi rico manantial.

Jesús brinda, como el árbol,
fruto dulce como miel,
y separa de las almas
todo vicio y toda hiel.

Infinita es su ternura,
imposible de sondear,
con los ángeles hoy quiero
su grandeza pregonar.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-53-ni-en-la-tierra/)' where id = 'sa-himno-53-ni-en-la-tierra';
update public.songs set title = 'La Vida es Ficticia', lyrics = 'La vida es ficticia, efímera flor.
Del sol, a la tarde, la agotó el ardor,
antes que se mustie la debes llevar,
cual grata ofrenda, de Dios al altar.

Sí, desde la infancia hasta la vejez
se pasan los años con gran rapidez;
y llega la muerte sin verla venir,
y el alma, ¡ah! ¿quién sabe adónde ha de ir?

No esperes, no esperes a tu última edad;
conságrate joven al Dios de verdad;
pues pasando el tiempo lejos del Señor,
se enerva, se apaga nuestro ardiente amor.

Incierta es la hora de tu incierto fin;
y ¡ay! De aquel que tema de juicio el clarín
reflexiona, hombre, ¿qué de ti va a ser?
O eterna desdicha, o eterno placer.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-54-la-vida-es-ficticia/)' where id = 'sa-himno-54-la-vida-es-ficticia';
update public.songs set title = 'La Diestra del Excelso', lyrics = 'La diestra del excelso
mostróme su poder,
en la tenaz batalla
me ha ayudado a vencer;
ella me dio la vida,
y ya no he de morir,
porque de su excelencia
la gloria he de decir.

Cuando me vi afligido,
a Jehová clamé;
en su inefable nombre,
tan sólo tuve fe.
Él corrigió mis yerros,
viendo mi corazón,
y así veré la eterna
tierra de promisión.

A ti, Señor, deseo
mi canto aderezar;
sobre mi tosca lira
elevo mi cantar.
Del polvo levantado,
por tu poder me vi,
por eso, Dios eterno,
mi voz levanto a ti.

Sí, él del universo
es la piedra angular,
la redondez del mundo
es de Jehová el altar.
Cantemos, pues su gloria
en plácida canción,
y nuestras voces lleguen
a la eterna mansión.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-55-la-diestra-del-excelso/)' where id = 'sa-himno-55-la-diestra-del-excelso';
update public.songs set title = 'Venid, Venid Zagales', lyrics = 'Venid, venid zagales,
pastores de Belén,
venid, cantad la gloria
de Cristo nuestro bien.
Los ángeles pregonan
la gloria del Señor,
y la paz a los mortales,
de voluntad y amor.

La humana vestidura
encubre al inmortal;
y va a pagar la deuda
al padre celestial.
A redimirnos viene
viene él a padecer,
para acercar al hombre
al infinito ser.

¡Oh, amor, inexplicable,
sublime abnegación,
de aquél que en un pesebre
nos da su bendición!
Unid, pues, vuestras voces,
viajeros al Edén,
venid, cantad la gloria
de Cristo, nuestro bien.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-57-venid-venid-zagales/)' where id = 'sa-himno-57-venid-venid-zagales';
update public.songs set title = 'Obediente a Tu Mandato', lyrics = 'Obediente a tu mandato
participa hoy tu grey
de tu cena: y con gozo
acerquémonos con fe.
Lo que hiciste en el Calvario
por el pobre pecador,
anunciamos en tu nombre,
recordando tu amor.

Recordando tu angustia,
¡oh, divino redentor!
Y la copa de amargura
que por todo pecador
en el Gólgota apuraste,
despreciando tu dolor;
te pedimos que constantes
te sigamos con valor.

Gracias, ¡oh, Jesús! Te damos
en tu santa comunión.
En tu gracia disfrutamos
tu clemencia, tu favor;
tuya fue la cruz: mas nuestra
es la dicha, es la paz;
tuya es la gloria toda
y será por siempre jamás.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-58-obediente-a-tu-mandato/)' where id = 'sa-himno-58-obediente-a-tu-mandato';
update public.songs set title = 'Más Cerca', lyrics = 'Más cerca, ¡oh, Dios! De ti.
Más cerca, sí;
aunque sea una cruz
que me lleva a ti.
Será mi canto aquí.
“Más cerca, ¡oh, Dios! De ti,
más cerca, ¡oh, Dios! De ti,
más cerca de ti”.

Y si, cual Israel,
postrado esté
en piedras de Betel.
Aún allí
en sueño te veré,
y cerca de ti estaré,
más cerca, ¡oh, Dios! De ti,
muy cerca, sí.

La escala sigo yo
que al cielo va,
por gozo o por dolor
quiero ir allá.
Un ángel venga a mí
para llamarme a ti,
más cerca, ¡oh, Dios! De ti,
más cerca de ti.

Y luego al despertar
te alabaré;
de gracias un altar
levantaré;
mi corazón allí
más cerca esté de ti
más cerca esté de ti
más cerca, sí.

Y cuando al fenecer
volando allá,
con inmortal placer
te vea ya,
mi canto será así:
más cerca, ¡oh, Dios! De ti
más cerca, ¡oh, Dios! De ti
más cerca, sí.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-60-mas-cerca/)' where id = 'sa-himno-60-mas-cerca';
update public.songs set title = 'Es Cristo Mi Pastor', lyrics = 'Es Cristo mi pastor fiel,
no falta a mi alma él;
en verdes prados andaré,
y aguas mansas beberé.

{soc}
Me guía, me lleva él;
es mi amparo siempre fiel,
yo sé que me sostiene él,
Dios con nosotros, Emmanuel.
{eoc}

Enseñarame mi deber,
mi alma él hará volver
por sendas justas; el Señor
me guía siempre con amor

{soc}
Me guía, me lleva él;
es mi amparo siempre fiel,
yo sé que me sostiene él,
Dios con nosotros, Emmanuel.
{eoc}

Si en el valle, al pasar,
la sombra de la muerte está,
no temeré el mal jamás,
porque conmigo estarás.

{soc}
Me guía, me lleva él;
es mi amparo siempre fiel,
yo sé que me sostiene él,
Dios con nosotros, Emmanuel.
{eoc}

Tu vara es mi dirección,
y tu cayado salvación;
gozoso siempre estoy en ti,
Jesús, por su amor a mí.

{soc}
Me guía, me lleva él;
es mi amparo siempre fiel,
yo sé que me sostiene él,
Dios con nosotros, Emmanuel.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-62-es-cristo-mi-pastor/)' where id = 'sa-himno-62-es-cristo-mi-pastor';
update public.songs set title = 'De pie, De pie, Soldados', lyrics = 'De pie, de pie, soldados
de Cristo y de su cruz,
pendones desplegados
os da el rey Jesús.
En lid y en victoria
los suyos guiará;
compárteles su gloria
y el Señor será.

{soc}
De pie, soldados
de Cristo y de su cruz,
pendones desplegados
os da el rey Jesús.
{eoc}

¡de pie, de pie, soldados,
por más que sea atroz!
¿quién huye la batalla,
si Cristo da la voz?
Por esto fue herido
el santo hijo fiel;
por él habrás vencido,
y reinarás con él.

{soc}
De pie, soldados
de Cristo y de su cruz,
pendones desplegados
os da el rey Jesús.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-64-de-pie-de-pie-soldados/)' where id = 'sa-himno-64-de-pie-de-pie-soldados';
update public.songs set title = 'La Nave Evangelista', lyrics = 'La nave evangelista
marcha, marcha,
la nave evangelista
marcha para Canaán;
los que embarcarse quieran
quieran, quieran,
los que embarcarse quieran
bienvenidos sí serán.

{soc}
“gloria en las alturas”,
los de abordo cantan dulcemente.
“gloria en las alturas,
a nuestro capitán”.
{eoc}

Desembarcaron miles,
miles, miles;
desembarcaron miles
al buen puerto siglos ha;
y miles más navegan,
navegan, navegan,
y miles más navegan
por las mismas aguas ya.

{soc}
“gloria en las alturas”,
los de abordo cantan dulcemente.
“gloria en las alturas,
a nuestro capitán”.
{eoc}

El viento en popa vuela,
vuela, vuela,
el viento en popa, vuela
hacia aquel florido hogar;
felices voces se oyen
se oyen, se oyen
felices voces se oyen,
resonando por la mar.

{soc}
“gloria en las alturas”,
los de abordo cantan dulcemente.
“gloria en las alturas,
a nuestro capitán”.
{eoc}

Embárcate conmigo,
conmigo, conmigo,
embárcate conmigo,
mortal, cansado de pecar.
Descanso te prometo,
prometo, prometo,
descanso te prometo,
allá en aquel feliz lugar.

{soc}
“gloria en las alturas”,
los de abordo cantan dulcemente.
“gloria en las alturas,
a nuestro capitán”.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-65-la-nave-evangelista/)' where id = 'sa-himno-65-la-nave-evangelista';
update public.songs set title = 'Nos Veremos en el Rio', lyrics = 'Nos veremos en el río,
cuyas aguas cristalinas,
cuyas ondas argentinas
nacen del trono de Dios.

{soc}
¡Oh, sí! Nos congregaremos
en célica, hermosísima ribera
del río de la vida verdadera
que nace del trono de Dios.
{eoc}

En las márgenes del río
que frecuentan serafines
y embellecen querubines,
da la dicha eterna de Dios.

{soc}
¡Oh, sí! Nos congregaremos
en célica, hermosísima ribera
del río de la vida verdadera
que nace del trono de Dios.
{eoc}

El vergel que riega el río
de Jesús es la morada;
el mal nunca tiene entrada,
allí sólo reina Dios.

{soc}
¡Oh, sí! Nos congregaremos
en célica, hermosísima ribera
del río de la vida verdadera
que nace del trono de Dios.
{eoc}

Antes de llegar al río
nuestras cargas dejaremos,
libre todos entraremos
por la gracia del Señor.

{soc}
¡Oh, sí! Nos congregaremos
en célica, hermosísima ribera
del río de la vida verdadera
que nace del trono de Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-66-nos-veremos-en-el-rio/)' where id = 'sa-himno-66-nos-veremos-en-el-rio';
update public.songs set title = 'Santo, Santo, Santo', lyrics = '¡Santo! ¡Santo! ¡Santo! Señor omnipotente,
siempre el labio mío loores te dará;
¡Santo! ¡Santo! ¡Santo! Te adoro reverente.
Dios en tres personas, bendita Trinidad.

¡Santo! ¡Santo! ¡Santo! En número coro,
santos escogidos te adoran sin cesar,
de alegría llenos; y sus coronas de oro
rinden ante el trono y el cristalino mar.

¡Santo! ¡Santo! ¡Santo! La inmensa muchedumbre
de ángeles que cumplen tu santa voluntad;
ante ti, se postra, bañada de tu lumbre,
ante ti, que has sido, que eres y serás.

¡Santo! ¡Santo! ¡Santo! Por más que estás velado
e imposible sea tu gloria contemplar,
santo tú eres solo, nada hay a tu lado
en poder perfecto, pureza y caridad.

¡Santo! ¡Santo! ¡Santo! La gloria de tu nombre
vemos en tus obras en cielo, tierra y mar;
¡Santo! ¡Santo! ¡Santo! Te adorará todo hombre
Dios en tres personas bendita Trinidad.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-67-santo-santo-santo/)' where id = 'sa-himno-67-santo-santo-santo';
update public.songs set title = 'Oh, que Amigo nos es Cristo', lyrics = '¡Oh, qué amigo nos es Cristo!
Él llevó nuestro dolor
y nos manda que llevemos
todo a Dios en oración.
¿Está el hombre desprovisto
de paz, gozo y santo amor?
Esto es porque no llevamos
todo a Dios en oración.

¿Estás débil y cargado
de cuidados y temor?
A Jesús, refugio eterno
dile todo en oración.
¿Te desprecian tus amigos?
Cuéntaselo en oración;
en sus brazos
de amor tierno
paz tendrá tu corazón.

Jesucristo es nuestro amigo,
de esto pruebas nos mostró,
pues para llevar consigo
al culpable se humanó.
El castigo de su pueblo
en su muerte él sufrió;
Cristo es un amigo eterno,
sólo en él confío yo.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-68-oh-que-amigo-nos-es-cristo/)' where id = 'sa-himno-68-oh-que-amigo-nos-es-cristo';
update public.songs set title = 'Santa Biblia', lyrics = 'Santa Biblia, para mí
eres un tesoro aquí;
tú contienes con verdad,
la divina voluntad;
tú me dices lo que soy,
de quién vine y a quién voy.

Tú reprendes mi dudar.
Tú me exhortas sin cesar;
eres faro que a mi pie
va guiando por la fe,
a las fuentes del amor
del bendito salvador.

Eres infalible voz
del Espíritu de Dios,
que vigor al alma da
cuando en aflicción está;
tú me enseñas a triunfar
de la muerte y del pecar.

Por tu santa letra sé
que con Cristo reinaré;
yo que tan indigno soy,
por tu luz al cielo voy;
¡santa Biblia!, para mí
eres un tesoro aquí.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-69-santa-biblia/)' where id = 'sa-himno-69-santa-biblia';
update public.songs set title = 'Cuando Leo en la Biblia', lyrics = 'Ver quisiera sus manos sobre mi reposar
cariñosos abrazos de él sentir,
sus miradas disfrutar,
las palabras escuchar;
“a los niños dejad a mi venir”.

Todos los redimidos y salvados por él
al cordero celebran inmortal;
allí voces mil y mil
salen del coro infantil,
porque es de ellos al reino celestial.

¡Cuándo hay que no saben de esa bella mansión!
Y que no quieren a Jesús oír;
yo quisiérales mostrar
que para ellos hay lugar
en el cielo do los convida a ir.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-70-cuando-leo-en-la-biblia/)
Falta la primera estrofa: la fuente repetía por error una estrofa del himno 69 («Santa Biblia»).' where id = 'sa-himno-70-cuando-leo-en-la-biblia';
update public.songs set title = 'Oid un Son en Alta Esfera', lyrics = 'Oíd un son en alta esfera:
“¡en los cielos gloria a Dios!”,
al mortal paz en la tierra
canta la celeste voz.
Con los cielos alabemos,
al eterno rey cantemos
a Jesús a nuestro bien.
Con el coro de Belén;
canta la celeste voz:
“¡en los cielos gloria a Dios!”.

El Señor de los señores,
el ungido celestial,
a salvar los pecadores
bajó al seno virginal.
Loor al verbo encarnado,
en humanidad velado:
gloria al santo de Israel,
cuyo nombre es Emmanuel;
canta la celeste voz;
“¡en los cielos gloria a Dios!”.

Príncipe de paz eterna,
gloria a ti, a ti, Jesús,
entregando el alma tierna,
tú nos traes vida y luz;
has tu majestad dejado,
y buscarnos te has dignado;
para darnos el vivir
a la muerte quieres ir;
canta la celeste voz:
“¡en los cielos gloria a Dios!”.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-73-oid-un-son-en-alta-esfera/)' where id = 'sa-himno-73-oid-un-son-en-alta-esfera';
update public.songs set title = 'Tentado, No Cedas', lyrics = 'Tentado no cedas; ceder es pecar,
más fácil será luchando triunfar.
¡Valor! pues, gustoso domina tu mal.
Jesús librar puede de asalto mortal.

{soc}
A Jesús pues, acude,
en sus brazos tu alma
hallará dulce calma;
él te hará vencedor.
{eoc}

Evita el pecado, procura agradar
a Dios a quien debes por siempre ensalzar:
no mancha tus labios impúdica voz,
tu corazón guarda de codicia atroz.

{soc}
A Jesús pues, acude,
en sus brazos tu alma
hallará dulce calma;
él te hará vencedor.
{eoc}

Amante, benigno y enérgico sé;
en Cristo ten siempre indómita fe;
veraz sea tu dicho, de Dios es tu ser;
corona te espera y vas a vencer.

{soc}
A Jesús pues, acude,
en sus brazos tu alma
hallará dulce calma;
él te hará vencedor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-80-tentado-no-cedas/)' where id = 'sa-himno-80-tentado-no-cedas';
update public.songs set title = 'Día Feliz', lyrics = 'Día feliz, cuando escogí
servirte, mi Señor y Dios;
preciso es que mi gozo en ti
lo muestres hoy
con obra y voz.

{soc}
¡Soy feliz! ¡soy feliz!
Y en tu favor me gozaré.
En libertad y luz me vi
cuando triunfó en mi la fe,
y el raudal carmesí
salud de mi alma
enferma fue.
{eoc}

¡Pasó mi gran deber, cumplí;
de Cristo soy, y mío es él!
Me atrajo con placer, seguí
su voz, conoce todo fiel.

{soc}
¡Soy feliz! ¡soy feliz!
Y en tu favor me gozaré.
En libertad y luz me vi
cuando triunfó en mi la fe,
y el raudal carmesí
salud de mi alma
enferma fue.
{eoc}

Reposa, débil corazón,
a tus contiendas pon ya fin;
hallé más noble posesión,
y parte en superior festín.

{soc}
¡Soy feliz! ¡soy feliz!
Y en tu favor me gozaré.
En libertad y luz me vi
cuando triunfó en mi la fe,
y el raudal carmesí
salud de mi alma
enferma fue.
{eoc}

Solemne voto, ofrenda flor,
que al cielo santo consagré,
hoy sé mi vínculo de honor,
después testigo de mi fe.

{soc}
¡Soy feliz! ¡soy feliz!
Y en tu favor me gozaré.
En libertad y luz me vi
cuando triunfó en mi la fe,
y el raudal carmesí
salud de mi alma
enferma fue.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-82-dia-feliz/)' where id = 'sa-himno-82-dia-feliz';
update public.songs set title = 'Trabajad, Trabajad', lyrics = '¡Trabajad! ¡trabajad! Somos siervos de Dios
seguiremos la senda que el maestro trazó;
renovando las fuerzas con bienes que da,
el deber que nos toca, cumplido será.

{soc}
¡Trabajad! ¡trabajad!
¡esperad y velad!
¡confiad! ¡siempre orad!
Que el maestro pronto volverá.
{eoc}

¡Trabajad! ¡trabajad! Hay que dar de comer,
al que pan de la vida quisiera tener;
hay enfermos que irán a los pies del Señor
al saber que de balde los sana su amor.

{soc}
¡Trabajad! ¡trabajad!
¡esperad y velad!
¡confiad! ¡siempre orad!
Que el maestro pronto volverá.
{eoc}

¡Trabajad! ¡trabajad! Fortaleza pedid;
el reinado del mal con valor combatid;
conducid los cautivos al libertador,
y decid que de balde redime su amor.

{soc}
¡Trabajad! ¡trabajad!
¡esperad y velad!
¡confiad! ¡siempre orad!
Que el maestro pronto volverá.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-83-trabajad-trabajad/)' where id = 'sa-himno-83-trabajad-trabajad';
update public.songs set title = 'Firmes y Adelante', lyrics = '¡Firmes y adelante!
Huestes de la fe,
sin temor alguno,
que Jesús nos ve.
Jefe soberano
Cristo al frente va,
y la regia enseña
tremolando está.

{soc}
Firmes y adelante
huestes de la fe,
sin temor alguno,
que Jesús nos ve.
{eoc}

Al sagrado nombre
de nuestro adalid,
tiembla el enemigo
y huye de la lid.
Nuestra es la victoria
dad a Dios loor;
y óigalo el averno
lleno de pavor.

{soc}
Firmes y adelante
huestes de la fe,
sin temor alguno,
que Jesús nos ve.
{eoc}

Muévase potente
la iglesia de Dios;
de los ya gloriosos
marchamos en pos.
Somos sólo un cuerpo,
y uno es el Señor,
una la esperanza,
y uno nuestro amor.

{soc}
Firmes y adelante
huestes de la fe,
sin temor alguno,
que Jesús nos ve.
{eoc}

Tronos y coronas
pueden perecer,
de Jesús la iglesia
constante ha de ser.
Nada en contra suya
prevalecerá
porque la promesa
nunca faltará.

{soc}
Firmes y adelante
huestes de la fe,
sin temor alguno,
que Jesús nos ve.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-85-firmes-y-adelante/)' where id = 'sa-himno-85-firmes-y-adelante';
update public.songs set title = 'El Trono Santo', lyrics = 'Del trono santo en derredor
niñitos mil están
que rescatados del Señor
allí loor le dan.

{soc}
Cantan “¡gloria, gloria
aleluya al santo Dios!”
{eoc}

¿Cómo al mundo superior
aquella Sion sin par,
en donde es todo paz y amor,
han podido llegar?.

{soc}
Cantan “¡gloria, gloria
aleluya al santo Dios!”
{eoc}

Porque el Señor su sangre dio,
en precio de expiación,
con ella los purificó
por grande compasión.

{soc}
Cantan “¡gloria, gloria
aleluya al santo Dios!”
{eoc}

Buscaron ellos a Jesús,
su nombre amando aquí;
y ahora ya en clara luz
su rostro ven allí.

{soc}
Cantan “¡gloria, gloria
aleluya al santo Dios!”
{eoc}

Ropaje blanco de esplendor
cada uno viste allí;
están allá con el Señor,
eternamente así.

{soc}
Cantan “¡gloria, gloria
aleluya al santo Dios!”
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-87-el-trono-santo/)' where id = 'sa-himno-87-el-trono-santo';
update public.songs set title = 'En La Célica Morada', lyrics = 'En la célica morada
de las cumbres del Edén,
donde cada voz ensalza
al autor de todo bien.
¿El pesar recordaremos,
y la triste nublazón,
tantas luchas del espíritu
con el débil corazón?.

{soc}
Sí, allí será gratísimo
en el proceder pensar
del pastor fiel y benéfico
que nos ayudó a llegar.
{eoc}

Oración, deberes, penas,
vías que anduvimos ya
poseyendo las riquezas
que Jesús nos guarda allá,
¿La memoria retendremos
a cubierto del dolor,
del camino largo, aspérrimo,
con sus luchas, su temor?

{soc}
Sí, allí será gratísimo
en el proceder pensar
del pastor fiel y benéfico
que nos ayudó a llegar.
{eoc}

La bondad con que nos mira
sin cansarse cuando ve
poco fruto en nuestras vidas
y tan débil nuestra fe.
¿Nos acordaremos de ella,
en aquel dichoso hogar
de eternal aurora espléndida
e inefable bienestar?

{soc}
Sí, allí será gratísimo
en el proceder pensar
del pastor fiel y benéfico
que nos ayudó a llegar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-88-en-la-celica-morada/)' where id = 'sa-himno-88-en-la-celica-morada';
update public.songs set title = 'Lejos de mi Padre Dios', lyrics = 'Lejos de mi padre Dios
por mi Jesús hallado,
por su gracia y por su amor
sólo fui salvado.

{soc}
Es Jesús, mi Señor,
es mi gloria eterna;
él me amo y me salvó
en su gracia tierna.
{eoc}

En Jesús, mi salvador,
pongo mi confianza;
toda mi necesidad
suple en abundancia.

{soc}
Es Jesús, mi Señor,
es mi gloria eterna;
él me amo y me salvó
en su gracia tierna.
{eoc}

Cerca de mi buen pastor
vivo cada día;
toda gracia en su Señor
halla el alma mía.

{soc}
Es Jesús, mi Señor,
es mi gloria eterna;
él me amo y me salvó
en su gracia tierna.
{eoc}

Guárdame, Señor Jesús,
para que no caiga,
como sarmiento en la vid,
vida en ti traiga.

{soc}
Es Jesús, mi Señor,
es mi gloria eterna;
él me amo y me salvó
en su gracia tierna.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-89-lejos-de-mi-padre-dios/)' where id = 'sa-himno-89-lejos-de-mi-padre-dios';
update public.songs set title = 'Ved que Acercándose', lyrics = 'Ved, que acercándose el día va
en que el Señor en su gloria vendrá
a recoger en su alfolí
lo que sembramos en tanto aquí.
Él su fruto recogerá,
sí, su fruto recogerá.

{soc}
Vamos sembrando con vivo amor
dulce palabra del buen salvador,
obrando siempre con celo y con fe,
para que rica cosecha nos dé.
{eoc}

Entre zarzales podrá caer
cierta semilla y no florecer;
mas el Señor a segar vendrá,
y su buen fruto recogerá,
él su fruto recogerá
sí, su fruto recogerá.

{soc}
Vamos sembrando con vivo amor
dulce palabra del buen salvador,
obrando siempre con celo y con fe,
para que rica cosecha nos dé.
{eoc}

Muy largo tiempo podrá pasar
antes de ver su semilla brotar;
mas ciertamente el Señor vendrá,
y su buen fruto recogerá.
Él su fruto recogerá,
sí, su fruto recogerá.

{soc}
Vamos sembrando con vivo amor
dulce palabra del buen salvador,
obrando siempre con celo y con fe,
para que rica cosecha nos dé.
{eoc}

En todo tiempo, sin desmayar,
vamos sembrando y orando a la par
pues prestamente el Señor vendrá
él su fruto recogerá;
y su buen fruto recogerá,
sí, su fruto recogerá.

{soc}
Vamos sembrando con vivo amor
dulce palabra del buen salvador,
obrando siempre con celo y con fe,
para que rica cosecha nos dé.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-90-ved-que-acercandose/)' where id = 'sa-himno-90-ved-que-acercandose';
update public.songs set title = 'Oh, Soldados De Los Cielos', lyrics = '¡Oh, soldados de los cielos
ved la señal ya!
Hay refuerzos, nuestro el triunfo,
no dudéis, será.

{soc}
“¡firmes!¡firmes! Yo voy pronto”
clama el salvador;
estaremos por tu gracia
firmes con valor.
{eoc}

Nada importa nos asedien
con rugiente afán
las legiones aguerridas
que ordenó Satán.

{soc}
“¡firmes!¡firmes! Yo voy pronto”
clama el salvador;
estaremos por tu gracia
firmes con valor.
{eoc}

Tremolando se divisa
el marcial pendón,
y se escucha de cornetas
el guerrero son.

{soc}
“¡firmes!¡firmes! Yo voy pronto”
clama el salvador;
estaremos por tu gracia
firmes con valor.
{eoc}

Viene el Cristo con potencia
a salvar su grey;
pues, soldados, ¡alegría!
¡viva nuestro rey!

{soc}
“¡firmes!¡firmes! Yo voy pronto”
clama el salvador;
estaremos por tu gracia
firmes con valor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-91-oh-soldados-de-los-cielos/)' where id = 'sa-himno-91-oh-soldados-de-los-cielos';
update public.songs set title = '¿Te Sientes Casi Resuelto Ya?', lyrics = '¿Te sientes casi resuelto ya?
¿Te falta poco para creer?
¿por qué pues, dices a Jesucristo?
“hoy no, mañana te seguiré”

¿Te sientes casi, resuelto ya?
Pues vence el casi, a Cristo ven;
que hoy es tiempo, mas el mañana
sobrando tarde pudiera ser.

Sabes que el casi no es de valor
en la presencia del justo juez
¡ay del que muere casi creyendo!
Completamente perdido es.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-92-te-sientes-casi-resuelto-ya/)' where id = 'sa-himno-92-te-sientes-casi-resuelto-ya';
update public.songs set title = 'A Jesucristo Ven Sin Tardar', lyrics = 'A Jesucristo ven sin tardar;
que ente nosotros hoy él está,
y te convida con dulce afán
tierno, diciendo: “ven”.

{soc}
¡Oh, cuán grata
es nuestra reunión!,
cuando allá,
Señor, en tu mansión
contigo estemos es comunión,
gozando eterno bien.
{eoc}

Piensa que él sólo
puede colmar
tu triste pecho de gozo y paz;
y porque anhela tu bienestar
vuelve a decirte: “ven”.

{soc}
¡Oh, cuán grata
es nuestra reunión!,
cuando allá,
Señor, en tu mansión
contigo estemos es comunión,
gozando eterno bien.
{eoc}

Su voz escucha sin vacilar,
y grato acepta
lo que hoy te da:
tal vez mañana
no habrá lugar;
no te detengas, ven.

{soc}
¡Oh, cuán grata
es nuestra reunión!,
cuando allá,
Señor, en tu mansión
contigo estemos es comunión,
gozando eterno bien.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-93-a-jesucristo-ven-sin-tardar/)' where id = 'sa-himno-93-a-jesucristo-ven-sin-tardar';
update public.songs set title = 'Dicha Grande', lyrics = 'Dicha grande es la del hombre
cuyas sendas rectas son;
lejos de los pecadores,
lejos de la tentación.
A los malos consejeros
deja, porque teme el mal;
huye de la burladora
gente impía e inmortal.

Antes en la ley divina
cifra su mayor placer,
meditando día y noche
en su divinal saber.
Este, como el árbol verde
bien regado y en sazón,
frutos abundantes rinde
y hojas que perennes son.

Cuando emprenda es prosperado,
duradero le es el bien;
muy diversos resultados
sacan lo que nada creen,
pues los lanza como el tamo
que el ciclón arrebató,
de pasiones remolino
que a millones destruyó.

En el juicio ningún malo
por lo tanto se alzará;
entre justos congregados
insensatos nunca habrá;
porque Dios la vía mira
por lo cual los suyos van;
otra es la de los impíos,
que al infierno bajarán.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-96-dicha-grande/)' where id = 'sa-himno-96-dicha-grande';
update public.songs set title = 'Salvo Navego', lyrics = 'Salvo navego
en la nave “salud”
¡cantando el nombre
del bendito Jesús!
La proa puesta al Edén celestial
rápida se aleja de este mundo mortal.

{soc}
Su ruta al cielo,
su enseña la cruz,
ya leva el áncora
la nave “salud”;
todos subid a bordo
sin temer al mar;
que Jesús la manda,
el mejor capitán.
{eoc}

Diestro el piloto,
surcará el fiero mar,
sin que la nave
llegue a zozobrar;
no hay dicha igual
a la del alma en Jesús,
salva por su sangre navegando en su luz.

{soc}
Su ruta al cielo,
su enseña la cruz,
ya leva el áncora
la nave “salud”;
todos subid a bordo
sin temer al mar;
que Jesús la manda,
el mejor capitán.
{eoc}

No más pecar:
ser quiero ya del Señor,
mi regla sea
su evangelio de amor;
pronto, muy pronto, llegaré a Canaán:
¡gloria a Jesucristo, celestial capitán!

{soc}
Su ruta al cielo,
su enseña la cruz,
ya leva el áncora
la nave “salud”;
todos subid a bordo
sin temer al mar;
que Jesús la manda,
el mejor capitán.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-97-salvo-navego/)' where id = 'sa-himno-97-salvo-navego';
update public.songs set title = 'Más Que Vencer', lyrics = 'Más que vencer, tal es nuestra divisa,
nuestra bandera es la persecución;
para la fe no hay batalla indecisa,
para el cristiano no hay condenación.

Nuestro caudillo salió victorioso,
en el Calvario su triunfo se ve,
todos sigamos al jefe glorioso:
nuestra mirada es su cruz fija esté.

Con él sufriendo, con él reinaremos,
no nos arredra del mundo el furor;
buen testimonio de Cristo daremos,
nuestra esperanza es el fiel salvador.

¡Animo, amigos! Poder invisible
nos comunica Jesús por su cruz,
el rey de reyes es jefe invencible,
¡más que vencer por la muerte a la luz!', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-98-mas-que-vencer/)' where id = 'sa-himno-98-mas-que-vencer';
update public.songs set title = 'Para Todo Viajero', lyrics = 'Para todo viajero
que camina con tesón
por la senda que conduce
a los brazos de su Dios,
hay un faro luminoso
que le presta su fulgor:
es el santo Jesucristo,
el bendito salvador.

Para aquel a quien el mundo
desgarró su corazón,
deshojó sus ilusiones,
y su alma marchitó;
hay un bálsamo divino
que le da consolación;
es el santo Jesucristo
el bendito salvador.

Para aquel que ya perdido
por el mal que practicó,
de su suerte desesperada
pereciendo de dolor,
hay un protector divino
que le mira con amor:
es el santo Jesucristo,
el bendito salvador.

Para el huérfano que solo
en la tierra se quedó,
y suspira por un alma
que le cuide con amor,
hay un padre cariñoso
de infinita compasión:
es el santo Jesucristo,
el bendito salvador.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-99-para-todo-viajero/)' where id = 'sa-himno-99-para-todo-viajero';
update public.songs set title = 'Gozo La Santa Palabra Leer', lyrics = 'Gozo la santa palabra leer,
cosas preciosas allí puedo ver;
y sobre todo que el gran redentor
es de los niños el tierno pastor.

{soc}
Con alegría yo cantaré
al redentor, tierno pastor
que en el Calvario por mí murió
sí, sí, por mí murió.
{eoc}

Me ama Jesús, pues su vida entregó
por mi salud y de niños habló:
“dejad los niños que vengan a mí;
para salvarlos mi sangre vertí”.

{soc}
Con alegría yo cantaré
al redentor, tierno pastor
que en el Calvario por mí murió
sí, sí, por mí murió.
{eoc}

Si alguien pregunta que cómo lo sé,
busca a Jesús, pecador, le diré;
“por su palabra que tienes aquí
aprende y siente que te ama él a ti”.

{soc}
Con alegría yo cantaré
al redentor, tierno pastor
que en el Calvario por mí murió
sí, sí, por mí murió.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-102-gozo-la-santa-palabra-leer/)' where id = 'sa-himno-102-gozo-la-santa-palabra-leer';
update public.songs set title = 'Dad Loor a Dios', lyrics = 'Dad loor a Dios, himnos elevad
alabando su bondad;
canta de Jesús, pobre pecador,
canta sí, su gran amor.
Jesucristo descendió
de los cielos a Belén,
nuestra paz allí nació;
nuestra dicha, luz y bien.

{soc}
¡Oh, bendito Dios!
Gloria a ti, Señor,
por Jesús, el salvador.
{eoc}

Dad loor a Dios, himnos elevad
alabando su bondad;
canta de Jesús, pobre pecador,
canta sí, su gran amor.
Por venir a padecer
a los ángeles dejó.
Y nacido de mujer
con los hombre habitó.

{soc}
¡Oh, bendito Dios!
Gloria a ti, Señor,
por Jesús, el salvador.
{eoc}

Dad loor a Dios, himnos elevad,
alabando su bondad;
canta a Jesús, pobre pecador,
canta sí, su gran amor.
En el patíbulo cruel
dio su vida celestial,
porque tenga luz en él
todo mísero mortal.

{soc}
¡Oh, bendito Dios!
Gloria a ti, Señor,
por Jesús, el salvador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-103-dad-loor-a-dios/)' where id = 'sa-himno-103-dad-loor-a-dios';
update public.songs set title = 'Tocad Trompeta Ya', lyrics = 'Tocad trompeta ya,
alegres en Sion:
al mundo publicad
eterna redención;
“este es el año de bondad,
volved a vuestra libertad”.

Jesús, el redentor
hizo propiciación:
afuera con dolor,
sonadles la canción;
“este es el año de bondad,
volved a vuestra libertad”.

A Jesús anunciad:
decidles que murió;
de la mortalidad
los lazos ya rompió.
“este es el año de bondad,
volved a vuestra libertad”.

Vosotros que el favor
del cielo despreciáis,
ved que por el amor
de Cristo lo cobráis;
“este es el año de bondad,
volved a vuestra libertad”.

Llamadles, ¡oh! Llamad;
id, ofrecedles paz;
es tarde apresurad,
que vuelvan su faz.
“Este es el año de bondad,
volved a vuestra libertad”.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-105-tocad-trompeta-ya/)' where id = 'sa-himno-105-tocad-trompeta-ya';
update public.songs set title = 'Sagrado Es El Amor', lyrics = 'Sagrado es el amor
que ya nos une aquí,
porque creemos del Señor
la voz que llama así.

A nuestro Padre Dios
rogamos con fervor,
alúmbrenos la misma luz,
consuele el mismo amor.

Penoso es esperar,
mas nuestra firme unión
jamás podráse quebrantar
por la separación.

Dicho día vendrá,
que nos ha de reunir,
que Dios nos lo conceda, hará
el férvido pedir.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-106-sagrado-es-el-amor/)' where id = 'sa-himno-106-sagrado-es-el-amor';
update public.songs set title = 'Siempre Aquí Reposaré', lyrics = 'Siempre aquí reposaré,
Señor, cerca de ti;
en esto sólo esperaré:
Jesús murió por mí.

Bendito Dios, mi salvador,
gran fuente del perdón;
con sangre lava al pecador
y limpia el corazón.

¡Oh, lávame, y tuyo seré,
precioso salvador;
¡oh, lávame y viviré
siempre en tu fiel amor.

De sangre tuya sin cesar
aplícame el poder;
hasta sueños en adorar
y fe se cambie en ver.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-107-siempre-aqui-reposare/)' where id = 'sa-himno-107-siempre-aqui-reposare';
update public.songs set title = 'A Cristo Doy Mi Canto', lyrics = 'A Cristo doy mi canto;
él salva el alma mía,
me libra de quebranto
y con amor me guía.

{soc}
Ensalce nuestro canto
su sacrosanta historia;
es nuestro anhelo santo
mirar, Jesús, tu gloria.
{eoc}

Jamás dolor ni agravios
enlutarán la mente;
si a Cristo nuestros labios
bendicen dulcemente.

{soc}
Ensalce nuestro canto
su sacrosanta historia;
es nuestro anhelo santo
mirar, Jesús, tu gloria.
{eoc}

Tu nombre bendecido
alegra el alma mía;
tu nombre es en mi oído
dulcísima armonía.

{soc}
Ensalce nuestro canto
su sacrosanta historia;
es nuestro anhelo santo
mirar, Jesús, tu gloria.
{eoc}

Viviendo he de ensalzarte,
y si abandono el suelo,
véranme ir adorarte
los ángeles del cielo.

{soc}
Ensalce nuestro canto
su sacrosanta historia;
es nuestro anhelo santo
mirar, Jesús, tu gloria.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-108-a-cristo-doy-mi-canto/)' where id = 'sa-himno-108-a-cristo-doy-mi-canto';
update public.songs set title = '¿Qué Me Importa del Mundo las Penas?', lyrics = '¿Qué me importa del mundo las penas,
y doblada tener la cerviz?
¿Qué me importa si esté en cadenas,
si me espera una patria feliz?
Resignado, tranquilo y dichoso,
de la aurora me encuentra la luz
porque sé que Jesús bondadoso
por su pueblo ha expirado en la cruz.

Y del preso las horas se ahuyentan
en gratísimo y blando solaz;
con la Biblia mis males se ausentan,
de la dicha me encuentro capaz.
¡Libro santo! Mi estancia ilumina;
nunca, nunca te apartes de mí!
Que aprendiendo tu bella doctrina,
no hay males ni penas aquí.

¡Evangelio sublime, adorado!
¡Bello pacto de amor sin igual!
Quiero siempre tenerte a mi lado;
y mirarte cual puro fanal.
Aunque esté moribundo y rendido
el que acude con fe al salvador,
en cualquier circunstancia es oído
y aceptado con férvido amor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-111-que-me-importa-del-mundo-las-penas/)' where id = 'sa-himno-111-que-me-importa-del-mundo-las-penas';
update public.songs set title = 'Dejé Mis Penas', lyrics = 'Dejé mis penas todas a Jesús,
y clavó mis pecados en su cruz,
el magnifico día que por fe
en la cruz por salvarme le miré.

Él la carga terrible
de mis hombros quitó
y su voz apacible
mi dolor disipó.

Dejé mis penas todas al Señor,
porque quita a las penas su amargor,
y las lágrimas dora del mortal
con su tierna sonrisa celestial.

El desierto miramos
que se torna vergel,
cuando peregrinamos
apoyados en él.

Dejé mis penas todas al Señor,
de mi siempre benigno protector;
en el puerto seguro al fin anclé:
y reposo en sus aguas encontré.

Tengo en él mi consuelo,
es mi guía, mi luz,
y vivir en el cielo
es vivir con Jesús.

Acude con penas al Señor,
alma martirizada del dolor,
a su lado la dicha lograrás
y librada de angustias vivirás.

En su seno divino
hay lugar para ti;
y seguro destino
alma tienes allí.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-112-deje-mis-penas/)' where id = 'sa-himno-112-deje-mis-penas';
update public.songs set title = 'Todos Los Que Tengan Sed', lyrics = 'Todos los que tengan sed
beberán, beberán:
vengan cuantos pobres hay;
comerán, comerán;
no malgastéis el haber:
¡compren verdadero pan!
Si a Jesús acuden hoy
gozarán, gozarán.

Si le prestan atención,
les dará, les dará
parte en su pactado bien,
eternal, eternal.
Con el místico David,
rey, maestro, capitán,
de las huestes que al Edén
llevará llevará.

Como baja bienhechor
sin volver, sin volver,
riego que las nubes dan.
Ha de ser, ha de ser
la palabra del Señor
productivo, pleno bien,
vencedora al fin será
por la fe, por la fe.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-113-todos-los-que-tengan-sed/)' where id = 'sa-himno-113-todos-los-que-tengan-sed';
update public.songs set title = 'Gloria a Nuestro Salvador', lyrics = 'Gloria a nuestro salvador por su gran salvación;
gloria tributemos en la sala de oración;
gloria cantaremos en canción de fuerte son;
¡yo soy salvado en Cristo!

{soc}
¡Salud!, ¡salud! Cantad a nuestro Dios:
la paz nos da; clamad en alta voz:
salvación ya tengo y descanso dulce en él.
¡Yo soy salvado en Cristo!
{eoc}

Vengo a tus pies, Jesús, con llanto y dolor;
misericordia te de mí, un pobre pecador,
sálvame y te daré mi vida en loor.
¡Él me salvo, tierno Cristo!

{soc}
¡Salud!, ¡salud! Cantad a nuestro Dios:
la paz nos da; clamad en alta voz:
salvación ya tengo y descanso dulce en él.
¡Yo soy salvado en Cristo!
{eoc}

Debo, pues, mi vida y mis fuerzas todo a ti;
y las doy con gratitud y alegría, sí,
gratitud a ti, que diste vida para mí;
¡mi salvador, Jesucristo!

{soc}
¡Salud!, ¡salud! Cantad a nuestro Dios:
la paz nos da; clamad en alta voz:
salvación ya tengo y descanso dulce en él.
¡Yo soy salvado en Cristo!
{eoc}

Dad la voz al pecador que anda sin sostén;
sin la paz –buscándola- decir: “a Cristo ven:
él que me salvó te ama, ¡oh, sálvate también!
Cree en la sangre de Cristo”.

{soc}
¡Salud!, ¡salud! Cantad a nuestro Dios:
la paz nos da; clamad en alta voz:
salvación ya tengo y descanso dulce en él.
¡Yo soy salvado en Cristo!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-114-gloria-a-nuestro-salvador/)' where id = 'sa-himno-114-gloria-a-nuestro-salvador';
update public.songs set title = 'Tú Dejaste Tu Trono', lyrics = 'Tú dejaste tu trono y corona por mí,
al venir a Belén a nacer;
mas a ti no fue dado el entrar al mesón,
y en pesebre te hicieron nacer.

{soc}
Ven a mi corazón, ¡oh, Cristo!
Pues, en él hay un lugar para ti;
ven a mi corazón, ¡oh, Cristo!, ven
pues, en él hay un lugar para ti.
{eoc}

Alabanzas celestes los ángeles dan
en que rinden al verbo loor;
mas humilde viniste a la tierra, Señor
a dar la vida al más vil pecador.

{soc}
Ven a mi corazón, ¡oh, Cristo!
Pues, en él hay un lugar para ti;
ven a mi corazón, ¡oh, Cristo!, ven
pues, en él hay un lugar para ti.
{eoc}

Siempre pueden las zorras sus cuevas tener,
y las aves sus nidos también;
mas el hijo del hombre no tuvo un lugar,
en el cual reclinara su sien.

{soc}
Ven a mi corazón, ¡oh, Cristo!
Pues, en él hay un lugar para ti;
ven a mi corazón, ¡oh, Cristo!, ven
pues, en él hay un lugar para ti.
{eoc}

Tú viniste, Señor, con tu gran bendición,
para dar libertad y salud;
mas con odio y desprecio te hicieron morir,
aunque vieron tu amor y virtud.

{soc}
Ven a mi corazón, ¡oh, Cristo!
Pues, en él hay un lugar para ti;
ven a mi corazón, ¡oh, Cristo!, ven
pues, en él hay un lugar para ti.
{eoc}

Alabanzas sublimes los cielos darán
cuando vengas glorioso de allá.
Y tu voz entre nubes dirá: “ven a mí”,
que hay lugar junto a mí para ti”.

{soc}
Ven a mi corazón, ¡oh, Cristo!
Pues, en él hay un lugar para ti;
ven a mi corazón, ¡oh, Cristo!, ven
pues, en él hay un lugar para ti.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-117-tu-dejaste-tu-trono/)' where id = 'sa-himno-117-tu-dejaste-tu-trono';
update public.songs set title = 'Venid Niños', lyrics = 'Venid, niños, todos, venid sin tardar
corred al pesebre en Belén, a admirar
del padre en los cielos el don sin igual;
¡a él sea la gloria, la paz al mortal!

Ved sobre el pesebre de un pobre portal
lindísimo niño en blanco pañal;
un rayo ilumina su rostro infantil,
en vez de la púrpura, sirve heno vil.

Mirad en su cuña, niñitos, su paz,
José con maría contemplan su faz;
hay píos pastores orando alrededor;
en lo alto mil ángeles cantan loor.

También, niños, con los pastores orad;
con ellos dad gracias, las manos alzad,
al coro celeste las voces unid,
del padre y del hijo el amor bendecid.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-118-venid-ninos/)' where id = 'sa-himno-118-venid-ninos';
update public.songs set title = 'Con Voz Benigna', lyrics = 'Con voz benigna te llama Jesús,
invitación de puro amor.
¿por qué le dejas en vano llamar?
¿sordo serás pecador?

{soc}
Hoy te convida
hoy te convida
voz bendecida
benigna convídate hoy.
{eoc}

A los cansados convida Jesús;
con compasión mira el dolor;
tráele tu carga; te la llevará
bendeciráte el Señor.

{soc}
Hoy te convida
hoy te convida
voz bendecida
benigna convídate hoy.
{eoc}

Siempre aguardando, contempla a Jesús
¡tanto esperar! ¡con tanto amor!
Hasta sus plantas ven, mísero, y trae
tu tentación, tu dolor.

{soc}
Hoy te convida
hoy te convida
voz bendecida
benigna convídate hoy.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-119-con-voz-benigna/)' where id = 'sa-himno-119-con-voz-benigna';
update public.songs set title = 'Bendita Hora de Oración', lyrics = 'Bendita hora de oración,
que del contacto mundanal
elévame hasta la mansión
de mi buen padre celestial.
Huyendo toda tentación,
acudo al templo del Señor,
lleno de paz y bendición,
a orar allí con fino amor.

Bendita voz, santa oración,
a quien escucha con bondad
dirijo aquí mi petición,
a Dios que es única verdad.
Confiado estoy en tu atención
a mi plegaria, a mi clamor,
pues ya me ha dado salvación
y pruebas grandes de amor.

¡oh, padre!, fuente de salud,
a tu gran nombre siempre honor;
tu reino venga que tu luz
por todo esparza su fulgor.
Hoy danos tu pan celestial,
perdona nuestra tibia fe,
y guárdanos de todo mal,
¡oh, tú de gloria eterno rey!', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-121-bendita-hora-de-oracion/)' where id = 'sa-himno-121-bendita-hora-de-oracion';
update public.songs set title = 'Castillo Fuerte', lyrics = 'Castillo fuerte es nuestro Dios,
defensa y buen escudo;
con su poder nos librará
en este trance agudo.
Con furia y con afán,
acósanos Satán:
por armas deja ver
astucia y gran poder;
cual él no hay en al tierra.

Nuestro valor no es nada aquí,
con él todo es perdido,
mas por nosotros pugnará
de Dios el escogido.
¿sabéis quién es? Jesús,
el que venció en la cruz.
Señor de sabaoth,
pues sólo él es Dios;
el triunfa en ala batalla.

Aunque estén demonio mil
pronto a devorarnos,
no temeremos, porque Dios
sabrá aún prosperarnos.
Que muestre su vigor
Satán y su furor,
dañarnos no podrá,
pues condenado es ya
por la palabra santa.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-122-castillo-fuerte/)' where id = 'sa-himno-122-castillo-fuerte';
update public.songs set title = 'Miré con Ansia', lyrics = 'Miré con ansia en derredor,
mar tempestuoso, negro, vi;
mas vino son consolador;
Jesús me dijo: “ven a mí”.

Me dijo: “yo te salvaré,
si crees que yo te redimí”.
¡cuán dulce fiar en Cristo fue!
Cuando él me dijo: “ven a mí”

“ven porque todo morirá.
No puedes más quedarte aquí;
tu patria, el cielo, arriba está,
yo soy la puerta, ven a mí”.

Tu voz, Jesús, de tierno amor,
me lleva siempre en pos de ti;
olvido penas y dolor,
pues tú me dices: “ven a mí”.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-126-mire-con-ansia/)' where id = 'sa-himno-126-mire-con-ansia';
update public.songs set title = 'Oh, vuelve, Vuelve', lyrics = 'Oh, vuelve, vuelve, pecador,
te espera el padre Dios,
lejos de él, tu salvador,
ningún bien hallarás.

{soc}
Te busca el salvador,
te llama hoy en amor;
oh, ven a él sin más vacilar,
te quiere perdonar.
{eoc}

Sí, vuelve, triste pecador,
Jesús murió por ti,
y él te llama en tu dolor;
responde: “heme aquí”.

{soc}
Te busca el salvador,
te llama hoy en amor;
oh, ven a él sin más vacilar,
te quiere perdonar.
{eoc}

¡oh! Vuelve, hijo pródigo,
al paternal hogar;
te llama él hoy, mañana, no,
¡acude, sin tardar!.

{soc}
Te busca el salvador,
te llama hoy en amor;
oh, ven a él sin más vacilar,
te quiere perdonar.
{eoc}

Ven, vuelve, no contristes más
al padre de bondad;
sin él, perdón no lograrás
por la eternidad.

{soc}
Te busca el salvador,
te llama hoy en amor;
oh, ven a él sin más vacilar,
te quiere perdonar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-128-oh-vuelve-vuelve/)' where id = 'sa-himno-128-oh-vuelve-vuelve';
update public.songs set title = '¡Adelante Vamos!', lyrics = '¡Adelante, vamos! Luchando por Jesús,
quien en su amor ha muerto en la cruz,
caminemos siempre en divina luz;
adelante sin temor.

{soc}
¡Despertad!, ¡despertad! Y pelead con valor;
¡con Jesús!, ¡con Jesús tendremos victoria!
¡Adelante, vamos! Con el salvador
a salvar del mal a todo pecador,
proclamad perdón por su inmenso amor;
adelante, sin temor.
{eoc}

¡Adelante, vamos! Dejando todo mal,
Jesucristo sólo nuestro ideal.
Preparando a todos para el día final
en el nombre del Señor.

{soc}
¡Despertad!, ¡despertad! Y pelead con valor;
¡con Jesús!, ¡con Jesús tendremos victoria!
¡Adelante, vamos! Con el salvador
a salvar del mal a todo pecador,
proclamad perdón por su inmenso amor;
adelante, sin temor.
{eoc}

¡Adelante, vamos! Espera el galardón
al que venciere, Dios le dará el don
de la vida eterna, sin más tentación,
adelante, sin temor.

{soc}
¡Despertad!, ¡despertad! Y pelead con valor;
¡con Jesús!, ¡con Jesús tendremos victoria!
¡Adelante, vamos! Con el salvador
a salvar del mal a todo pecador,
proclamad perdón por su inmenso amor;
adelante, sin temor.
{eoc}

¡Adelante, vamos! Jesús, el capitán,
nos conducirá pasando el Jordán,
a la tierra prometida de Canaán,
entraremos sin temor.

{soc}
¡Despertad!, ¡despertad! Y pelead con valor;
¡con Jesús!, ¡con Jesús tendremos victoria!
¡Adelante, vamos! Con el salvador
a salvar del mal a todo pecador,
proclamad perdón por su inmenso amor;
adelante, sin temor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-131-adelante-vamos/)' where id = 'sa-himno-131-adelante-vamos';
update public.songs set title = 'Jesús Es Mi Amigo', lyrics = 'Jesús es mi amigo, mi buen amigo fiel,
a mi alma el más bello de un millar;
el lirio de los valles, encuentro sólo en él
la virtud que trae perfecto bienestar.
En todos mis pesares es siempre mi sostén.
Me manda sobre él mi carga echar

{soc}
Es el lirio de los valles, la estrella del amor,
a mi alma el más bello de un millar.
{eoc}

Alivia mis pesares, mi buen amigo fiel,
en la tentación es torre eficaz;
del corazón arranco los ídolos por él
y las faltas que me apartan de su faz.
Si todos me desprecian, yo firme quedaré,
por él podré victoria alcanzar.

{soc}
Es el lirio de los valles, la estrella del amor,
a mi alma el más bello de un millar.
{eoc}

Si cumplo sus mandatos, viviendo por la fe,
en las pruebas de maldad me sostendrá:
rodeado de sus brazos, yo nada temeré;
con sus huestes el Señor me guardará
entonces a la gloria iremos para ver
su rostro y el cielo heredar.

{soc}
Es el lirio de los valles, la estrella del amor,
a mi alma el más bello de un millar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-132-jesus-es-mi-amigo/)' where id = 'sa-himno-132-jesus-es-mi-amigo';
update public.songs set title = 'Pecadores Extraviados', lyrics = 'Pecadores extraviados, lejos de su Dios,
degradados y perdidos lejos de su Dios.

{soc}
¡Oh! La muerte viene, viene.
Y el día final;
huyan, clamen, pidan, busquen
vida inmortal.
{eoc}

Satanás desea hundirles en la perdición,
Jesucristo quiere darles libre salvación.

{soc}
¡Oh! La muerte viene, viene.
Y el día final;
huyan, clamen, pidan, busquen
vida inmortal.
{eoc}

¡Oigan! Es la voz de Cristo: “yo les salvaré
y de todas tentaciones les rescataré”

{soc}
¡Oh! La muerte viene, viene.
Y el día final;
huyan, clamen, pidan, busquen
vida inmortal.
{eoc}

Mas, si este evangelio quieren despreciar,
en tinieblas sempiternas tendrán que morar.

{soc}
¡Oh! La muerte viene, viene.
Y el día final;
huyan, clamen, pidan, busquen
vida inmortal.
{eoc}

Y si quieren convertirse, fieles a Cristo ser,
allí podrán vivir con gozo y su rostro ver.

{soc}
¡Oh! La muerte viene, viene.
Y el día final;
huyan, clamen, pidan, busquen
vida inmortal.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-133-pecadores-extraviados/)' where id = 'sa-himno-133-pecadores-extraviados';
update public.songs set title = 'Salvado, Tan Gran Privilegio', lyrics = 'Salvado, tan gran privilegio,
¡salud por la sangre de él!
Yo canto, no puedo callarme,
yo vivo en hermoso vergel.

{soc}
Salud, salud,
salud me ha dado Jesús;
salud, salud,
por siempre soy hijo de luz.
{eoc}

Muy bien sé que soy tan benigno
de gracia, perdón, o de paz;
mas, él con su amor me ha salvado,
me ha dado la luz de su faz.

{soc}
Salud, salud,
salud me ha dado Jesús;
salud, salud,
por siempre soy hijo de luz.
{eoc}

Ya yo me he entregado del todo
al que me ha comprado así;
ya no me opongo ni un punto
de su voluntad para mí.

{soc}
Salud, salud,
salud me ha dado Jesús;
salud, salud,
por siempre soy hijo de luz.
{eoc}

Acepta mi ofrenda, ¡oh, Cristo!
Poséeme bien desde hoy;
mi voluntad y pensamientos,
y alma por siempre te doy.

{soc}
Salud, salud,
salud me ha dado Jesús;
salud, salud,
por siempre soy hijo de luz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-136-salvado-tan-gran-privilegio/)' where id = 'sa-himno-136-salvado-tan-gran-privilegio';
update public.songs set title = 'Te Alabamos, ¡Oh Dios!', lyrics = 'Te alabamos, ¡oh Dios!
Por tu hijo de amor,
que murió en el Calvario
por mí, pecador.

{soc}
¡Aleluya, gloria a Cristo!
¡Te alabamos, Jesús!
¡Aleluya, gloria a Cristo!
Te alabamos, amén.
{eoc}

Te alabamos, ¡oh Dios!
Por tu espíritu de luz
que mostró nos a Cristo
clavado en la cruz.

{soc}
¡Aleluya, gloria a Cristo!
¡Te alabamos, Jesús!
¡Aleluya, gloria a Cristo!
Te alabamos, amén.
{eoc}

Te alabamos, Jesús,
cordero inmortal,
que mi alma has comprado,
y librado del mal.

{soc}
¡Aleluya, gloria a Cristo!
¡Te alabamos, Jesús!
¡Aleluya, gloria a Cristo!
Te alabamos, amén.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-137-te-alabamos-oh-dios/)' where id = 'sa-himno-137-te-alabamos-oh-dios';
update public.songs set title = 'Cuando Yo Contemplé la Cruz', lyrics = 'Cuando yo contemple la cruz,
mis ídolos dejé;
en sendas nuevas ando ya,
y soy feliz, yo sé.

{soc}
Va bien, va bien,
va bien con los salvos; bien.
Yo sé por cierto es así;
va bien por los salvos; bien.
{eoc}

El desierto ya pasé,
a Canaán me voy;
el salvador mi guía es,
confiado en él estoy.

{soc}
Va bien, va bien,
va bien con los salvos; bien.
Yo sé por cierto es así;
va bien por los salvos; bien.
{eoc}

Cuando al tentarme Satanás
su sutileza emplea,
confío sólo en Jesús,
y gano la pelea.

{soc}
Va bien, va bien,
va bien con los salvos; bien.
Yo sé por cierto es así;
va bien por los salvos; bien.
{eoc}

En la hora de obscuridad
en Dios yo confiaré;
su gran promesa firme es:
yo no te dejaré.

{soc}
Va bien, va bien,
va bien con los salvos; bien.
Yo sé por cierto es así;
va bien por los salvos; bien.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-138-cuando-yo-contemple-la-cruz/)' where id = 'sa-himno-138-cuando-yo-contemple-la-cruz';
update public.songs set title = 'He Oído De Un Bello Paraíso', lyrics = 'He oído de un bello paraíso
en el reino de Dios más allá,
sus murallas de jaspe son hechas,
y sus calles de oro real.
Y allí corren aguas de vida,
transparentes cual puro cristal:
pero ni la mitad de sus glorias,
ha ideado la mente mortal.

{soc}
No se ha contado jamás,
no se ha contado jamás,
la mitad de las glorias del cielo
no se ha contado jamás.
{eoc}

He oído de regias mansiones,
que Jesús ha ido a preparar;
de las almas por él redimidas,
para siempre con Dios estarán.
Allí el pecado no entra;
ni pesar, ni dolor terrenal;
pero ni la mitad de sus goces,
ha ideado la mente mortal.

{soc}
No se ha contado jamás,
no se ha contado jamás,
la mitad de las glorias del cielo
no se ha contado jamás.
{eoc}

He oído de blancos vestidos,
y coronas que todos tendrán,
cuando el padre eterno diráles:
“venid, en mi reino entrad”.
Donde vivirán siempre felices,
alejados de pena carnal;
pero ni la mitad de su dicha
ha ideado la mente mortal.

{soc}
No se ha contado jamás,
no se ha contado jamás,
la mitad de las glorias del cielo
no se ha contado jamás.
{eoc}

He oído de un Cristo amante,
que perdona al vil pecador;
quien de pena y culpa absuelve
al que pide con fe su favor.
Y Jesús lo ampara y guarda,
dando fuerzas y valor potencial;
pero, ni la mitad de su gloria
ha ideado la mente mortal.

{soc}
No se ha contado jamás,
no se ha contado jamás,
la mitad de las glorias del cielo
no se ha contado jamás.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-139-he-oido-de-un-bello-paraiso/)' where id = 'sa-himno-139-he-oido-de-un-bello-paraiso';
update public.songs set title = 'Cuando Cesaren Mis Penas', lyrics = 'Cuando cesaren mi penas aquí,
y comenzaren los goces allí,
con mi amado Señor, eso sí,
gloria eterna será para mí.

{soc}
Gloria será, sí, para mí,
sí, para mí, sí, para mí.
Cuando en la luz contemplare a Jesús,
gloria eterna será para mí.
{eoc}

Cuando mediante su gracia sin par
yo en el cielo encuentre lugar,
en su presencia tan sólo estar,
gloria eterna será para mí.

{soc}
Gloria será, sí, para mí,
sí, para mí, sí, para mí.
Cuando en la luz contemplare a Jesús,
gloria eterna será para mí.
{eoc}

Entre amigos que antes amé.
Glorificado allí, gozaré,
dulces miradas de Cristo, yo sé
gloria eterna será para mí.

{soc}
Gloria será, sí, para mí,
sí, para mí, sí, para mí.
Cuando en la luz contemplare a Jesús,
gloria eterna será para mí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-140-cuando-cesaren-mis-penas/)' where id = 'sa-himno-140-cuando-cesaren-mis-penas';
update public.songs set title = 'Si Al Fiero Enemigo', lyrics = 'Si al fiero enemigo
temes combatir,
si estás en tinieblas
y sin porvenir,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.

{soc}
Deja penetrar la luz,
deja penetrar la luz,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.
{eoc}

Si tu fe en Cristo
flaca y débil es,
si Dios no contesta tu ferviente prez,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.

{soc}
Deja penetrar la luz,
deja penetrar la luz,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.
{eoc}

Si fueras con gozo
a la mansión sin par,
sin ver las tinieblas
que hay que disipar,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.

{soc}
Deja penetrar la luz,
deja penetrar la luz,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.
{eoc}

Si andamos en la luz,
divina luz,
nos limpiamos
por la sangre de Jesús,
claridad tenemos
en el corazón,
si vivimos en la luz.

{soc}
Deja penetrar la luz,
deja penetrar la luz,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.
{eoc}

Si el Espíritu de Dios consolador,
luz del cielo trae
divino resplandor,
cuando tenga entrada
a tu corazón,
esparce la luz y amor.

{soc}
Deja penetrar la luz,
deja penetrar la luz,
que la hermosa luz de Dios fulgure en ti
y serás feliz así.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-141-si-al-fiero-enemigo/)' where id = 'sa-himno-141-si-al-fiero-enemigo';
update public.songs set title = 'Un Vivo Anhelo', lyrics = 'Un vivo anhelo tengo yo
desde que alienta en mí la fe;
ya por el fuego del crisol,
o por el agua, limpio ser.

{soc}
¿a quién, Señor, acudiré?
Sé tú mi purificador;
pues sólo así podré tener
un puro y limpio corazón.
{eoc}

Mi senda limpia quiero ver,
mi mente exenta del terror.
Pero con todo mi querer
impuro soy –impuro soy.

{soc}
¿a quién, Señor, acudiré?
Sé tú mi purificador;
pues sólo así podré tener
un puro y limpio corazón.
{eoc}

Sólo el de limpio corazón
verá la cara del Señor,
porque es su fondo el reflector
del mismo Dios –del mismo Dios.

{soc}
¿a quién, Señor, acudiré?
Sé tú mi purificador;
pues sólo así podré tener
un puro y limpio corazón.
{eoc}

Quiero en mi pecho reflejar
el rostro amado Jesús,
cual se refleja sobre el mar
el cielo azul –el cielo azul.

{soc}
¿a quién, Señor, acudiré?
Sé tú mi purificador;
pues sólo así podré tener
un puro y limpio corazón.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-142-un-vivo-anhelo/)' where id = 'sa-himno-142-un-vivo-anhelo';
update public.songs set title = 'Cristo Jesús', lyrics = 'Cristo Jesús es un fiel amigo,
Sólo Él sólo Él.
En mis flaquezas está conmigo,
Sólo Él sólo Él

{soc}
En las luchas de cada día
Él es siempre un amigo fiel;
Jesús es nuestro seguro guía,
Sólo Él sólo Él.
{eoc}

No hay un amigo más noble y digno
No, no hay no, no hay;
Ni más humilde, manso y benigno,
No, no hay no, no hay.

{soc}
En las luchas de cada día
Él es siempre un amigo fiel;
Jesús es nuestro seguro guía,
Sólo Él sólo Él.
{eoc}

No hay hora sin su compañía,
Siempre fiel siempre fiel;
Llena la noche de su alegría
Sólo Él sólo Él.

{soc}
En las luchas de cada día
Él es siempre un amigo fiel;
Jesús es nuestro seguro guía,
Sólo Él sólo Él.
{eoc}

Al pecador perdonar anhela,
Sólo Él sólo Él.
Y por los santos Él siempre vela,
Sólo Él sólo Él.

{soc}
En las luchas de cada día
Él es siempre un amigo fiel;
Jesús es nuestro seguro guía,
Sólo Él sólo Él.
{eoc}

Dios en el hijo se ha complacido,
Sólo Él sólo Él;
Mas Él su gloria me ha compartido
Sólo Él sólo Él.

{soc}
En las luchas de cada día
Él es siempre un amigo fiel;
Jesús es nuestro seguro guía,
Sólo Él sólo Él.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-143-cristo-jesus/)' where id = 'sa-himno-143-cristo-jesus';
update public.songs set title = 'Más de Jesús Quiero Aprender', lyrics = 'Más de Jesús quiero aprender,
más de su gracia conocer,
más del amor con que me amó,
más de la cruz en que murió

{soc}
Más, más de Jesús
más, más de Jesús;
más del amor con que me amó,
más de la cruz en que murió.
{eoc}

Más de Jesús quisiera hablar
más de su comunión gozar,
más de sus dones recibir,
más a los otros compartir

{soc}
Más, más de Jesús
más, más de Jesús;
más del amor con que me amó,
más de la cruz en que murió.
{eoc}

Más de Jesús ansío ver,
más de su hermoso parecer,
más de la gloria de su faz,
más de su luz, más de su paz.

{soc}
Más, más de Jesús
más, más de Jesús;
más del amor con que me amó,
más de la cruz en que murió.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-144-mas-de-jesus-que-apender/)' where id = 'sa-himno-144-mas-de-jesus-que-apender';
update public.songs set title = 'Cual Faro En El Mar', lyrics = 'Cual faro en el mar, cual plácida armonía
es la esperanza del bendito día
en que el Señor vendrá con su excelsa compañía,
descendiendo en gloriosa majestad.

{soc}
Ven Señor, ven Señor.
Ven, Señor, con los tuyos a reinar.
Que a tu grata aparición
cesará nuestra aflicción,
ven, Señor, con los tuyos a reinar
{eoc}

Cual iris de paz en tempestad airada,
es para el alma, de luchar cansada,
la vuelta del Señor a su iglesia bien amada.
A inundarla de lumbre celestial.

{soc}
Ven Señor, ven Señor.
Ven, Señor, con los tuyos a reinar.
Que a tu grata aparición
cesará nuestra aflicción,
ven, Señor, con los tuyos a reinar
{eoc}

Cual fuerte clarín, que a batallar convida,
es de Jesús la grata y bendecida
promesa de volver para dar la bienvenida
a sus siervos que pronto le verán.

{soc}
Ven Señor, ven Señor.
Ven, Señor, con los tuyos a reinar.
Que a tu grata aparición
cesará nuestra aflicción,
ven, Señor, con los tuyos a reinar
{eoc}

¡oh!, ven sin tardar, Dios de los altos cielos,
ven a cumplir del alma los anhelos;
¡oh, pronto ven, Jesús! Y pon fin a los desvelos
de tus siervos que claman con afán.

{soc}
Ven Señor, ven Señor.
Ven, Señor, con los tuyos a reinar.
Que a tu grata aparición
cesará nuestra aflicción,
ven, Señor, con los tuyos a reinar
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-145-cual-faro-en-el-mar/)' where id = 'sa-himno-145-cual-faro-en-el-mar';
update public.songs set title = 'Avívanos, Señor', lyrics = 'Avívanos, Señor;
sintamos el poder
del Santo Espíritu de Dios
en todo nuestro ser.

Avívanos, Señor,
con nueva bendición.
Inflama el fuego de tu amor
en cada corazón.

Avívanos, Señor
tenemos sed en ti;
las lluvias de tu bendición
derrama ahora aquí.

Avívanos, Señor
despierta más amor,
más celo y fe en tu pueblo aquí
en bien del pecador.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-146-avivanos-senor/)' where id = 'sa-himno-146-avivanos-senor';
update public.songs set title = 'En Su Amorosa Compasión', lyrics = 'En su amorosa compasión,
Jesús me vino a rescatar.
Y de un abismo de maldad
su brazo me salvó.

{soc}
De las cadenas de Satán
con su poder me liberó,
y es hoy gozo proclamar
que pro su gracia salvo soy.
{eoc}

Por largo tiempo él esperó;
por largo tiempo él esperó;
y cuando al fin oí su voz
fue de perdón y paz.

{soc}
De las cadenas de Satán
con su poder me liberó,
y es hoy gozo proclamar
que pro su gracia salvo soy.
{eoc}

Sangrando aún veo su sien
que mano impía desgarró;
más, él me dice con amor
que por salvarme fue.

{soc}
De las cadenas de Satán
con su poder me liberó,
y es hoy gozo proclamar
que pro su gracia salvo soy.
{eoc}

Hoy en un mundo superior
respiro ambiente celestial,
y salvo soy para ensalzar
al que por mí murió.

{soc}
De las cadenas de Satán
con su poder me liberó,
y es hoy gozo proclamar
que pro su gracia salvo soy.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-149-en-su-amorosa-compasion/)' where id = 'sa-himno-149-en-su-amorosa-compasion';
update public.songs set title = 'Consagrarme Todo Entero', lyrics = 'Consagrarme todo entero
alma, vida y corazón,
es el íntimo deseo
que hoy me anima,
buen Señor.

{soc}
Heme aquí, Señor,
a tus plantas hoy,
consagrado a tu servicio
todo lo que soy.
{eoc}

Al contrito has prometido
que de ti no arrojarás,
hoy propicio sé conmigo
y tu espíritu me das.

{soc}
Heme aquí, Señor,
a tus plantas hoy,
consagrado a tu servicio
todo lo que soy.
{eoc}

Confesando mis pecados,
que sin número han de ser,
y arrojando todo a un lado
a servirte aprenderé.

{soc}
Heme aquí, Señor,
a tus plantas hoy,
consagrado a tu servicio
todo lo que soy.
{eoc}

Mi canción constante sea,
y mi sola inspiración,
proclamad la dicha eterna
del que vive para Dios.

{soc}
Heme aquí, Señor,
a tus plantas hoy,
consagrado a tu servicio
todo lo que soy.
{eoc}

¡cuánta paz inunda mi alma
al pensar que suyo soy,
y que pronto en las moradas
estará de mi Señor!

{soc}
Heme aquí, Señor,
a tus plantas hoy,
consagrado a tu servicio
todo lo que soy.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-150-consagrame-todo-entero/)' where id = 'sa-himno-150-consagrame-todo-entero';
update public.songs set title = 'Lleno De Angustias', lyrics = 'Lleno de angustia y temores
en brava y obscura mar,
el hombre perdido navega
cual barco en la tempestad,
olas del mal le rodean
nubes de duda y pavor;
y el eterno naufragio amenaza
sumergir su embarcación.

{soc}
Mira, alma turbada, tu salvador,
cerca está, cerca está;
vio tu peligro, y en su bondad
acude a librarte de ruina y dolor;
domina los vientos,
las nubes, el mar,
y al puerto te lleva
del bienestar.
Su voz potente, en la tempestad
trae paz, dulce paz.
Su nombre invoca y él te dará
eterna paz.
{eoc}

Contra las olas y el viento
batalla con ansiedad;
valiente, procura librarse
del piélago de maldad;
mas ya sus fuerzas gastadas.
Rendido ya su vigor,
desmayado, desea un refugio,
un guía y un salvador.

{soc}
Mira, alma turbada, tu salvador,
cerca está, cerca está;
vio tu peligro, y en su bondad
acude a librarte de ruina y dolor;
domina los vientos,
las nubes, el mar,
y al puerto te lleva
del bienestar.
Su voz potente, en la tempestad
trae paz, dulce paz.
Su nombre invoca y él te dará
eterna paz.
{eoc}

Fuerte y solícito acude
Jesús y con gran bondad
aborda la frágil barquilla
y calma la tempestad.
Libre de todo peligro,
salvo, seguro y en paz,
hoy con Cristo navega el marino
a eterna felicidad.

{soc}
Mira, alma turbada, tu salvador,
cerca está, cerca está;
vio tu peligro, y en su bondad
acude a librarte de ruina y dolor;
domina los vientos,
las nubes, el mar,
y al puerto te lleva
del bienestar.
Su voz potente, en la tempestad
trae paz, dulce paz.
Su nombre invoca y él te dará
eterna paz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-157-lleno-de-angustias/)' where id = 'sa-himno-157-lleno-de-angustias';
update public.songs set title = 'Jerusalén de Arriba', lyrics = 'Jerusalén de arriba, hogar de paz y amor,
allí los redimidos alaban al Señor,
no hay noche allí que oculte del sol la claridad;
y abiertas están sus puertas al mísero mortal.

Aquella hermosa patria de Dios es la mansión;
allí no hay más pecado, pesar, ni tentación;
angélica armonía resuena por doquier,
¡oh, cuándo yo por sus puertas con júbilo entraré!

En ese hogar me esperan con cariñoso afán
amados de mi alma que pronto me verán.
Pues nada ya en el mundo me puede retener
y sé que allá con los santos a mi Señor veré.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-160-jerusalem-de-arriba/)' where id = 'sa-himno-160-jerusalem-de-arriba';
update public.songs set title = 'Soy Extranjero Aquí', lyrics = 'Soy extranjero aquí, en tierra extraña estoy;
mi hogar está muy lejos, del sol más allá
a todo pecador embajador yo soy
del que por siempre rey será.

{soc}
Ved el mensaje que os traigo aquí:
“que os reconciliéis con Dios”.
Embajador yo soy de mi Señor el rey;
oíd, ¡oh pueblos! A mi voz.
{eoc}

Mi rey ordena que en todas partes hoy
el pecador se vuelva del pecado a Dios;
los que obedecen reinarán allá do voy;
escucha, pecador, su voz.

{soc}
Ved el mensaje que os traigo aquí:
“que os reconciliéis con Dios”.
Embajador yo soy de mi Señor el rey;
oíd, ¡oh pueblos! A mi voz.
{eoc}

La hermosura de mi hogar no tiene igual.
Eterna vida y gozo siempre hay allá;
mi rey y Dios anuncia que allí el mortal
eternamente morará.

{soc}
Ved el mensaje que os traigo aquí:
“que os reconciliéis con Dios”.
Embajador yo soy de mi Señor el rey;
oíd, ¡oh pueblos! A mi voz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-162-soy-extranjero-aqui/)' where id = 'sa-himno-162-soy-extranjero-aqui';
update public.songs set title = 'Ve, Ve, Oh, Sion', lyrics = 'Ve, ve, ¡oh, Sion!, tu gran destino cumple
que Dios es luz al mundo proclamad,
que el hacedor de las naciones quiere
que nadie muera en densa obscuridad.

{soc}
Nuevas alegres al mundo dad
nuevas de redención, de amor y libertad.
{eoc}

Ve cuantos miles yacen todavía
en las obscuras cárceles del mal
sin saber que de Cristo la agonía
fue para darles vida celestial.

{soc}
Nuevas alegres al mundo dad
nuevas de redención, de amor y libertad.
{eoc}

Es tu deber que salves de la muerte
las almas por las cuales él murió;
sé fiel si no quieres culpable verte
de que se pierda lo que Dios ganó.

{soc}
Nuevas alegres al mundo dad
nuevas de redención, de amor y libertad.
{eoc}

Ve, di a toda tribu, pueblo y lengua
que Dios en el cual viven es amor
que en la tierra ha muerto porque tenga
todo mortal la vida en el Señor.

{soc}
Nuevas alegres al mundo dad
nuevas de redención, de amor y libertad.
{eoc}

Tus hijos manda con gran mensaje,
con tu dinero impulso a ellos dá;
en oración sustenta fiel sus almas,
y cuando gastes Cristo pagará.

{soc}
Nuevas alegres al mundo dad
nuevas de redención, de amor y libertad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/ve-ve-oh-sion/)' where id = 'sa-ve-ve-oh-sion';
update public.songs set title = 'Tus Pies La Senda', lyrics = 'Tus pies la senda han extraviado,
de Dios muy lejos tu alma está
sus dones tú has disipado,
mas el perdón Jesús te da.

{soc}
Tu Dios te llama a su lado
él quiere oír tu triste historia;
te limpiará de tus pecados,
y gloria eterna gozarás.
{eoc}

Espinas crueles en tu senda
herido te han sin compasión;
tus ojos cubren negra venda
y todo en ti es aflicción.

{soc}
Tu Dios te llama a su lado
él quiere oír tu triste historia;
te limpiará de tus pecados,
y gloria eterna gozarás.
{eoc}

Al corazón adolorido
jamás despreciará el Señor:
al quebrantado y afligido
Jesús es tierno salvador.

{soc}
Tu Dios te llama a su lado
él quiere oír tu triste historia;
te limpiará de tus pecados,
y gloria eterna gozarás.
{eoc}

A Cristo ábrele tu alma,
y a él descubre tu aflicción
y pronto inundará de calma
tu pobre y triste corazón.

{soc}
Tu Dios te llama a su lado
él quiere oír tu triste historia;
te limpiará de tus pecados,
y gloria eterna gozarás.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-166-tus-pies-la-senda/)' where id = 'sa-himno-166-tus-pies-la-senda';
update public.songs set title = 'Cristo Busca Limpios Corazones', lyrics = 'Cristo busca limpios corazones,
que le sirvan siempre con fidelidad;
que a los pecadores insten con fervor
que se vuelvan al Señor de su maldad.

{soc}
Id, a trabajar allá en los campos del Señor
que para la siega se presentan blancos hoy,
oh, fieles siervos de Dios,
a quien debéis todo honor
oíd su voz, salid a trabajar.
{eoc}

Labios puros Cristo necesita
que con gozo anuncien plena salvación,
lenguas consagradas sólo a su servicio,
que proclaman al cautivo redención.

{soc}
Id, a trabajar allá en los campos del Señor
que para la siega se presentan blancos hoy,
oh, fieles siervos de Dios,
a quien debéis todo honor
oíd su voz, salid a trabajar.
{eoc}

Cristo busca manos bien dispuestas
para trabajar con buena voluntad,
siembras ya maduras piden vuestra ayuda;
las doradas mieses pronto cosechad.

{soc}
Id, a trabajar allá en los campos del Señor
que para la siega se presentan blancos hoy,
oh, fieles siervos de Dios,
a quien debéis todo honor
oíd su voz, salid a trabajar.
{eoc}

Vidas santas el Señor necesita,
que a los pecadores muestren su poder;
libres de ansiedad, en Jesús confiadas,
y que pueda de ellas siempre disponer.

{soc}
Id, a trabajar allá en los campos del Señor
que para la siega se presentan blancos hoy,
oh, fieles siervos de Dios,
a quien debéis todo honor
oíd su voz, salid a trabajar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-167-cristo-busca-limpios-corazones/)' where id = 'sa-himno-167-cristo-busca-limpios-corazones';
update public.songs set title = 'Cuando Vengan Pruebas', lyrics = 'Cuando vengan pruebas,
Cristo, ven a mí;
guárdame que débil,
no te niegue aquí,
si ves que vacilo
hazme recordar;
que tú tienes fuerzas
que me harán triunfar.

Si mundanos goces
vienen con afán,
o placeres falsos
tras mi alma van,
trae a mi memoria
tu Getsemaní,
o el cruel Calvario
con tu muerte allí.

Si, Señor, me mandas
ayes y aflicción,
si el dolor no falta
a mi corazón,
ve Jesús que nunca
falte en mí la fe,
ve que a ti yo siempre
toda carga dé.

Cuando al fin me venga
triste la vejez,
y mi cuerpo vuelva
al polvo otra vez,
en tu corazón confío
con paz celestial
que darás a mi alma
vida eternal.

Arreglos musicales: Hno. Matias Retamal', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-168-cuando-vengan-pruebas/)' where id = 'sa-himno-168-cuando-vengan-pruebas';
update public.songs set title = 'El Señor Resucitó', lyrics = 'El Señor resucitó: ¡aleluya!
Muerte y tumba hoy venció: ¡aleluya!
Su poder y gran virtud
cautivó la esclavitud;
redimido soy por él: ¡aleluya!

{soc}
¡Aleluya! Salvo soy;
redimido soy por él;
su poder y gran virtud
cautivó la esclavitud;
redimido soy por él: ¡aleluya!
{eoc}

Él al polvo se humilló: ¡aleluya!
Vencedor se levantó: ¡aleluya!
Cante pues la cristiandad
su gloriosa majestad;
redimido soy por él: ¡aleluya!

{soc}
¡Aleluya! Salvo soy;
redimido soy por él;
su poder y gran virtud
cautivó la esclavitud;
redimido soy por él: ¡aleluya!
{eoc}

Cristo en la cruz sufrió: ¡aleluya!
Al sepulcro descendió: ¡aleluya!
Hoy en gloria celestial
reina vivo e inmortal:
redimido soy por el: ¡aleluya!

{soc}
¡Aleluya! Salvo soy;
redimido soy por él;
su poder y gran virtud
cautivó la esclavitud;
redimido soy por él: ¡aleluya!
{eoc}

Hoy en gloria él está: ¡aleluya!
Y con él nos llevará
pronto él vendrá acá: ¡aleluya!
Con amor nos salva ya;
redimido soy por él: ¡aleluya!

{soc}
¡Aleluya! Salvo soy;
redimido soy por él;
su poder y gran virtud
cautivó la esclavitud;
redimido soy por él: ¡aleluya!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-170-el-senor-resucito/)' where id = 'sa-himno-170-el-senor-resucito';
update public.songs set title = 'Cuando En Mí Todo Acabaré', lyrics = 'Cuando en mí todo acabare,
Dios me sostendrá,
y Satán me acosaré,
Dios me sostendrá.

{soc}
Dios me sostendrá,
Dios me sostendrá,
porque soy de Cristo amado,
Dios me sostendrá.
{eoc}

Yo no puedo resistir.
Dios me sostendrá.
Y él vino a redimir;
Dios me sostendrá.

{soc}
Dios me sostendrá,
Dios me sostendrá,
porque soy de Cristo amado,
Dios me sostendrá.
{eoc}

Él conoce a sus amados:
Dios me sostendrá.
Y él está con los tentados,
Dios me sostendrá.

{soc}
Dios me sostendrá,
Dios me sostendrá,
porque soy de Cristo amado,
Dios me sostendrá.
{eoc}

No me dejará perdido,
Dios me guiará.
Y hoy me encuentro arrepentido;
Dios me sostendrá.

{soc}
Dios me sostendrá,
Dios me sostendrá,
porque soy de Cristo amado,
Dios me sostendrá.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-172-cuando-en-mi-todo-acabare/)' where id = 'sa-himno-172-cuando-en-mi-todo-acabare';
update public.songs set title = 'Unánimes Junto a Jesús', lyrics = 'Unánimes junto a Jesús,
pedimos con fervor;
según tu dicho, o Jesús,
manda el consolador.

{soc}
¡Oh! Manda otro pentecostés,
potente salvador,
y con fuego otra vez
avívanos, Señor.
{eoc}

Cual vivo fuego
o vendaval,
¡oh! Hazlo descender,
y en el alma de cada cual
tu templo, establecer.

{soc}
¡Oh! Manda otro pentecostés,
potente salvador,
y con fuego otra vez
avívanos, Señor.
{eoc}

Mediante fe y oración
el cielo abrirás,
el santo fuego harás bajar
y nos avivarás.

{soc}
¡Oh! Manda otro pentecostés,
potente salvador,
y con fuego otra vez
avívanos, Señor.
{eoc}

Destruye el egoísmo, así,
y quema todo mal;
ven, vivificamos aquí,
con fuego celestial.

{soc}
¡Oh! Manda otro pentecostés,
potente salvador,
y con fuego otra vez
avívanos, Señor.
{eoc}

¡Oh! Haz temblar al pecador
como en pentecostés,
y vuelve al que perdió
el valor
al gozo otra vez.

{soc}
¡Oh! Manda otro pentecostés,
potente salvador,
y con fuego otra vez
avívanos, Señor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-173-unanimes-junto-a-la-cruz/)' where id = 'sa-himno-173-unanimes-junto-a-la-cruz';
update public.songs set title = '¿Qué Ha Quitado Mi Maldad?', lyrics = '¿Qué ha quitado mi maldad?
Sólo de Jesús la sangre.
¿Qué me ha dado sanidad?
Sólo de Jesús la sangre.

{soc}
De toda mi maldad
por ella limpio soy,
ni a otra fuente voy,
sólo de Jesús la sangre.
{eoc}

Alcancé de Dios perdón,
sólo de Jesús la sangre.
Y un nuevo corazón;
sólo de Jesús la sangre

{soc}
De toda mi maldad
por ella limpio soy,
ni a otra fuente voy,
sólo de Jesús la sangre.
{eoc}

Me procura gracia y paz,
sólo de Jesús la sangre.
Es mi único solaz,
sólo de Jesús la sangre.

{soc}
De toda mi maldad
por ella limpio soy,
ni a otra fuente voy,
sólo de Jesús la sangre.
{eoc}

Cantaré junto a sus pies,
sólo de Jesús la sangre.
El cordero digno es,
sólo de Jesús la sangre.

{soc}
De toda mi maldad
por ella limpio soy,
ni a otra fuente voy,
sólo de Jesús la sangre.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-177-que-ha-quitado-mi-maldad/)' where id = 'sa-himno-177-que-ha-quitado-mi-maldad';
update public.songs set title = '¡Oh! Ven a la Cruz', lyrics = '¡Oh! Ven a la cruz donde Cristo expiró,
¡Oh! Ven a la cruz pues todo él pagó,
¡Oh! Ven a la cruz, cumplió ya está,
y su sangre ya nos lava del pecado

{soc}
Hay salud en Cristo,
vida en Cristo;
hay salud en Cristo.
Para el alma desdichada.
¡Oh, aleluya, aleluya!
¡Oh, aleluya salvado soy por él!
{eoc}

Él puede salvar al pobre pecador,
él puede salvar al alma de pecar;
él puede salvar si crees hoy en él,
pues su sangre ya nos lava del pecado.

{soc}
Hay salud en Cristo,
vida en Cristo;
hay salud en Cristo.
Para el alma desdichada.
¡Oh, aleluya, aleluya!
¡Oh, aleluya salvado soy por él!
{eoc}

Él quiere salvar a todo pecador,
te quiere salvar, Jesús el redentor,
te quiere salvar, y esto sin cobrar,
pues su sangre ya nos lava del pecado.

{soc}
Hay salud en Cristo,
vida en Cristo;
hay salud en Cristo.
Para el alma desdichada.
¡Oh, aleluya, aleluya!
¡Oh, aleluya salvado soy por él!
{eoc}

En él hay salud, perfecta salvación,
en él hay salud, ahora, salvación;
en él hay salud, eterna salvación;
pues su sangre ya nos lava del pecado.

{soc}
Hay salud en Cristo,
vida en Cristo;
hay salud en Cristo.
Para el alma desdichada.
¡Oh, aleluya, aleluya!
¡Oh, aleluya salvado soy por él!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-178-oh-ven-a-la-cruz/)' where id = 'sa-himno-178-oh-ven-a-la-cruz';
update public.songs set title = 'Óyenos, Pastor Divino', lyrics = 'Óyenos, pastor divino;
los que en este buen lugar,
como ovejas, congregados
te venimos a buscar.
Cristo, llega, Cristo, llega,
tu rebaño a apacentar.

Al perdido en el pecado
su peligro harás sentir
llama al pobre seducido,
déjale tu voz oír;
al enfermo, al enfermo
pronto dígnate acudir.

Guía al triste fatigado
al aprisco del Señor;
cría al tierno corderito
a tu lado, buen pastor
con los pastos, con los pastos
de celeste y dulce amor.

¡Oh, Jesús! Escucha el ruego
y esta humilde petición:
ven a henchir a tu rebaño
de sincera devoción,
cantaremos, cantaremos,
tu benigna protección.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-179-oyenos-pastor-divino/)' where id = 'sa-himno-179-oyenos-pastor-divino';
update public.songs set title = 'Mi Redentor, el Rey de Gloria', lyrics = 'Mi redentor, el rey de gloria
que vive, yo seguro estoy;
y da coronas de victoria;
a recibir la mía voy.

{soc}
Que permanezca no pidáis
entre el bullicio y el vaivén;
el mundo alegre hoy dejara,
aun cuando fuese algún Edén;
la cita nada mas aguardo
que el rey me diga: hijo, ven.
{eoc}

En mi Señor Jesús confío;
su sangre clama a mi favor,
es dueño él de mí albedrío;
estar con él es lo mejor.

{soc}
Que permanezca no pidáis
entre el bullicio y el vaivén;
el mundo alegre hoy dejara,
aun cuando fuese algún Edén;
la cita nada mas aguardo
que el rey me diga: hijo, ven.
{eoc}

De tanto amor me maravillo,
y no me canso de admirar;
me liberto de mi peligro,
sufriendo todo en mi lugar.

{soc}
Que permanezca no pidáis
entre el bullicio y el vaivén;
el mundo alegre hoy dejara,
aun cuando fuese algún Edén;
la cita nada mas aguardo
que el rey me diga: hijo, ven.
{eoc}

Consuélome en su larga ausencia
pensando: pronto volverá.
Entonces su gloriosa herencia
a cada fiel Jesús dará.

{soc}
Que permanezca no pidáis
entre el bullicio y el vaivén;
el mundo alegre hoy dejara,
aun cuando fuese algún Edén;
la cita nada mas aguardo
que el rey me diga: hijo, ven.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-180-mi-redentor-el-rey-de-gloria/)' where id = 'sa-himno-180-mi-redentor-el-rey-de-gloria';
update public.songs set title = 'Alabado El Gran Manantial', lyrics = 'Alabado el gran manantial
que de sangre Dios nos mostró.
Alabado el rey que murió.
Su pasión nos libra del mal.
Lejos del redil de mi dueño
vime mísero, pequeño, vil;
el cordero sangre vertió;
me limpia sólo este raudal.

{soc}
Sé que sólo así
me emblanqueceré.
Lávame en su sangre Jesús;
y la nívea blancura me dé.
{eoc}

La punzante insignia llevó.
En la cruz dejó de vivir;
grandes males quiso sufrir;
no en vano empero sufrió.
Al gran manantial
conducido,
que de mi maldad
ha sido fin,
“lávame” le pude decir,
y nívea blancura me dio.

{soc}
Sé que sólo así
me emblanqueceré.
Lávame en su sangre Jesús;
y la nívea blancura me dé.
{eoc}

Padre, de ti lejos vagué;
extravióse mi corazón;
como grana mis culpas son;
no con agua limpio seré
a tu fuente magna acudí;
tu promesa creo, ¡oh, Jesús!
La eficaz virtud de tu don
la nívea blancura me dé.

{soc}
Sé que sólo así
me emblanqueceré.
Lávame en su sangre Jesús;
y la nívea blancura me dé.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-181-alabado-el-gran-manantial/)' where id = 'sa-himno-181-alabado-el-gran-manantial';
update public.songs set title = 'Pobre Peregrino', lyrics = 'Pobre peregrino, que vagando estás
fuera del camino, ¿dónde pararás?
Con vara y cayado hoy el buen pastor
te brinda a su lado; ven ¡oh, pecador!

Tú vida pasada te causa dolor,
tu alma lacerada, tristeza y pavor;
tu suerte futura, eterno sufrir:
de tanta amargura, ¿no querrás salir?

¡Ay! ¿y cuántos días dejaste pasar
en vanas porfías que te han se pesar?
Por tu bien atiende la voz del Señor
y tu mano extiende hacia el salvador.

Tu vista levanta, eleva tu voz,
dirige tu planta hacia el salvador,
tu honra ha llegado, conócela, pues
el que te ha llamado tu salvador es.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-182-pobre-peregrino/)' where id = 'sa-himno-182-pobre-peregrino';
update public.songs set title = 'Nuevas Alegres', lyrics = 'Nuevas alegres para decirles
yo tengo ahora y éstas son:
que Jesucristo me ha salvado
desde que le pedí el perdón.
Y que también en patria mejor,
una morada prepara el Señor
para aquellos que determinen
su salvación aceptar.

Goces mundanos ya he dejado;
no quiero más tan falso placer.
Paz prometieron,
mas engañaron,
no me pudieron satisfacer;
más bien estoy con mi salvador
y al cielo voy
gozando su amor;
y él me guarda día por día
en gozo y libertad.

No me importa lo que dijeren
los enemigos de mi Jesús:
he elegido el buen camino.
Voy a la gloria, reino de luz.
Luchas yo tengo siempre aquí,
pero descanso aguardo allí.
¡oh, qué consuelo para mi alma
cuando me llame el Señor!', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-183-nuevas-alegres/)' where id = 'sa-himno-183-nuevas-alegres';
update public.songs set title = 'De Cristo Yo Soy', lyrics = 'De Cristo yo soy.
De Cristo yo soy:
él ya me lavó,
sellado ya estoy.
Tú eres mi pastor,
yo te seguiré,
no me apartaré
de mi buen Señor.

{soc}
Cristo santo, heme aquí,
dame de la fuente carmesí:
yo buscaré y llegaré
el gran mensaje del Señor.
{eoc}

Él, por su palabra
me dice ya soy
columna en el cielo
del templo de Dios.
“Tienes la corona
que te prometí
retén lo que tienes
mientras estás aquí”.

{soc}
Cristo santo, heme aquí,
dame de la fuente carmesí:
yo buscaré y llegaré
el gran mensaje del Señor.
{eoc}

“yo por mis promesas
os quiero decir
que quiero llevaros
muy cerca de mí.
Yo soy el camino
la verdad y la vida”.
Él ya nos convida:
tenemos que ir.

{soc}
Cristo santo, heme aquí,
dame de la fuente carmesí:
yo buscaré y llegaré
el gran mensaje del Señor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-184-de-cristo-yo-soy/)' where id = 'sa-himno-184-de-cristo-yo-soy';
update public.songs set title = 'Soñé que el Gran Día', lyrics = 'Soñé que el gran día del juicio
llegó y sonó el clarín;
soñé ver los pueblos reunidos,
para oír de su suerte sin fin.
Del trono salió un gran ángel,
y parado en tierra y mar.
Juró con su diestra alzada
que el tiempo ya no más será.

{soc}
Con llanto y duelo entonces
los perdidos su cuenta darán;
clamarán a las rocas: “cubridnos”
orarán, pero tarde será.
{eoc}

El rico llegó, mas su oro
se fue y se desvaneció.
Cual pobre paróse ante el trono;
de su deuda a Dios se acordó.
El grande también, mas la muerte
le había quitado su honor
y el ángel abriendo los libros
no halló nada en su favor.

{soc}
Con llanto y duelo entonces
los perdidos su cuenta darán;
clamarán a las rocas: “cubridnos”
orarán, pero tarde será.
{eoc}

Vino el moralista al juicio.
Mas vana fue su pretensión;
también los que a Cristo mataron
hicieron moral profesión.
Y el alma que daba la excusa
hoy no, otro día mejor;
halló que por siglos eternos
tendría que llorar su error.

{soc}
Con llanto y duelo entonces
los perdidos su cuenta darán;
clamarán a las rocas: “cubridnos”
orarán, pero tarde será.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/hinmo-185-sone-que-el-gran-dia/)' where id = 'sa-hinmo-185-sone-que-el-gran-dia';
update public.songs set title = 'Cuando Anuncie el Arcángel', lyrics = 'Cuando anuncie el arcángel
que más tiempo no habrá,
y aclare esplendoroso el día final;
cuando todos los salvados
se congreguen ante Dios,
entre ellos yo también tendré lugar.

{soc}
Cuando el ángel pase lista
cuando el ángel pase lista
cuando el ángel pase lista
al llamar mi nombre yo responderé.
{eoc}

Resucitarán gloriosos
los que han muerto en Jesús
las delicias del paraíso a gozar;
y triunfantes entrarán
en las mansiones de la luz,
para mí también habrá un dulce hogar.

{soc}
Cuando el ángel pase lista
cuando el ángel pase lista
cuando el ángel pase lista
al llamar mi nombre yo responderé.
{eoc}

Trabajemos para Cristo
anunciando su amor,
mientras dure nuestra vida terrenal;
y al fin de la jornada
con los salvos por Jesús
entraremos en la patria celestial.

{soc}
Cuando el ángel pase lista
cuando el ángel pase lista
cuando el ángel pase lista
al llamar mi nombre yo responderé.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-187-cuando-anuncie-el-arcangel/)' where id = 'sa-himno-187-cuando-anuncie-el-arcangel';
update public.songs set title = 'Cantemos Del Amor Divino', lyrics = 'Cantemos del divino amor
del salvador Jesús,
quien dio su vida en la cruz
comprando paz y luz;
todo el que con fervor
clamare al Señor,
por él será salvado de maldad.

{soc}
La sangre de Jesús te salvará de pecar,
la sangre de Jesús te salvará de pecar,
en él feliz estoy, porque salvado soy
de todos mis pecado y maldad.
{eoc}

Proclamaré al pecador
de Cristo la virtud;
Jesús es el libertador
de toda esclavitud.
Él me libró a mí,
perdón yo recibí.
Por él salvado soy de mi maldad.

{soc}
La sangre de Jesús te salvará de pecar,
la sangre de Jesús te salvará de pecar,
en él feliz estoy, porque salvado soy
de todos mis pecado y maldad.
{eoc}

Si somos fieles a Jesús
luchando contra el mal,
con él disfrutaremos
en la gloria celestial;
entonces más allá
pecado no habrá,
pues estaremos lejos de maldad.

{soc}
La sangre de Jesús te salvará de pecar,
la sangre de Jesús te salvará de pecar,
en él feliz estoy, porque salvado soy
de todos mis pecado y maldad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-188-cantemos-del-amor-divino/)' where id = 'sa-himno-188-cantemos-del-amor-divino';
update public.songs set title = '¡A Combatir!', lyrics = '¡A combatir!
Resuena la guerrera voz
del buen Jesús,
que hoy llamando está,
sin desmayar, seguidle siempre con valor,
y la victoria plena os dará.

{soc}
¡A la batalla!; ¡Oh Cristianos!
Con el escudo de la cruz;
sé fiel soldado,
pues a tu lado
está el príncipe Jesús.
El con su gracia te sostiene.
Y con potencia sin igual
su brazo extiende
y te defiende
en esta lucha contra el mal.
{eoc}

¡A combatir!
Marchad con fiel resolución
en pos de Cristo,
vuestro capitán,
henchido el corazón de varonil ardor
a derrotar
las huestes de Satán.

{soc}
¡A la batalla!; ¡Oh Cristianos!
Con el escudo de la cruz;
sé fiel soldado,
pues a tu lado
está el príncipe Jesús.
El con su gracia te sostiene.
Y con potencia sin igual
su brazo extiende
y te defiende
en esta lucha contra el mal.
{eoc}

Al rey de reyes
nuestro salvador Jesús
honor y gloria
todos tributad,
pues ya los suyos gozan de su plenitud
y pronto reinará
la santidad.

{soc}
¡A la batalla!; ¡Oh Cristianos!
Con el escudo de la cruz;
sé fiel soldado,
pues a tu lado
está el príncipe Jesús.
El con su gracia te sostiene.
Y con potencia sin igual
su brazo extiende
y te defiende
en esta lucha contra el mal.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-190-a-combatir/)' where id = 'sa-himno-190-a-combatir';
update public.songs set title = 'Un Príncipe Vino', lyrics = 'Un príncipe vino de noche a Jesús
buscando el camino de vida y de luz;
Jesús respondióle con gran sencillez;
“debéis nacer otra vez”.

{soc}
Debéis nacer otra vez,
debéis nacer otra vez,
de cierto, de cierto os vuelvo a decir,
debéis nacer otra vez.
{eoc}

Atiende tú, hombre, al tono y voz
solemne y divina del Hijo de Dios,
y acata el mensaje sin vana altivez:
“debéis nacer otra vez”.

{soc}
Debéis nacer otra vez,
debéis nacer otra vez,
de cierto, de cierto os vuelvo a decir,
debéis nacer otra vez.
{eoc}

Si el santo reposo anheláis alcanzar,
y a Dios con los santos canciones alzar
y su vida eterna quisierais tal vez,
“debéis nacer otra vez”.

{soc}
Debéis nacer otra vez,
debéis nacer otra vez,
de cierto, de cierto os vuelvo a decir,
debéis nacer otra vez.
{eoc}

Hay seres queridos que aguardan allí,
en la puerta hermosa esperan por ti;
escucha el mensaje, escúchalo, pues:
“debéis nacer otra vez”.

{soc}
Debéis nacer otra vez,
debéis nacer otra vez,
de cierto, de cierto os vuelvo a decir,
debéis nacer otra vez.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-191-un-principe-vino/)' where id = 'sa-himno-191-un-principe-vino';
update public.songs set title = 'Me Hirió El Pecado', lyrics = 'Me hirió el pecado,
fui a Jesús,
mostréle mi dolor.
Perdido, errante vi su luz,
bendíjome su amor.

{soc}
En la cruz, en la cruz,
do primero vi la luz,
y las manchas de mi alma lavé,
fue allí por fe que vi a Jesús
y siempre feliz con él seré.
{eoc}

Sobre una cruz
vi a mi Señor,
por fe cuando él murió;
en mí probó su grande amor,
mis culpas él expió.

{soc}
En la cruz, en la cruz,
do primero vi la luz,
y las manchas de mi alma lavé,
fue allí por fe que vi a Jesús
y siempre feliz con él seré.
{eoc}

Venció la muerte con poder,
y a gloria se exaltó.
Confiar en él es mi placer,
morir no temo yo.

{soc}
En la cruz, en la cruz,
do primero vi la luz,
y las manchas de mi alma lavé,
fue allí por fe que vi a Jesús
y siempre feliz con él seré.
{eoc}

Aunque él se fue,
solo no estoy,
mandó el consolador
divino espíritu que hoy
me da perfecto amor.

{soc}
En la cruz, en la cruz,
do primero vi la luz,
y las manchas de mi alma lavé,
fue allí por fe que vi a Jesús
y siempre feliz con él seré.
{eoc}

Vivir en Cristo trae la paz;
con él habitaré,
pues suyo soy,
y de hoy, en más
a nadie temeré.

{soc}
En la cruz, en la cruz,
do primero vi la luz,
y las manchas de mi alma lavé,
fue allí por fe que vi a Jesús
y siempre feliz con él seré.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-192-me-hirio-el-pecado/)' where id = 'sa-himno-192-me-hirio-el-pecado';
update public.songs set title = 'Honra y Gloria al Padre Eterno', lyrics = 'Honra y gloria al Padre Eterno
que a su hijo unigénito dio,
por el rescate del mundo entero
su última gota de sangre derramó.

{soc}
Más que victoria,
más que victoria,
Más que victoria,
tenemos en ti;
todo es puesto debajo de tus pies
y más que victoria tenemos en ti.
{eoc}

Cristo amado, mi fuerza tú eres,
fuera de ti nada puedo hacer;
todo es puesto debajo de tus pies
y más que victoria yo tengo en ti.

{soc}
Más que victoria,
más que victoria,
Más que victoria,
tenemos en ti;
todo es puesto debajo de tus pies
y más que victoria tenemos en ti.
{eoc}

Victoria sobre el mundo y sobre el pecado
victoria sobre el diablo y toda potestad;
y el que venciere será coronado
según su promesa y buena voluntad.

{soc}
Más que victoria,
más que victoria,
Más que victoria,
tenemos en ti;
todo es puesto debajo de tus pies
y más que victoria tenemos en ti.
{eoc}

Ahora, hermanos, estamos en la guerra,
contra los poderes de Satanás.
Después de la vida aquí en la tierra,
con Cristo reinaremos por siempre jamás.

{soc}
Más que victoria,
más que victoria,
Más que victoria,
tenemos en ti;
todo es puesto debajo de tus pies
y más que victoria tenemos en ti.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-193-honra-y-gloria-al-padre-eterno/)' where id = 'sa-himno-193-honra-y-gloria-al-padre-eterno';
update public.songs set title = 'Ved Del Cielo Rey De Gloria', lyrics = 'Ved al Cristo, rey de gloria,
es del mundo el vencedor;
de la guerra vuelve invicto,
todos deben darle loor.

{soc}
Coronadle, santos todos,
coronad al rey de reyes
coronadle, santos todos,
coronad al salvador.
{eoc}

Exaltadlo, exaltadlo.
Ricos triunfos trae Jesús;
entronadlo en los cielos
en la refulgente luz.

{soc}
Coronadle, santos todos,
coronad al rey de reyes
coronadle, santos todos,
coronad al salvador.
{eoc}

Pecadores se burlaron,
coronando al salvador,
ángeles y santos dadle
su riquísimo amor.

{soc}
Coronadle, santos todos,
coronad al rey de reyes
coronadle, santos todos,
coronad al salvador.
{eoc}

Escuchad las alabanzas
que se elevan hacia él.
Victorioso reina el Cristo,
adorad a Emmanuel.

{soc}
Coronadle, santos todos,
coronad al rey de reyes
coronadle, santos todos,
coronad al salvador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-194-ved-del-cielo-rey-de-gloria/)' where id = 'sa-himno-194-ved-del-cielo-rey-de-gloria';
update public.songs set title = 'Hoy Mi Alma Baña Con Su Luz', lyrics = 'Hoy mi alma baña con su luz
un astro superior;
es el rostro del Señor Jesús
que amante me miró,
¡cuánta dicha para el alma
en momentos de tribulación
es de Jesús la dulce faz
irradiando luz de Dios!

Hoy mi alma alegra con su son
un coro celestial;
es el himno de la redención
que yo debo entonar.
¡Cuánta dicha para el alma
en momentos de tribulación,
es escuchar el himno de la paz
y del gozo del Señor!

Hoy mi alma cubre de verdor
un sol primaveral:
es la fuerza del divino amor
que mi Señor me da.
¡Cuánta dicha para el alma
que el mundo nada poseyó
es sentir el fuego puro del altar
el divino y santo amor!', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-195-hoy-mi-alma-bana-con-su-luz/)' where id = 'sa-himno-195-hoy-mi-alma-bana-con-su-luz';
update public.songs set title = 'Marcharé En La Luz De Dios', lyrics = 'Marcharé en la luz de Dios
marcharé, sí, marcharé;
en la vía que Jesús pisó,
siempre marcharé.

{soc}
Vestido blanco, arpa y
corona áurea hay para mí;
laurel de triunfo y un hogar
en el Edén sin par.
Jesús me ha salvado de iniquidad
su espíritu mi alma sacia,
soy feliz en su amor, vivo en santidad
sí, vivo y triunfo por su gracia.
{eoc}

Marcharé sobre huestes mil,
marcharé, sí, marcharé:
la victoria he de conseguir
siempre marcharé.

{soc}
Vestido blanco, arpa y
corona áurea hay para mí;
laurel de triunfo y un hogar
en el Edén sin par.
Jesús me ha salvado de iniquidad
su espíritu mi alma sacia,
soy feliz en su amor, vivo en santidad
sí, vivo y triunfo por su gracia.
{eoc}

Marcharé almas a buscar,
marcharé, sí, marcharé;
pues Jesús las desea salvar
siempre marcharé.

{soc}
Vestido blanco, arpa y
corona áurea hay para mí;
laurel de triunfo y un hogar
en el Edén sin par.
Jesús me ha salvado de iniquidad
su espíritu mi alma sacia,
soy feliz en su amor, vivo en santidad
sí, vivo y triunfo por su gracia.
{eoc}

Por Jesús más que vencedor,
marcharé, sí, marcharé;
hasta llegar a la patria mejor,
siempre marcharé.

{soc}
Vestido blanco, arpa y
corona áurea hay para mí;
laurel de triunfo y un hogar
en el Edén sin par.
Jesús me ha salvado de iniquidad
su espíritu mi alma sacia,
soy feliz en su amor, vivo en santidad
sí, vivo y triunfo por su gracia.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-197-marchare-en-la-luz-de-dios/)' where id = 'sa-himno-197-marchare-en-la-luz-de-dios';
update public.songs set title = 'Ama El Pastor Sus Ovejas', lyrics = 'Ama el pastor sus ovejas
con su amor paternal;
ama el pastor su rebaño
con un amor sin igual;
ama el pastor a las otras
que descarriadas están
y conmovido las busca
por donde quiera que van.

{soc}
Por el desierto errabundas
vence sufrir penas mil,
y al encontrarlas, en hombros
tráelas gozoso al redil.
{eoc}

Ama el pastor sus corderos
ámalos tiernos el pastor;
a los que a veces perdidos
se oyen gemir de dolor.
Ved al pastor conmovido
por los collados vagar
y los corderos en hombros
traerlos, vedlo al hogar.

{soc}
Por el desierto errabundas
vence sufrir penas mil,
y al encontrarlas, en hombros
tráelas gozoso al redil.
{eoc}

Ama las noventa y nueve
que en el aprisco guardó,
ama las que descarriadas
por el desierto dejó:
“¡oh, mis ovejas perdidas!”
Clama doliente el pastor:
“¿quiénes vendrán en mi ayuda
para encontrarlas Señor?”

{soc}
Por el desierto errabundas
vence sufrir penas mil,
y al encontrarlas, en hombros
tráelas gozoso al redil.
{eoc}

Son delicados tus pastos
y quietas tus aguas son:
aquí nos tienes, ¡oh, maestro!
Danos hoy la comisión:
haznos obreros fervientes,
llénalos de tu amor,
por las ovejas perdidas
de tu redil, buen Señor.

{soc}
Por el desierto errabundas
vence sufrir penas mil,
y al encontrarlas, en hombros
tráelas gozoso al redil.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-198-ama-el-pastor-sus-ovejas/)' where id = 'sa-himno-198-ama-el-pastor-sus-ovejas';
update public.songs set title = 'A Abraham y A Sara', lyrics = 'A Abraham y a Sara un hijo Dios plugo prometer
confusos, no supieron qué decir.
Sabían, sin embargo, que Dios puede cumplir;
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

Hizo Moisés, serpiente, y en asta levantó
a donde todo el pueblo pudo ver;
cuando miraron ellos Jehová salud les dio:
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

Cuando Josué dio orden, el sol por él paró
la luna en su lugar también quedó;
ganaron la batalla. Dios plugo así hacer;
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

David con el gigante, propuso combatir;
confiaba cada uno en bien salir.
David mató al gigante, estaba Dios con él:
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

Daniel estando en honra, conspiran contra él;
secuaces envidiosos tienden red.
Estaba Dios potente en fosa del león:
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

Cuando ordenó el profeta los diezmos para Dios
el pueblo conoció su grande error.
Volviéronle los diezmos, volvió la bendición:
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

Vino el bendito Cristo, potente en sanar;
también al alma limpia de pecar
y quita los dolores, los lleva sobre él:
lo mismo, pues, hoy día es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}

Cantando Pablo y Silas y orando en la prisión,
sabían Pablo y Silas cómo orar.
Abriéronse las puertas, cayó todo eslabón;
lo mismo, pues, hoy es su poder.

{soc}
Lo mismo, pues, hoy día es su poder,
aunque el mundo no lo pueda comprender.
Habiendo él prometido, lo pudo Dios hacer
lo mismo, pues, hoy día es su poder.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-199-a-abraham-y-a-sara/)' where id = 'sa-himno-199-a-abraham-y-a-sara';
update public.songs set title = 'En Cristo, Feliz', lyrics = 'En Cristo, feliz es mi alma;
precioso es su célico don
su voz me devuelve la calma,
su faz me anticipa el perdón.

{soc}
Yo soy feliz en él,
yo soy feliz en él;
el gozo y la paz inunda mi ser
pues yo soy feliz con él.
{eoc}

Mucho antes que yo, él buscóme,
me atrajo a su amado redil,
de amor en sus brazos llevóme
do hay dichas y encantos a mil.

{soc}
Yo soy feliz en él,
yo soy feliz en él;
el gozo y la paz inunda mi ser
pues yo soy feliz con él.
{eoc}

Su amor fraternal me circunda,
su gracia conforta mi ser;
su Espíritu Santo me inunda
de un noble y extraño poder.

{soc}
Yo soy feliz en él,
yo soy feliz en él;
el gozo y la paz inunda mi ser
pues yo soy feliz con él.
{eoc}

A él seré un día semejante
dejando este cuerpo mortal,
y mientras discípulo amante,
ser quiero hasta el día final.

{soc}
Yo soy feliz en él,
yo soy feliz en él;
el gozo y la paz inunda mi ser
pues yo soy feliz con él.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-200-en-cristo-feliz/)' where id = 'sa-himno-200-en-cristo-feliz';
update public.songs set title = 'Muy Cercano Está el Día', lyrics = 'Muy cercano está el día,
cuando volverá Jesús
con la majestad y gloria
que le dio su padre Dios.
De sus santos rodeado
en la nube bajará:
ya de Cristo en el reinado
y el pecado quitará

{soc}
Ven, Señor Jesús, ven pronto.
Claman todos con ardor:
“he aquí yo vengo presto”
nos promete el salvador.
{eoc}

Tu venida, Jesucristo,
librará la humanidad
de Satán, autor inicuo;
de su gran calamidad.
Cesarán los males todos
por el reino de Jesús
¡alegraos oh, mortales!
Ved el triunfo de la cruz.

{soc}
Ven, Señor Jesús, ven pronto.
Claman todos con ardor:
“he aquí yo vengo presto”
nos promete el salvador.
{eoc}

Cómo anhela y espera
tu venida, oh Jesús,
toda alma que es salvada
por la sangre de tu cruz:
“ven y siéntate conmigo
en mi trono” el rey dirá;
“has sufrido y vencido
de mi gloria gozarás”.

{soc}
Ven, Señor Jesús, ven pronto.
Claman todos con ardor:
“he aquí yo vengo presto”
nos promete el salvador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-203-muy-cercano-esta-el-dia/)' where id = 'sa-himno-203-muy-cercano-esta-el-dia';
update public.songs set title = 'Que Mi Vida Entera Esté', lyrics = 'Que mi vida entera esté
consagrada a ti, Señor;
que mis pasos siempre guié
el impulso de tu amor

{soc}
¡Lávame en tu sangre, salvador!
Límpiame de toda mi maldad
traigo a ti mi vida,
para ser Señor,
tuya por la eternidad.
{eoc}

Que mis pies tan solo en pos
de los santos puedan ir,
y que a ti, Señor, mi voz
se complazca en bendecir.

{soc}
¡Lávame en tu sangre, salvador!
Límpiame de toda mi maldad
traigo a ti mi vida,
para ser Señor,
tuya por la eternidad.
{eoc}

Que mi tiempo todo esté
consagrado a tu loor,
que mis labios al hablar
hablen sólo de tu amor.

{soc}
¡Lávame en tu sangre, salvador!
Límpiame de toda mi maldad
traigo a ti mi vida,
para ser Señor,
tuya por la eternidad.
{eoc}

Toma ¡Oh Dios! Mi voluntad
y hazla tuya nada más;
toma, sí, mi corazón;
por tu trono lo tendrás.

{soc}
¡Lávame en tu sangre, salvador!
Límpiame de toda mi maldad
traigo a ti mi vida,
para ser Señor,
tuya por la eternidad.
{eoc}

Toma tú mi amor, que hoy
a tus pies vengo a poner,
toma todo lo que soy,
todo tuyo quiero ser.

{soc}
¡Lávame en tu sangre, salvador!
Límpiame de toda mi maldad
traigo a ti mi vida,
para ser Señor,
tuya por la eternidad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-204-que-mi-vida-entera-este/)' where id = 'sa-himno-204-que-mi-vida-entera-este';
update public.songs set title = 'Cantaré La Maravilla', lyrics = 'Cantaré la maravilla,
que Jesús murió por mí;
cómo allá en el Calvario
dio su sangre carmesí.

{soc}
Cantaré la bella historia
de Jesús mi salvador
y con santos en la gloria
a Jesús daré loor.
{eoc}

Cristo vino a rescatarme.
Vil, perdido me encontró;
con su mano fiel y tierna
al redil él me llevó.

{soc}
Cantaré la bella historia
de Jesús mi salvador
y con santos en la gloria
a Jesús daré loor.
{eoc}

Mis heridas y dolores
el Señor Jesús sanó;
del pecado y los temores
su poder me libertó.

{soc}
Cantaré la bella historia
de Jesús mi salvador
y con santos en la gloria
a Jesús daré loor.
{eoc}

En el río de la muerte
el Señor me guardará,
es su amor tan fiel y fuerte
que jamás me dejará.

{soc}
Cantaré la bella historia
de Jesús mi salvador
y con santos en la gloria
a Jesús daré loor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-205-cantare-la-maravilla/)' where id = 'sa-himno-205-cantare-la-maravilla';
update public.songs set title = 'Cuando Estés Cansado', lyrics = 'Cuando estés cansado y abatido,
dilo a Cristo, dilo a Cristo;
si te sientes débil y herido,
dilo a Cristo el Señor.

{soc}
Dilo a Cristo, dilo a Cristo,
él es tu amigo más fiel:
no hay otro amigo como Cristo.
Dilo tan sólo a él.
{eoc}

Cuando estés de tentación cercado,
mira a Cristo, mira a Cristo;
cuando rujan huestes de pecado
mira a Cristo, el Señor.

{soc}
Mira a Cristo, dilo a Cristo,
él es tu amigo más fiel:
no hay otro amigo como Cristo.
Dilo tan sólo a él.
{eoc}

Si se apartan otros de la senda,
sigue a Cristo, sigue a Cristo;
cuando recrudece la contienda,
sigue a Cristo, el Señor.

{soc}
Sigue a Cristo, dilo a Cristo,
él es tu amigo más fiel:
no hay otro amigo como Cristo.
Dilo tan sólo a él.
{eoc}

Cuando llegue la final jornada,
confía en Cristo, confía en Cristo;
te dará en el cielo franca entrada.
Confía en Cristo, el Señor.

{soc}
Confía en Cristo, dilo a Cristo,
él es tu amigo más fiel:
no hay otro amigo como Cristo.
Dilo tan sólo a él.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-206-cuando-estes-cansado/)' where id = 'sa-himno-206-cuando-estes-cansado';
update public.songs set title = '¡Oh! Jamás Nos Cansaremos', lyrics = '¡Oh! Jamás nos cansaremos de la gran canción.
Loores a Dios, ¡aleluya!
Por la fe cantaremos con el corazón.
Loores a Dios, ¡aleluya!

{soc}
A los hijos de Dios pertenece el cantar.
Pues vendrá el salvador y nos arrebatará;
del palacio celestial gozaremos más allá.
Loores a Dios, ¡aleluya!
{eoc}

¡Oh! La indecible gloria del divino amor;
loores a Dios, ¡aleluya!
Que en sus alas lleva el alma donde el Señor.
Loores a Dios, ¡aleluya!

{soc}
A los hijos de Dios pertenece el cantar.
Pues vendrá el salvador y nos arrebatará;
del palacio celestial gozaremos más allá.
Loores a Dios, ¡aleluya!
{eoc}

¡Qué vistosos son los ángeles morando en luz!
Loores a Dios, ¡aleluya!
Más lucientes los creyentes al venir Jesús,
loores a Dios, ¡aleluya!

{soc}
A los hijos de Dios pertenece el cantar.
Pues vendrá el salvador y nos arrebatará;
del palacio celestial gozaremos más allá.
Loores a Dios, ¡aleluya!
{eoc}

Coronado en la gloria con el salvador;
loores a Dios, ¡aleluya!
Cantaremos alabanzas del divino amor.
Loores a Dios, ¡aleluya!

{soc}
A los hijos de Dios pertenece el cantar.
Pues vendrá el salvador y nos arrebatará;
del palacio celestial gozaremos más allá.
Loores a Dios, ¡aleluya!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-207-oh-jamas-nos-cansaremos/)' where id = 'sa-himno-207-oh-jamas-nos-cansaremos';
update public.songs set title = 'Soldados Santos del Señor', lyrics = 'Soldados santos del Señor,
llamados sois por él;
vamos luchando con valor
para Emmanuel.

{soc}
Después de la guerra seremos coronados:
seremos coronados, seremos coronados;
después de la guerra seremos coronados
en la nueva Jerusalén.
Coronados, coronados, coronados, coronados.
Después de la guerra seremos coronados
en la nueva Jerusalén.
{eoc}

Fue ofrecido una vez
Jesús mi salvador;
comprado por su sangre es
el pobre pecador.

{soc}
Después de la guerra seremos coronados:
seremos coronados, seremos coronados;
después de la guerra seremos coronados
en la nueva Jerusalén.
Coronados, coronados, coronados, coronados.
Después de la guerra seremos coronados
en la nueva Jerusalén.
{eoc}

Con la ayuda del Señor
yo quiero serle fiel;
a Satanás el tentador
deseo yo vencer.

{soc}
Después de la guerra seremos coronados:
seremos coronados, seremos coronados;
después de la guerra seremos coronados
en la nueva Jerusalén.
Coronados, coronados, coronados, coronados.
Después de la guerra seremos coronados
en la nueva Jerusalén.
{eoc}

Oh, buen Jesús, mi vencedor,
mi vida y salud,
enséñame tu grande amor
tu gracia y virtud.

{soc}
Después de la guerra seremos coronados:
seremos coronados, seremos coronados;
después de la guerra seremos coronados
en la nueva Jerusalén.
Coronados, coronados, coronados, coronados.
Después de la guerra seremos coronados
en la nueva Jerusalén.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-209-soldados-santos-del-senor/)' where id = 'sa-himno-209-soldados-santos-del-senor';
update public.songs set title = 'En El Fondo De Mi Alma', lyrics = 'En el fondo de mi alma una dulce quietud
se difunde embargando mi ser,
una calma infinita que sólo podrán
los salvados de Dios comprender.

{soc}
¡Paz! ¡Paz! Dulcísima paz
es aquella que el padre me da;
yo le ruego que inunde por siempre mi ser
en sus ondas de amor celestial.
{eoc}

Qué tesoros yo tengo en la paz que me dio,
y en el fondo del alma ha de estar
tan segura que nadie quitarla podrá
mientras miro los años pasar.

{soc}
¡Paz! ¡Paz! Dulcísima paz
es aquella que el padre me da;
yo le ruego que inunde por siempre mi ser
en sus ondas de amor celestial.
{eoc}

Esta paz inefable consuelo me da,
descansando tan sólo en Jesús;
y ningunos peligros mi vida tendrá
si me siento inundado en su luz.

{soc}
¡Paz! ¡Paz! Dulcísima paz
es aquella que el padre me da;
yo le ruego que inunde por siempre mi ser
en sus ondas de amor celestial.
{eoc}

Alma triste que en rudo conflicto te ves
sola y débil tu senda al seguir,
haz de Cristo tu amigo, que fiel siempre es,
y su paz tú podrás recibir.

{soc}
¡Paz! ¡Paz! Dulcísima paz
es aquella que el padre me da;
yo le ruego que inunde por siempre mi ser
en sus ondas de amor celestial.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-212-en-el-fondo-de-mi-alma/)' where id = 'sa-himno-212-en-el-fondo-de-mi-alma';
update public.songs set title = 'A Prepararnos Morada', lyrics = 'A preparadnos moradas
fuiste a la patria querida,
a gozar de tu hermosura
en tu segunda venida.

{soc}
Heme aquí, Señor, te espero,
mi alma de anhelo henchida
a gozar de tu hermosura
en tu segunda venida.
{eoc}

De peligros y temores
esta mi alma combatida,
porque el tiempo cerca espera
de tu segunda venida.

{soc}
Heme aquí, Señor, te espero,
mi alma de anhelo henchida
a gozar de tu hermosura
en tu segunda venida.
{eoc}

Mientras lejos permaneces
mi alma de anhelo henchida
acerca, Señor, el día
de tu segunda venida.

{soc}
Heme aquí, Señor, te espero,
mi alma de anhelo henchida
a gozar de tu hermosura
en tu segunda venida.
{eoc}

Allá en las nubes viene
el autor de nuestras vidas
con sus santos y sus ángeles
en su segunda venida.

{soc}
Heme aquí, Señor, te espero,
mi alma de anhelo henchida
a gozar de tu hermosura
en tu segunda venida.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-213-a-prepararnos-morada/)' where id = 'sa-himno-213-a-prepararnos-morada';
update public.songs set title = 'Mensajeros Del Maestro', lyrics = 'Mensajeros del maestro
anunciad al corazón,
de Jesús las buenas nuevas,
de su grande salvación.

{soc}
Mensajeros del maestro
vuestra voz haced oír,
y los hombres que la escuchen
vida puedan recibir.
{eoc}

De los montes en la cima,
en los valles y en el mar,
que doquier el evangelio
hoy se pueda proclamar.

{soc}
Mensajeros del maestro
vuestra voz haced oír,
y los hombres que la escuchen
vida puedan recibir.
{eoc}

En los antros del pecado,
y en los sitios de aflicción
las alegres nuevas vayan
a llevar consolación.

{soc}
Mensajeros del maestro
vuestra voz haced oír,
y los hombres que la escuchen
vida puedan recibir.
{eoc}

Anunciad a los cautivos
su gloria libertad,
al cansado y al caído
buenas nuevas proclamad.

{soc}
Mensajeros del maestro
vuestra voz haced oír,
y los hombres que la escuchen
vida puedan recibir.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-215-mensajeros-del-maestro/)' where id = 'sa-himno-215-mensajeros-del-maestro';
update public.songs set title = 'Cuán Glorioso Es el Cambio', lyrics = 'Cuán glorioso es el cambio operado en mi ser
viniendo a mi vida el Señor,
hay en mi alma una paz que yo ansiaba tener,
la paz que me trajo su amor.

{soc}
Él vino a mi corazón,
él vino a mi corazón,
soy feliz con la vida que Cristo me dio,
cuando él vino a mi corazón.
{eoc}

Ya no voy por la senda que el mal me trazó
do solo encontré confusión;
mis errores pasados Jesús los borró
cuando él vino a mi corazón.

{soc}
Él vino a mi corazón,
él vino a mi corazón,
soy feliz con la vida que Cristo me dio,
cuando él vino a mi corazón.
{eoc}

Ni una sombra de duda obscurece su amor,
amor que me trajo el perdón;
la esperanza que aliento la debo al Señor,
cuando él vino a mi corazón.

{soc}
Él vino a mi corazón,
él vino a mi corazón,
soy feliz con la vida que Cristo me dio,
cuando él vino a mi corazón.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-216-cuan-glorioso-es-el-cambio/)' where id = 'sa-himno-216-cuan-glorioso-es-el-cambio';
update public.songs set title = '¿Hasta Cuándo, Señor?', lyrics = '¿Hasta cuándo, Señor, yo te pido,
hasta cuándo tendrás escondido
tu rostro de mí?
¿Hasta cuándo en el alma, dudoso,
todo el día con pecho angustioso,
tendré que sufrir?

¿Hasta cuándo el feroz enemigo
al luchar orgulloso conmigo
triunfante saldrá?
¡Oh Señor y mi Dios, presuroso,
vuelve a mí tu semblante amoroso
y escúchame ya!

Ilumina mis ojos, de suerte
que el sueño de súbita muerte
no venga a dormir.
Que no diga: “vencíle”, algún día
mi enemigo; y rebose alegría
si caigo infeliz.

Pero yo en tu bondad he confiado
y de gozo mi pecho colmado
será en tu salud.
Al Señor, que me dio bienes tantos,
placentero diré nuevos cantos
al son del laúd.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-217-hasta-cuando-senor/)' where id = 'sa-himno-217-hasta-cuando-senor';
update public.songs set title = '¿Quién a Cristo Quiere?', lyrics = '¿Quién a Cristo quiere
de hoy en más seguir,
su pendón alzando,
yendo a combatir?
¿Quién le quiere humilde
siempre aquí servir,
siempre obedecerle,
darle su existir?

{soc}
¿Quién seguirle quiere?
¿Quién responderá
al buen redentor:
“heme aquí, yo iré”?
Quien doquier que fuere
tras su huella irá.
¿Quién dirá al Señor:
“yo te seguiré”?
{eoc}

¿Quién seguirle quiere
con profundo amor,
dándole la gloria,
dándole el honor,
de su noble causa
siendo defensor,
y en su santa viña
fiel trabajador?

{soc}
¿Quién seguirle quiere?
¿Quién responderá
al buen redentor:
“heme aquí, yo iré”?
Quien doquier que fuere
tras su huella irá.
¿Quién dirá al Señor:
“yo te seguiré”?
{eoc}

¿Quién seguirle quiere
sin vacilación
a su seno huyendo
de la tentación;
sin dudar confiado
en su protección
y gozando siempre
de su bendición?

{soc}
¿Quién seguirle quiere?
¿Quién responderá
al buen redentor:
“heme aquí, yo iré”?
Quien doquier que fuere
tras su huella irá.
¿Quién dirá al Señor:
“yo te seguiré”?
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-218-quien-a-cristo-quiere/)' where id = 'sa-himno-218-quien-a-cristo-quiere';
update public.songs set title = 'Nuestra Vida Acabará', lyrics = 'Nuestra vida acabará,
cual las hojas caerá,
cual el haz se ligará,
busca a Dios.
Vuela cada día veloz
y volando da su voz:
“ven a dar tu cuenta a Dios”,
busca a Dios.

{soc}
Busca a Dios, busca a Dios,
entretanto tengas tiempo,
busca a Dios.
Si te atreves a esperar,
Dios la puerta cerrará;
te dirá: – “es tarde ya”,
busca a Dios.
{eoc}

Pierde el hombre su vigor,
se marchita cual la flor,
desvanece cual vapor.
Busca a Dios
como el río aprisa va
hasta entrar al vasto mar,
vas así a la eternidad,
busca a Dios.

{soc}
Busca a Dios, busca a Dios,
entretanto tengas tiempo,
busca a Dios.
Si te atreves a esperar,
Dios la puerta cerrará;
te dirá: – “es tarde ya”,
busca a Dios.
{eoc}

Clama a Dios de corazón,
con sincera contrición.
Por Jesús Dios da perdón:
busca a Dios.
Si no escuchas al Señor,
si desprecias su perdón,
te acarreas perdición.
Busca a Dios.

{soc}
Busca a Dios, busca a Dios,
entretanto tengas tiempo,
busca a Dios.
Si te atreves a esperar,
Dios la puerta cerrará;
te dirá: – “es tarde ya”,
busca a Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-219-nuestra-vida-acabara/)' where id = 'sa-himno-219-nuestra-vida-acabara';
update public.songs set title = '¿Cómo Puedes Pecar?', lyrics = '¿Cómo puedes pecar sin temor contra Dios,
echando en olvido su amor?
¿Cómo puedes vivir rechazando la voz
de Cristo, tu buen salvador?

{soc}
El verano acabó, la siega pasó,
y tenemos que ir a la cuenta rendir
delante del trono de Dios.
{eoc}

¿Cómo puedes pensar que al infierno tú vas
sin estremecerte de horror;
sin pedir a tu Dios mientras tengas lugar,
que tenga de ti compasión?

{soc}
El verano acabó, la siega pasó,
y tenemos que ir a la cuenta rendir
delante del trono de Dios.
{eoc}

Cuando acabe el verano y se siegue la mies,
la muerte vendrá con su hoz,
y tendrás que dar cuenta ante Cristo, tu juez,
entonces no habrá salvación.

{soc}
El verano acabó, la siega pasó,
y tenemos que ir a la cuenta rendir
delante del trono de Dios.
{eoc}

Cuando Dios haya puesto su trono de luz.
Llamándote a su tribunal,
y buscares en vano refugio en Jesús,
¡qué espanto y terror sentirás!

{soc}
El verano acabó, la siega pasó,
y tenemos que ir a la cuenta rendir
delante del trono de Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-220-como-puedes-pecar/)' where id = 'sa-himno-220-como-puedes-pecar';
update public.songs set title = 'Hay quien Vele Mis Pisadas', lyrics = 'Hay quien vele mis pisadas
en la sombra y en la luz;
por las sendas escarpadas
velará por mí Jesús.
Por los valles, por los montes,
do me lleva su bondad,
miro ya los horizontes
de una nueva claridad.

{soc}
Hay quien vele mis pisadas
y mi senda trazará
a las célicas moradas,
es Jesús quien me guiará.
{eoc}

Hay contacto que me explica
la presencia del Señor;
en las penas santifica,
y me libra del temor.
Cristo con su mano herida,
protección me puede dar,
cuando cruzo de la vida
el inquieto y fiero mar.

{soc}
Hay quien vele mis pisadas
y mi senda trazará
a las célicas moradas,
es Jesús quien me guiará.
{eoc}

Hay un corazón amante,
de infinita compasión,
que confiere paz constante
al contrito corazón.
En su amor hay eficacia,
él es un amigo fiel.
Hay en él verdad y gracia,
suyo soy y mío es él.

{soc}
Hay quien vele mis pisadas
y mi senda trazará
a las célicas moradas,
es Jesús quien me guiará.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-221-hay-quien-vele-mis-pisadas/)' where id = 'sa-himno-221-hay-quien-vele-mis-pisadas';
update public.songs set title = 'Hermano, Dinos Hoy', lyrics = 'Hermano, dinos hoy algo de Jesús;
dinos otra ves la historia de su amor.
Decláranos la fe, gozo y gratitud.
Dinos otra vez la historia de su amor.
¿sigues todavía cerca del Señor?
¿arde tu alma del primer fervor?
¿está tu copa llena de bendición?
Dinos otra vez la historia de su amor.

{soc}
Dinos otra vez la historia
del amor del salvador;
tan bendita y grata historia
nos hará cantar su gloria.
Dinos otra vez la historia de su amor.
{eoc}

Al escuchar tu voz que habla del Señor,
dinos otra vez la historia de su amor,
tal vez un pecador se convierta a Dios;
dinos otra vez la historia de su amor.
Muchos tienen sed en su corazón
y en el mundo buscan diversión;
señálales la fuente de bendición.
Dinos otra vez la historia de su amor.

{soc}
Dinos otra vez la historia
del amor del salvador;
tan bendita y grata historia
nos hará cantar su gloria.
Dinos otra vez la historia de su amor.
{eoc}

La ayuda que te ha dado en al tentación;
dinos otra vez la historia de su amor.
Las pruebas de tu fe y su compasión;
dinos otra vez la historia de su amor.
Dinos que Jesús es amigo fiel,
que es tu capitán y gran pastor;
socorro oportuno has hallado en él;
dinos otra vez la historia de su amor.

{soc}
Dinos otra vez la historia
del amor del salvador;
tan bendita y grata historia
nos hará cantar su gloria.
Dinos otra vez la historia de su amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-222-hermano-dinos-hoy/)' where id = 'sa-himno-222-hermano-dinos-hoy';
update public.songs set title = 'Cristo Quiere Que Yo Brille', lyrics = 'Cristo quiere que yo brille,
brillando para él;
y que yo dé a conocer
su amor y gran poder.

{soc}
Brillando, brillando,
queremos que Chile brille;
brillando, brillando.
Chile pedimos a Dios.
{eoc}

Somos pequeños nosotros,
mas, grande es el Señor;
haremos lo que podamos
en bien de la nación.

{soc}
Brillando, brillando,
queremos que Chile brille;
brillando, brillando.
Chile pedimos a Dios.
{eoc}

Aunque somos pequeños
nos oirá el Señor
cuando pidamos por Chile
con intenso clamor.

{soc}
Brillando, brillando,
queremos que Chile brille;
brillando, brillando.
Chile pedimos a Dios.
{eoc}

Es un deber del cristiano,
según nos aconsejó
el gran apóstol san pablo:
orar por la nación.

{soc}
Brillando, brillando,
queremos que Chile brille;
brillando, brillando.
Chile pedimos a Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-223-cristo-quiere-que-yo-brille/)' where id = 'sa-himno-223-cristo-quiere-que-yo-brille';
update public.songs set title = 'Cuán Hermosos Son los Pies', lyrics = 'Cuán hermosos son los pies del fiel cristiano
que cumple el mandato de Jesús;
va a las gentes sumergidas en tinieblas,
llamándolas a la luz.

{soc}
Los que sirven a Jesús
y son fieles a su rey,
“ven buen siervo y fiel”, les dirá;
“sobre poco has sido fiel,
sobre mucho te pondré
y en mi gozo tú entrarás”.
{eoc}

Despertad de vuestro sueño, mis hermanos,
salid levantando vuestra voz;
predicad a todo el mundo el evangelio
de la salvación de Dios.

{soc}
Los que sirven a Jesús
y son fieles a su rey,
“ven buen siervo y fiel”, les dirá;
“sobre poco has sido fiel,
sobre mucho te pondré
y en mi gozo tú entrarás”.
{eoc}

No nos predicamos a nosotros mismos;
hablamos de Cristo y de su cruz;
Dios que resplandece en nuestros corazones
también quiere daros luz.

{soc}
Los que sirven a Jesús
y son fieles a su rey,
“ven buen siervo y fiel”, les dirá;
“sobre poco has sido fiel,
sobre mucho te pondré
y en mi gozo tú entrarás”.
{eoc}

Satanás a los incrédulos e impíos
cegó y andan en oscuridad,
y debemos proclamar las gratas nuevas
que quiten su ceguedad.

{soc}
Los que sirven a Jesús
y son fieles a su rey,
“ven buen siervo y fiel”, les dirá;
“sobre poco has sido fiel,
sobre mucho te pondré
y en mi gozo tú entrarás”.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-224-cuan-hermosos-son-los-pies/)' where id = 'sa-himno-224-cuan-hermosos-son-los-pies';
update public.songs set title = 'Oíd, Oíd Lo Que Nos Manda', lyrics = 'Oíd, oíd lo que nos manda el salvador;
marchad, marchad, y proclamad mi amor
porque he aquí, yo con vosotros estaré
los días todos hasta el fin os guardaré.

{soc}
Id, id, por el mundo;
id, id y predicad el evangelio.
Id, id, va adelante
el todopoderoso salvador.
¡gloria, gloria, aleluya a Jesús!
Nuestras almas él salvó,
nuestras manchas él lavó,
proclamemos, pues, a todos su amor.
{eoc}

Pensad, pensad la condición del pecador,
qué triste es, qué llena de dolor;
sin luz, sin paz camina a la eternidad,
y no conoce el gran peligro en que él está.

{soc}
Id, id, por el mundo;
id, id y predicad el evangelio.
Id, id, va adelante
el todopoderoso salvador.
¡gloria, gloria, aleluya a Jesús!
Nuestras almas él salvó,
nuestras manchas él lavó,
proclamemos, pues, a todos su amor.
{eoc}

Salid, salid, embajadores del Señor,
buscad, buscad al pobre pecador;
aprovechad el tiempo que el Señor nos da,
pues pronto el día de salud acabará.

{soc}
Id, id, por el mundo;
id, id y predicad el evangelio.
Id, id, va adelante
el todopoderoso salvador.
¡gloria, gloria, aleluya a Jesús!
Nuestras almas él salvó,
nuestras manchas él lavó,
proclamemos, pues, a todos su amor.
{eoc}

Mirad, mirad, la hora presto llegará;
Jesús vendrá su reino a disfrutar;
de mar a mar habrá prosperidad y paz;
sus alabanzas cantará la humanidad.

{soc}
Id, id, por el mundo;
id, id y predicad el evangelio.
Id, id, va adelante
el todopoderoso salvador.
¡gloria, gloria, aleluya a Jesús!
Nuestras almas él salvó,
nuestras manchas él lavó,
proclamemos, pues, a todos su amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-225-oid-oid-lo-que-nos-manda/)' where id = 'sa-himno-225-oid-oid-lo-que-nos-manda';
update public.songs set title = 'Uno Por Uno Llegando Están', lyrics = 'Uno por uno llegando están
al Señor, al Señor;
uno por uno aceptando van al redentor.
Obreros Cristianos rogad al Señor
que nuevos obreros envíe a su mies;
obreros Cristianos luchad con valor
y almas perdidas traed a sus pies.

{soc}
Trabajad, trabajad;
uno por uno al Señor llevad.
Trabajad, trabajad
con fe y amor.
{eoc}

Andrés a su hermano simón habló
del Señor, del Señor;
y a su presencia después le llevó con fe y amor.
Nosotros también, como hizo Andrés,
a unos llevemos al salvador,
llevemos a uno contrito a sus pies
y Cristo le recibirá con amor.

{soc}
Trabajad, trabajad;
uno por uno al Señor llevad.
Trabajad, trabajad
con fe y amor.
{eoc}

Dijo a Felipe, el salvador:
sígueme, sígueme;
y éste a Natanael habló del buen Señor.
Y uno por uno así creció
el grupo de fieles al redentor;
y a uno por uno él prometió
a todos la dádiva de su amor.

{soc}
Trabajad, trabajad;
uno por uno al Señor llevad.
Trabajad, trabajad
con fe y amor.
{eoc}

Uno por uno al salvador
hoy también, hoy también,
traigamos nosotros con fe y amor al sumo bien,
a uno traigamos y Dios dirá:
“bien hecho, fiel siervo, en mi gozo entrad”.
A uno traigamos y gozo habrá
delante del trono del padre allá.

{soc}
Trabajad, trabajad;
uno por uno al Señor llevad.
Trabajad, trabajad
con fe y amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-227-uno-por-uno-llegando-estan/)' where id = 'sa-himno-227-uno-por-uno-llegando-estan';
update public.songs set title = 'Lejos, Allende Los Mares', lyrics = 'Lejos, allende los mares,
tengo mi dulce hogar.
Veo entre las tinieblas
la hermosa ribera brillar.
Pronto allá me dirijo
aunque difícil es;
recto el camino que llevo,
y muy seguro es.

{soc}
Sion, hermoso lugar
do mi hogar tendré;
feliz yo voy a estar
cuando a ti veré.
Santos esperan allá;
pronto con ellos estaré;
no habrá tristeza,
no habrá más muerte
en mi hogar.
{eoc}

Cuando me llame la muerte
en mi hogar entraré;
cuando ha cesado la lucha
corona allí ceñiré;
libre de todo pecado
iré a descansar,
mi alma a unirse con santos
a Cristo alabar.

{soc}
Sion, hermoso lugar
do mi hogar tendré;
feliz yo voy a estar
cuando a ti veré.
Santos esperan allá;
pronto con ellos estaré;
no habrá tristeza,
no habrá más muerte
en mi hogar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-229-lejos-allende-los-mares/)' where id = 'sa-himno-229-lejos-allende-los-mares';
update public.songs set title = 'Comisionados Del Señor', lyrics = 'Comisionados del Señor
venimos a contar
que Jesucristo sangre dio
al mundo por salvar.
Atentos perseguimos hoy
tan importante fin,
y pregonamos por doquier
“ya suena el clarín”.

{soc}
A proclamar-
“muy cerca el reino está”-
“¡aún más allá!”
“¡muy cerca el reino está!”
Henos aquí, oh, pecador;
la voz de amor oíd:
dejad el mal, volved al bien,
y vida recibid.
{eoc}

¿Por qué más tiempo peligrar
tu alma inmortal?
Jesús el precio ya pagó
por todos, imparcial.
Del cielo habla el Señor
con voz de gran poder.
Mandando salvación buscar,
su rostro para ver.

{soc}
A proclamar-
“muy cerca el reino está”-
“¡aún más allá!”
“¡muy cerca el reino está!”
Henos aquí, oh, pecador;
la voz de amor oíd:
dejad el mal, volved al bien,
y vida recibid.
{eoc}

Con pocos días más acá
y ha de terminar
tu vida y tu trabajar,
y cuentas habrás de dar.
Pues, no demores más –oh, ven,
escucha, pecador:
entrega ya tu triste ser
a Cristo, tu Señor.

{soc}
A proclamar-
“muy cerca el reino está”-
“¡aún más allá!”
“¡muy cerca el reino está!”
Henos aquí, oh, pecador;
la voz de amor oíd:
dejad el mal, volved al bien,
y vida recibid.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-230-comisionados-del-senor/)' where id = 'sa-himno-230-comisionados-del-senor';
update public.songs set title = 'Por Fe En Jesús El Salvador', lyrics = 'Por fe en Jesús el Salvador,
se hace salvo el pecador;
sin merecer tan rico don,
recibe plena salvación.

{soc}
¡Oh, excelsa gracia del amor!
Que Dios perdona al pecador,
si presto está a confesar
su culpa y en Jesús confiar.
No hay otro autor de salvación,
pues Cristo obró la redención.
{eoc}

La vida antigua ya pasó,
y todo nuevo se tornó;
aquí cual peregrino es;
hogar con Dios tendrá después.

{soc}
¡Oh, excelsa gracia del amor!
Que Dios perdona al pecador,
si presto está a confesar
su culpa y en Jesús confiar.
No hay otro autor de salvación,
pues Cristo obró la redención.
{eoc}

Aun cuando nada tenga aquí,
su gran herencia tiene, sí.
Arriba en gloria con Jesús,
quien le ha salvado por su cruz.

{soc}
¡Oh, excelsa gracia del amor!
Que Dios perdona al pecador,
si presto está a confesar
su culpa y en Jesús confiar.
No hay otro autor de salvación,
pues Cristo obró la redención.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-231-por-fe-en-jesus-el-salvador/)' where id = 'sa-himno-231-por-fe-en-jesus-el-salvador';
update public.songs set title = 'Enrolado Estoy', lyrics = 'Enrolado estoy en las huestes de Jehová;
he resuelto pelear por el bien y contra el mal;
con las armas de Dios y la espada espiritual
con Jesús en las luchas venceremos.

{soc}
Oíd el son marcial de los soldados,
al son del triunfo derrotaremos.
Oíd que pasan ya los alistados,
van vencer a Satán.
Como soldado me he enrolado;
el Dios de los ejércitos es mi ayuda,
cual fiel soldado me he presentado
con Jesús en las luchas venceremos.
{eoc}

Desplegad el pendón de amor y santidad,
salvación publicad al mundo pecador;
con sus dardos Satán podrá darnos temor,
con Jesús en las luchas venceremos.

{soc}
Oíd el son marcial de los soldados,
al son del triunfo derrotaremos.
Oíd que pasan ya los alistados,
van vencer a Satán.
Como soldado me he enrolado;
el Dios de los ejércitos es mi ayuda,
cual fiel soldado me he presentado
con Jesús en las luchas venceremos.
{eoc}

Si tu nombre, ¡oh, amigo!, no has dado hasta hoy
para unirte con los pocos fieles a Jesús,
no hay otro remedio al mal sino la cruz.
Con Jesús en las luchas venceremos.

{soc}
Oíd el son marcial de los soldados,
al son del triunfo derrotaremos.
Oíd que pasan ya los alistados,
van vencer a Satán.
Como soldado me he enrolado;
el Dios de los ejércitos es mi ayuda,
cual fiel soldado me he presentado
con Jesús en las luchas venceremos.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-232-enrolado-estoy/)' where id = 'sa-himno-232-enrolado-estoy';
update public.songs set title = 'Cautivo Era De Satán', lyrics = 'Cautivo era de Satán,
por mis maldades oprimido
perderme fue siempre su afán,
mas, Cristo al fin me libertó.

{soc}
Diré a todos mi historia;
feliz y libre estoy,
feliz y libre estoy,
a Dios loor, a Dios loor
por su gloriosa libertad.
{eoc}

Emancipado ya del mal
emprenderé divina lucha.
Con Cristo insigne general
invicto siempre yo seré.

{soc}
Diré a todos mi historia;
feliz y libre estoy,
feliz y libre estoy,
a Dios loor, a Dios loor
por su gloriosa libertad.
{eoc}

Jesús caudillo inmortal
al mundo vino por librarnos
de la vil opresión del mal
y darnos dulce libertad.

{soc}
Diré a todos mi historia;
feliz y libre estoy,
feliz y libre estoy,
a Dios loor, a Dios loor
por su gloriosa libertad.
{eoc}

Después de lidia terrenal
el premio celestial aguarda
al vencedor, quien vivirá
por siempre, libre de maldad.

{soc}
Diré a todos mi historia;
feliz y libre estoy,
feliz y libre estoy,
a Dios loor, a Dios loor
por su gloriosa libertad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-233-cautivo-era-de-satan/)' where id = 'sa-himno-233-cautivo-era-de-satan';
update public.songs set title = 'Oh, Cristo Amado', lyrics = 'Oh, Cristo amado, mi buen Salvador,
por ti he dejado las sendas del error:
y quiero servirte pues tú me amaste a mí,
si antes no te amaba, Señor, ahora sí.

{soc}
Y al llegar al cielo así cantaré yo;
yo era vil indigno, yo era vil indigno,
yo era indigno, mas Cristo me salvó.
{eoc}

En santas moradas en gozo perennal,
a Cristo Jesús el cordero inmortal
yo siempre cantaré ¡Oh! Qué dicha para mí,
si antes no te amaba, Señor, ahora sí.

{soc}
Y al llegar al cielo así cantaré yo;
yo era vil indigno, yo era vil indigno,
yo era indigno, mas Cristo me salvó.
{eoc}

Te amo porque en tu grande amor,
tuviste en poco vergüenza y dolor,
corona de espinas llevaste tú por mí.
Si antes no te amaba, Señor, ahora sí.

{soc}
Y al llegar al cielo así cantaré yo;
yo era vil indigno, yo era vil indigno,
yo era indigno, mas Cristo me salvó.
{eoc}

En la vida y muerte yo siempre te amaré,
y en alabanzas mi voz entonaré,
porque en el madero moriste tú por mí.
Si antes no te amaba, Señor, ahora sí.

{soc}
Y al llegar al cielo así cantaré yo;
yo era vil indigno, yo era vil indigno,
yo era indigno, mas Cristo me salvó.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-234-oh-cristo-amado/)' where id = 'sa-himno-234-oh-cristo-amado';
update public.songs set title = '¿Cómo Podré Estar Triste?', lyrics = '¿Cómo podré estar triste,
cómo entre sombras ir
cómo sentirme solo
y en el dolor vivir
si Cristo es mi consuelo,
mi amigo siempre fiel,
si aun las aves tienen
seguro asilo en él?

{soc}
Feliz cantando alegre,
yo vivo siempre aquí:
¡si él cuida de las aves
cuidará también de mí!
{eoc}

Nunca te desalientes
oigo al Señor decir,
y en su palabra fiado
hago al dolor huir.
A Cristo paso a paso
yo sigo sin cesar.
Y todas sus bondades
me da sin limitar.

{soc}
Feliz cantando alegre,
yo vivo siempre aquí:
¡si él cuida de las aves
cuidará también de mí!
{eoc}

Siempre que estoy tentado
o que en la sombra estoy,
más cerca de él camino
y protegido voy.
Si en mí la fe desmaya,
y caigo en la ansiedad
tan sólo él me levanta,
me da seguridad.

{soc}
Feliz cantando alegre,
yo vivo siempre aquí:
¡si él cuida de las aves
cuidará también de mí!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-235-como-podre-estar-triste/)' where id = 'sa-himno-235-como-podre-estar-triste';
update public.songs set title = '¡Oh, Jóvenes, Venid!', lyrics = '¡Oh, jóvenes, venid! Su brillante pabellón
Cristo ha desplegado hoy en la nación.
A todos en sus filas os quiere recibir;
y con él a la pelea os hará salir.

{soc}
Vamos a Jesús, compañeros, sin temor.
Vamos a la lid, inflamados de valor.
Jóvenes, luchemos todos contra el mal;
en Jesús llevamos nuestro general.
{eoc}

¡Oh, jóvenes, venid! El caudillo salvador
quiere recibirnos en su derredor;
con él a la batalla salid sin vacilar.
Vamos pronto, compañeros, vamos a luchar.

{soc}
Vamos a Jesús, compañeros, sin temor.
Vamos a la lid, inflamados de valor.
Jóvenes, luchemos todos contra el mal;
en Jesús llevamos nuestro general.
{eoc}

Las armas invencibles del jefe guiador
son el evangelio y su gran amor;
con ellas revestidos, y llenos de poder,
compañeros acudamos, vamos a vencer.

{soc}
Vamos a Jesús, compañeros, sin temor.
Vamos a la lid, inflamados de valor.
Jóvenes, luchemos todos contra el mal;
en Jesús llevamos nuestro general.
{eoc}

Los fieros enemigos, engendros de Satán,
al lado ya se hallan de su capitán;
¡oh, jóvenes, vosotros poneos sin temor
a la diestra del caudillo, nuestro salvador.

{soc}
Vamos a Jesús, compañeros, sin temor.
Vamos a la lid, inflamados de valor.
Jóvenes, luchemos todos contra el mal;
en Jesús llevamos nuestro general.
{eoc}

Quien venga a la pelea su voz escuchará;
Cristo la victoria le concederá;
salgamos, compañeros, luchemos, sí, por él;
con Jesús conquistaremos inmortal laurel.

{soc}
Vamos a Jesús, compañeros, sin temor.
Vamos a la lid, inflamados de valor.
Jóvenes, luchemos todos contra el mal;
en Jesús llevamos nuestro general.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-239-oh-jovenes-venid/)' where id = 'sa-himno-239-oh-jovenes-venid';
update public.songs set title = 'Adiós Mis Hermanos', lyrics = '¡Adiós, mis hermanos! Yo voy a dejaros,
y seguir la batalla en otra ciudad.
Más, quiero animaros a ser valerosos,
luchando por Dios contra toda maldad.

{soc}
Partiremos de aquí, más allá nos veremos,
delante del trono de nuestro Señor;
por siglos sin fin, nunca más separarnos
morando con Cristo en eterno esplendor.
{eoc}

¡Adiós, mis amigos! El deber ya me toca;
y tengo que irme sirviendo al Señor;
y es mi oración que el maestro os bendiga,
guardándoos siempre en su santo amor.

{soc}
Partiremos de aquí, más allá nos veremos,
delante del trono de nuestro Señor;
por siglos sin fin, nunca más separarnos
morando con Cristo en eterno esplendor.
{eoc}

¡Adiós, pecadores! Yo siento dejaros,
porque todavía estáis lejos de Dios;
más, aún tiempo hay, si queréis entregaros
en manos de aquel que os quiere salvar.

{soc}
Partiremos de aquí, más allá nos veremos,
delante del trono de nuestro Señor;
por siglos sin fin, nunca más separarnos
morando con Cristo en eterno esplendor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-240-adios-mis-hermanos/)' where id = 'sa-himno-240-adios-mis-hermanos';
update public.songs set title = 'Ando con Gozo', lyrics = 'Ando con gozo todo el camino
cuando hay pruebas, cuando hay paz.
Cristo promete nunca faltarme,
dicho precioso, grato solaz.

{soc}
Gozo indecible hallo en Cristo
nombre divino lleno de amor,
¡Aleluya!, sigo cantando
salmos e himnos a mi Señor.
{eoc}

Sombras arriba o alrededor
nunca se esconde mi guiador,
él es la luz del mundo entero,
y para siempre, mi salvador.

{soc}
Gozo indecible hallo en Cristo
nombre divino lleno de amor,
¡Aleluya!, sigo cantando
salmos e himnos a mi Señor.
{eoc}

En la luz brillante siempre gozando
sigo la senda de santidad.
En la mansión de Cristo en gloria
yo viviré por la eternidad.

{soc}
Gozo indecible hallo en Cristo
nombre divino lleno de amor,
¡Aleluya!, sigo cantando
salmos e himnos a mi Señor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-241-ando-con-gozo/)' where id = 'sa-himno-241-ando-con-gozo';
update public.songs set title = 'Al Pecador Cristo Llama', lyrics = 'Al pecador, Cristo llama,
pues no ha terminado aún su amor,
él no quiere que las almas
sumergidas mueran en perdición.

{soc}
Acudid todos los seres tristes,
pronto venid, Jesús insiste,
todo aquel que le quiera aceptar;
sólo en Jesús hay salvación y libertad.
{eoc}

Otro ser no hay en quien pueda
encontrar el hombre la salvación;
sólo Cristo dio su sangre
en la cruz por darnos la redención.

{soc}
Acudid todos los seres tristes,
pronto venid, Jesús insiste,
todo aquel que le quiera aceptar;
sólo en Jesús hay salvación y libertad.
{eoc}

El que vaga en este mundo
sin hallar reposo y tranquilidad,
si a Jesús acude pronto
él le dará paz que fin no tendrá.

{soc}
Acudid todos los seres tristes,
pronto venid, Jesús insiste,
todo aquel que le quiera aceptar;
sólo en Jesús hay salvación y libertad.
{eoc}

A Jesús, ¡oh, pecadores!
Venid pronto ya sin más demorar,
pues el tiempo pasa luego,
quizás ya mañana, no llamará.

{soc}
Acudid todos los seres tristes,
pronto venid, Jesús insiste,
todo aquel que le quiera aceptar;
sólo en Jesús hay salvación y libertad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-242-al-pecador-cristo-llama/)' where id = 'sa-himno-242-al-pecador-cristo-llama';
update public.songs set title = 'Cantaré a Cristo', lyrics = 'Cantaré a Cristo por su gran amor,
cómo vino para ser mi salvador,
¡cuán humilde fue el lugar
en el pueblo de Judá,
donde Cristo vino por amor a mí!

{soc}
Es sin igual su infinito amor,
y en una horrenda cruz su vida dio por mí.
Yo cantaré su dulce nombre, sí.
Oh, salvador eterno, loores doy a ti.
{eoc}

Cantaré a Cristo, quien en humildad
hizo siempre la divina voluntad;
los enfermos él sanó,
a los muertos levantó,
a los pobres, él colmó de su bondad.

{soc}
Es sin igual su infinito amor,
y en una horrenda cruz su vida dio por mí.
Yo cantaré su dulce nombre, sí.
Oh, salvador eterno, loores doy a ti.
{eoc}

Cantaré a Cristo sin cesar aquí,
cantaré lo que él ha hecho para mí,
mis pecados él llevó,
mi perdón y paz compró;
cantaré su dulce nombre, sí.

{soc}
Es sin igual su infinito amor,
y en una horrenda cruz su vida dio por mí.
Yo cantaré su dulce nombre, sí.
Oh, salvador eterno, loores doy a ti.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-243-cantare-a-cristo/)' where id = 'sa-himno-243-cantare-a-cristo';
update public.songs set title = 'Sembraré la Simiente preciosa', lyrics = 'Sembraré la simiente preciosa,
del glorioso evangelio de amor,
sembraré, sembraré mientras viva
dejaré el resultado al Señor.

{soc}
Sembraré, sembraré
mientras viva simiente de amor.
Segaré, segaré, al hallarme en la casa de Dios.
{eoc}

Sembraré en corazones sencillos
la doctrina de Dios de perdón,
sembraré, sembraré mientras viva;
dejaré el resultado al Señor.

{soc}
Sembraré, sembraré
mientras viva simiente de amor.
Segaré, segaré, al hallarme en la casa de Dios.
{eoc}

Sembraré en corazones de mármol,
la bendita palabra de amor.
Sembraré, sembraré mientras viva;
dejaré el resultado al Señor.

{soc}
Sembraré, sembraré
mientras viva simiente de amor.
Segaré, segaré, al hallarme en la casa de Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-244-sembrare-la-simiente-preciosa/)' where id = 'sa-himno-244-sembrare-la-simiente-preciosa';
update public.songs set title = 'Señor Jesús, Escucha ya', lyrics = 'Señor Jesús, escucha ya
a este pobre pecador,
que hoy te pide a ti perdón,
me reconozco pecador.

{soc}
Yo le diré a mí Señor,
lo malo que he sido aquí;
y le diré: mi buen Señor,
ten hoy compasión de mí.
{eoc}

Muy afligido me encontré,
muy agobiado de pecar;
pero Jesús me dice: ven,
ven, te haré yo descansar.

{soc}
Yo le diré a mí Señor,
lo malo que he sido aquí;
y le diré: mi buen Señor,
ten hoy compasión de mí.
{eoc}

Alguna vez la muerte atroz
vendrá, más cuándo, no lo sé;
pero esto sé, que si soy fiel
un sitio yo feliz tendré.

{soc}
Yo le diré a mí Señor,
lo malo que he sido aquí;
y le diré: mi buen Señor,
ten hoy compasión de mí.
{eoc}

Mientras yo pueda aquí vivir;
esta es mi fiel resolución:
servirte sólo a ti, Señor,
con un sincero corazón.

{soc}
Yo le diré a mí Señor,
lo malo que he sido aquí;
y le diré: mi buen Señor,
ten hoy compasión de mí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-245-senor-jesus-escucha-ya/)' where id = 'sa-himno-245-senor-jesus-escucha-ya';
update public.songs set title = 'Cual ciudad Sobre Un Monte', lyrics = 'Cual ciudad sobre un monte edificada
no se puede esconder.
Que la luz de Dios sea en ti reflejada;
haz tu luz resplandecer.

{soc}
Haz tu luz resplandecer.
Haz tu luz resplandecer.
Brille Cristo solamente en nuestra vida
Haz tu luz resplandecer.
{eoc}

Cuídate que el mundo no se asombre
por un mal paso que en ti vea,
no deshonres de Jesús el santo nombre;
haz tu luz resplandecer.

{soc}
Haz tu luz resplandecer.
Haz tu luz resplandecer.
Brille Cristo solamente en nuestra vida
Haz tu luz resplandecer.
{eoc}

Caminando tú por plazas o por calles
en el hogar o en el taller,
digno ejemplo de un cristiano en ti se halle;
haz tu luz resplandecer.

{soc}
Haz tu luz resplandecer.
Haz tu luz resplandecer.
Brille Cristo solamente en nuestra vida
Haz tu luz resplandecer.
{eoc}

Del Señor alzad en alto la bandera
hasta morir o vencer.
Sé cristiano hasta el fin de la carrera;
haz tu luz resplandecer.

{soc}
Haz tu luz resplandecer.
Haz tu luz resplandecer.
Brille Cristo solamente en nuestra vida
Haz tu luz resplandecer.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-246-cual-ciudad-sobre-un-monte/)' where id = 'sa-himno-246-cual-ciudad-sobre-un-monte';
update public.songs set title = 'En La Guerra Contra El Pecado', lyrics = 'En la guerra contra el pecado,
vamos todos a combatir.
Estará Dios a nuestro lado
en tiempo de sufrir.
La victoria será nuestra
confiando en su poder.
Nos dará él su ayuda,
hemos todos de vencer.

{soc}
No, nosotros, nunca, nunca, cederemos al mal,
nunca, no, no, no. Nunca, no, no.
No, nosotros, nunca, nunca, cederemos al mal.
Nos espera la corona en el cielo.
{eoc}

Pelearemos con toda fuerza
los demonios del mal a destruir,
ayudando a los pecadores
el Calvario a subir.
Sin miedo de las burlas
del diablo y del mundo,
para Dios y para el alma
hemos todos de vivir.

{soc}
No, nosotros, nunca, nunca, cederemos al mal,
nunca, no, no, no. Nunca, no, no.
No, nosotros, nunca, nunca, cederemos al mal.
Nos espera la corona en el cielo.
{eoc}

Jesucristo es nuestra fuerza
su poder nunca faltará.
Su presencia nos esfuerza
y victoria nos dará.
Levantemos la bandera
del bendito salvador,
para que la gente sin temor
disfrute de su amor.

{soc}
No, nosotros, nunca, nunca, cederemos al mal,
nunca, no, no, no. Nunca, no, no.
No, nosotros, nunca, nunca, cederemos al mal.
Nos espera la corona en el cielo.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-247-en-la-guerra-contra-el-pecado/)' where id = 'sa-himno-247-en-la-guerra-contra-el-pecado';
update public.songs set title = 'Quieres Ser Salvo', lyrics = '¿Quieres ser salvo de toda maldad?
Tan sólo hay poder en mi Jesús.
¿Quieres vivir y gozar santidad?
Tan sólo hay poder en Jesús.

{soc}
Hay poder, poder, sin igual poder,
en Jesús, quien murió,
hay poder, poder, sin igual poder
en la sangre, que él vertió.
{eoc}

¿Quieres ser libre de orgullo y pasión?
Tan sólo hay poder en mi Jesús.
¿Quieres vencer toda cruel tentación?
Tan sólo hay poder en Jesús.

{soc}
Hay poder, poder, sin igual poder,
en Jesús, quien murió,
hay poder, poder, sin igual poder
en la sangre, que él vertió.
{eoc}

¿Quieres servir a tu rey Señor?
Tan sólo hay poder en Jesús.
Ven y ser salvo podrás en su amor;
tan sólo hay poder en Jesús.

{soc}
Hay poder, poder, sin igual poder,
en Jesús, quien murió,
hay poder, poder, sin igual poder
en la sangre, que él vertió.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-249-quieres-ser-salvo/)' where id = 'sa-himno-249-quieres-ser-salvo';
update public.songs set title = 'En Un Monte Lejano', lyrics = 'En un monte lejano diviso una cruz,
emblema de afrenta y dolor;
y yo amo esa cruz donde Cristo expiró
por salvar al más vil pecador.

{soc}
Yo me abrazo a esa cruz con amor
Hasta el día de mi mutación,
Cuando a Cristo mi cuenta le dé
Por su cruz yo corona tendré
{eoc}

Despreciada del mundo yo veo esa cruz
Que es centro de mi adoración;
Pues en ella el cordero sin mancha expiró,
Sacrificio de gran expiación.

{soc}
Yo me abrazo a esa cruz con amor
Hasta el día de mi mutación,
Cuando a Cristo mi cuenta le dé
Por su cruz yo corona tendré
{eoc}

Empapada de sangre yo veo esa cruz
Que es sangre preciosa en verdad,
Pues en ella mis culpas redime Jesús
Y dichosa mi alma será

{soc}
Yo me abrazo a esa cruz con amor
Hasta el día de mi mutación,
Cuando a Cristo mi cuenta le dé
Por su cruz yo corona tendré
{eoc}

A la cruz despreciada, yo leal he de ser,
Su escarnio no he de rehuir,
Mas un día Jesús ha de darme con él
Herencia eterna y feliz

{soc}
Yo me abrazo a esa cruz con amor
Hasta el día de mi mutación,
Cuando a Cristo mi cuenta le dé
Por su cruz yo corona tendré
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-252-en-un-monte-lejano/)' where id = 'sa-himno-252-en-un-monte-lejano';
update public.songs set title = 'La Mujer Samaritana', lyrics = 'La mujer samaritana
a sacar el agua va,
sin pensar que Jesucristo
esperando está.
Viene él en busca suya
para ser su salvador.
Su miseria y su pecado
sabe el Señor.

{soc}
Oye, pues, la gratas nuevas
“el Señor te salvará”,
“es el mismo Jesucristo
que esperando está”.
{eoc}

Escuchando la palabra
que revela su maldad,
recordando su pecado
compungida está.
Él le da el agua viva,
Él le da salvación,
Él le da la paz perfecta
y le da el perdón.

{soc}
Oye, pues, la gratas nuevas
“el Señor te salvará”,
“es el mismo Jesucristo
que esperando está”.
{eoc}

A su casa corre ella,
habla a todos de Jesús.
¿No será éste el mesías
que nos trae luz?
Y la gente convencida
va también al salvador,
y le piden que les hable
de su gran amor.

{soc}
Oye, pues, la gratas nuevas
“el Señor te salvará”,
“es el mismo Jesucristo
que esperando está”.
{eoc}

Ayer, hoy y por los siglos
es el mismo salvador,
es el mismo Jesucristo
y es el mismo amor.
Hoy te busca, hoy te llama,
no lo hagas esperar,
porque el tiempo oportuno
pronto pasará.

{soc}
Oye, pues, la gratas nuevas
“el Señor te salvará”,
“es el mismo Jesucristo
que esperando está”.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-253-la-mujer-samaritana/)' where id = 'sa-himno-253-la-mujer-samaritana';
update public.songs set title = 'Las Sendas Anchas Dejaré', lyrics = 'Las sendas anchas dejaré,
yo quiero por la angosta andar,
el mundo no sabrá por qué;
mas voy a mi celeste hogar.

{soc}
No puede el mundo ser mi hogar,
no puede el mundo ser mi hogar,
en gloria tengo mi mansión,
no puede el mundo ser mi hogar.
{eoc}

Algunos quieren verme ir
por los senderos de maldad;
oír no quiero su llamar
pues voy a mi celeste hogar.

{soc}
No puede el mundo ser mi hogar,
no puede el mundo ser mi hogar,
en gloria tengo mi mansión,
no puede el mundo ser mi hogar.
{eoc}

¡Oh, ven conmigo, pecador!
Y sigue en pos del salvador,
¿por qué no quieres tú buscar
la hermosa tierra “más allá”?

{soc}
No puede el mundo ser mi hogar,
no puede el mundo ser mi hogar,
en gloria tengo mi mansión,
no puede el mundo ser mi hogar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-254-las-sendas-anchas-dejare/)' where id = 'sa-himno-254-las-sendas-anchas-dejare';
update public.songs set title = 'El Señor Jesús Está Llamando', lyrics = 'El Señor Jesús está llamando.
¿Quién irá por mí a trabajar?
¿Quién a mí traerá a los que se pierden
y el camino les ha de enseñar?

{soc}
Háblame, háblame
y tu voz yo presto acataré.
Háblame, ¡Oh, Señor!
Y tu voz yo presto acataré.
{eoc}

Cuando el trozo de carbón ardiente
al profeta fiel purificó;
al oír la voz que le llamaba
“¡mándame, Señor!”, le respondió.

{soc}
Háblame, háblame
y tu voz yo presto acataré.
Háblame, ¡Oh, Señor!
Y tu voz yo presto acataré.
{eoc}

Hay millones que en pecado mueren,
escuchad su tétrico gemir;
acudid con tiempo a rescatarles.
¿Quién dirá “Señor, yo quiero ir”?

{soc}
Háblame, háblame
y tu voz yo presto acataré.
Háblame, ¡Oh, Señor!
Y tu voz yo presto acataré.
{eoc}

Pronto el tiempo de la siega pasa,
pronto iremos al celeste Edén;
ojalá en aquel solemne día
él me diga: “hijo hiciste bien”.

{soc}
Háblame, háblame
y tu voz yo presto acataré.
Háblame, ¡Oh, Señor!
Y tu voz yo presto acataré.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-256-el-senor-jesus-esta-llamando/)' where id = 'sa-himno-256-el-senor-jesus-esta-llamando';
update public.songs set title = 'Muchas Cosas En Los Cielos', lyrics = 'Muchas cosas en los cielos los niños tendrán,
preparadas por su rey Jesús.
Ropas blancas, coronas de oro y también
lindas arpas las que tocarán.

{soc}
Muchas cosas habrá, muchas cosas tendrán.
Muchas cosas veremos allá,
¡Oh, qué felicidad! Cuando estemos allí
cuántas cosas serán para mí.
{eoc}

En el cielo las calles de oro serán
y en ellas los niños pasearán,
y felices como ángeles cantarán
al cordero que nos rescató.

{soc}
Muchas cosas habrá, muchas cosas tendrán.
Muchas cosas veremos allá,
¡Oh, qué felicidad! Cuando estemos allí
cuántas cosas serán para mí.
{eoc}

Junto al río de la vida se alegrarán
y el pan de la vida tendrán;
no existe más noche, ni muerte, ni dolor,
pues los cuida Jesús con amor.

{soc}
Muchas cosas habrá, muchas cosas tendrán.
Muchas cosas veremos allá,
¡Oh, qué felicidad! Cuando estemos allí
cuántas cosas serán para mí.
{eoc}

De los niños el reino de los cielos será
y en brazos de Jesús descansarán.
Cantarán sin cesar en presencia del Señor,
danzarán rebosando de amor.

{soc}
Muchas cosas habrá, muchas cosas tendrán.
Muchas cosas veremos allá,
¡Oh, qué felicidad! Cuando estemos allí
cuántas cosas serán para mí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-257-muchas-cosas-en-los-cielos/)' where id = 'sa-himno-257-muchas-cosas-en-los-cielos';
update public.songs set title = '¡Oh! Mi Corazón Rebosa De Gozo', lyrics = '¡Oh! Mi corazón rebosa de gozo,
porque Dios me perdonó en su amor;
sirviéndolo a él estoy dichoso,
voy al cielo do está mi salvador.

{soc}
Voy subiendo en áurea escalera,
voy subiendo do corona me espera,
voy subiendo en la luz, voy subiendo con Jesús.
Alabanzas cantaré a Dios allá.
Voy subiendo en áurea escalera,
voy subiendo do corona me espera.
Voy subiendo en la luz, voy subiendo con Jesús.
Voy subiendo a mi celeste hogar.
{eoc}

Cada día quiero serle más constante,
cada día quiero serle más leal;
ayudado por su gracia abundante
que procede de mi padre celestial.

{soc}
Voy subiendo en áurea escalera,
voy subiendo do corona me espera,
voy subiendo en la luz, voy subiendo con Jesús.
Alabanzas cantaré a Dios allá.
Voy subiendo en áurea escalera,
voy subiendo do corona me espera.
Voy subiendo en la luz, voy subiendo con Jesús.
Voy subiendo a mi celeste hogar.
{eoc}

Hallo gran placer llevando pecadores,
pobres, ricos de cualquiera condición,
a aquel que en la cruz sufrió dolores
para dar a todos plena salvación.

{soc}
Voy subiendo en áurea escalera,
voy subiendo do corona me espera,
voy subiendo en la luz, voy subiendo con Jesús.
Alabanzas cantaré a Dios allá.
Voy subiendo en áurea escalera,
voy subiendo do corona me espera.
Voy subiendo en la luz, voy subiendo con Jesús.
Voy subiendo a mi celeste hogar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-259-oh-mi-corazon-rebosa-de-gozo/)' where id = 'sa-himno-259-oh-mi-corazon-rebosa-de-gozo';
update public.songs set title = 'Pienso Ahora', lyrics = 'Pienso ahora en aquel reluciente hogar
do por siglos sin fin viviré;
en aquella mansión yo quiero ver brillar
la corona que Cristo me dé.

{soc}
¡Oh! Que brillen allí como estrellas de luz
redimidos que a Cristo guié.
Cuando allá corona me entregue Jesús,
la corona que Cristo me dé.
Con la fuerza divina podré trabajar,
velaré, oraré sin cesar,
para Dios muchas almas espero ganar
y veré mi corona brillar.
{eoc}

{soc}
¡Oh! Que brillen allí como estrellas de luz
redimidos que a Cristo guié.
Cuando allá corona me entregue Jesús,
la corona que Cristo me dé.
{eoc}

¡Oh! Qué gozo en los cielos será para mí
joyas vivas para poner a sus pies,
recibiendo de él la corona que allí
resplandezca con gran brillantes.

{soc}
¡Oh! Que brillen allí como estrellas de luz
redimidos que a Cristo guié.
Cuando allá corona me entregue Jesús,
la corona que Cristo me dé.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-260-pienso-ahora/)' where id = 'sa-himno-260-pienso-ahora';
update public.songs set title = 'Quiero Cantar a Mi Rey', lyrics = 'Quiero cantar a mi rey salvador
por su inmenso amor,
que me ha salvado y me ha dado su luz.
Gloria aleluya, a Jesús.

Quiero hablar del amor de Jesús
para el infiel pecador,
quiero en su sangre vertida en la cruz
todo mi cuerpo lavar.

Quiero vivir cerca de mi Jesús
y obtener mi hogar,
en las mansiones de gloria y luz
allí por siempre gozar.

Quiero vivir obediente a Jesús
y terminar mi carrera,
en lo que Cristo me ha puesto aquí
como atalaya en la tierra.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-261-quiero-cantar-a-mi-rey/)' where id = 'sa-himno-261-quiero-cantar-a-mi-rey';
update public.songs set title = '¿Quién Está de Parte?', lyrics = '¿Quién esta de parte del buen salvador,
pronto a dedicarse ahora a su Señor,
y que abandonando su falaz vivir,
quiere aquí servirle y aún por él sufrir?

{soc}
¿Quién de Cristo al lado quiere caminar?
¿Quién contra el pecado quiere ya luchar?
Quien esté agobiado o sufra aflicción,
venga a Cristo que le llama hoy con amor.
{eoc}

Cristo está llamando, ven a él pecador,
quiere él librarte de eternal dolor,
venga el que hoy errante va en la obscuridad,
venga pronto que el gran día cerca está.

{soc}
¿Quién de Cristo al lado quiere caminar?
¿Quién contra el pecado quiere ya luchar?
Quien esté agobiado o sufra aflicción,
venga a Cristo que le llama hoy con amor.
¿Quién dirá hoy mismo: “heme aquí, Señor,
¡oh! Jesús, tus pasos quiero yo seguir”?
¿Quién querrá hoy mismo el mundo dejar
y seguir a Cristo y aun por él morir?
{eoc}

{soc}
¿Quién de Cristo al lado quiere caminar?
¿Quién contra el pecado quiere ya luchar?
Quien esté agobiado o sufra aflicción,
venga a Cristo que le llama hoy con amor.
{eoc}

La batalla ruda siempre habrá de ser,
enemigos fuertes hemos de tener,
mas potente es Cristo, nuestro capitán:
ha vencido ya las huestes de Satán.

{soc}
¿Quién de Cristo al lado quiere caminar?
¿Quién contra el pecado quiere ya luchar?
Quien esté agobiado o sufra aflicción,
venga a Cristo que le llama hoy con amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-262-quien-esta-de-parte/)' where id = 'sa-himno-262-quien-esta-de-parte';
update public.songs set title = 'Yo Quiero Trabajar', lyrics = 'Yo quiero trabajar, por mi Señor
confiado en su palabra y en su amor.
Quiero yo cantar y orar
y, ocupado siempre estar
en la viña del Señor.

{soc}
Trabajad y orad
en la viña, en la viña del Señor.
Sí, mi anhelo es orar
y ocupado siempre estar
en la viña del Señor.
{eoc}

Yo quiero día por día trabajar
y esclavos del pecado libertar,
conducirlos a Jesús,
nuestro guía, nuestra luz,
en la viña del Señor.

{soc}
Trabajad y orad
en la viña, en la viña del Señor.
Sí, mi anhelo es orar
y ocupado siempre estar
en la viña del Señor.
Yo quiero ser obrero de valor
confiado en el poder del salvador,
y el que quiera trabajar
hallará también lugar
en la viña del Señor.
{eoc}

{soc}
Trabajad y orad
en la viña, en la viña del Señor.
Sí, mi anhelo es orar
y ocupado siempre estar
en la viña del Señor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-263-yo-quiero-trabajar/)' where id = 'sa-himno-263-yo-quiero-trabajar';
update public.songs set title = 'Cantan Los Ángeles', lyrics = 'Cantan los ángeles con dulce voz,
cantan los hombres con sonora voz,
Cristo vendrá, nuestro rey salvador,
Cristo vendrá otra vez.

{soc}
Viene otra vez, viene otra vez
en gloria viene al mundo otra vez
viene otra vez, viene otra vez,
el viene prono a reinar.
{eoc}

Ved en la tierra los aires y el mar
cuántas señales cumpliéndose ya,
todo indicando que pronto vendrá
nuestro glorioso Señor.

{soc}
Viene otra vez, viene otra vez
en gloria viene al mundo otra vez
viene otra vez, viene otra vez,
el viene prono a reinar.
{eoc}

Todos los muertos en Cristo saldrán
de sus sepulcros y alegres irán,
para encontrar a su rey vencedor,
Cristo vendrá otra vez.

{soc}
Viene otra vez, viene otra vez
en gloria viene al mundo otra vez
viene otra vez, viene otra vez,
el viene prono a reinar.
{eoc}

Ven en las nubes, oh, buen salvador.
Ven a la tierra glorioso a reinar.
Ven que tu iglesia te espera Señor.
Cristo vendrá otra vez.

{soc}
Viene otra vez, viene otra vez
en gloria viene al mundo otra vez
viene otra vez, viene otra vez,
el viene prono a reinar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-264-cantan-los-angeles/)' where id = 'sa-himno-264-cantan-los-angeles';
update public.songs set title = 'Si Yo Tuviera De La Mañana', lyrics = 'Si yo tuviera de la mañana
las raudas alas para volar,
yo muy contento me trasladara
a las riberas de Canaán.

{soc}
Ángeles blancos me llevarán
a la presencia de mi Señor,
y yo con júbilo cantaría
con los salvados por su amor.
{eoc}

Allí no hay llanto, no hay amargura,
allí no se sabe lo que es dolor,
allí es todo luz y alegría,
allí todo es amor.

{soc}
Ángeles blancos me llevarán
a la presencia de mi Señor,
y yo con júbilo cantaría
con los salvados por su amor.
{eoc}

Vestidos blanco, palma y corona
cada uno de ellos visten allí,
y sé ahora que si soy fiel,
vestido blanco hay para mí.

{soc}
Ángeles blancos me llevarán
a la presencia de mi Señor,
y yo con júbilo cantaría
con los salvados por su amor.
{eoc}

Allí no hay llanto, no hay despedida,
allí nunca se dice adiós,
porque allí siempre reinaremos
junto a Cristo nuestro Señor.

{soc}
Ángeles blancos me llevarán
a la presencia de mi Señor,
y yo con júbilo cantaría
con los salvados por su amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-266-si-yo-tuviera-de-la-manana/)' where id = 'sa-himno-266-si-yo-tuviera-de-la-manana';
update public.songs set title = 'La Venida De Cristo', lyrics = 'La venida de Cristo se acerca,
pronto viene su iglesia a buscar
no durmamos, estemos alerta,
vigilad, vigilad, vigilad.

{soc}
Pronto viene Jesús y nos lleva
a la hermosa mansión celestial,
pronto viene Jesús a la tierra;
nos iremos con él a gozar.
{eoc}

Si queremos que Cristo nos lleve
a los cielos con él a reinar,
no seamos jamás negligentes;
trabajad, trabajad, trabajad.

{soc}
Pronto viene Jesús y nos lleva
a la hermosa mansión celestial,
pronto viene Jesús a la tierra;
nos iremos con él a gozar.
{eoc}

Arreglemos, estemos a cuenta
con Jesús el cordero inmortal,
del que ofende tengamos clemencia,
perdonad, perdonad, perdonad.

{soc}
Pronto viene Jesús y nos lleva
a la hermosa mansión celestial,
pronto viene Jesús a la tierra;
nos iremos con él a gozar.
{eoc}

Perdonando, Jesús nos perdona,
y a los cielos nos lleva a reinar,
ganaremos también la corona;
vigilad, trabajad, perdonad.

{soc}
Pronto viene Jesús y nos lleva
a la hermosa mansión celestial,
pronto viene Jesús a la tierra;
nos iremos con él a gozar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-268-la-venida-de-cristo/)' where id = 'sa-himno-268-la-venida-de-cristo';
update public.songs set title = 'Con El Alma Entristecida', lyrics = 'Con el alma entristecida
vengo a ti mi salvador
pues sentí tu gran ternura
y lo inmenso de tu amor.
Falsa paz ofrece el mundo,
sólo tú me das solaz,
¡oh, Jesús, amparo mío,
fiel y pura mi alma haz!.

{soc}
Yo creo sí, yo creo sí,
Jesús murió, murió por mi,
y en la cruz vertida fue
su sangre carmesí.
{eoc}

Cristo mío, veo al mundo
que se aleja de su Dios;
veo al hombre desprovisto,
de tu oferta y de tu voz,
esa vida tan torcida
nunca más voy a seguir,
con tu ayuda Cristo mío
quiero para ti vivir.

{soc}
Yo creo sí, yo creo sí,
Jesús murió, murió por mi,
y en la cruz vertida fue
su sangre carmesí.
{eoc}

Muy obscura fue la senda
por la cual me encaminé,
mas, tu tierno amor me trajo,
y contrito me humillé.
Heme, pues, aquí en tus plantas,
¡oh, perdona mi maldad!
No desoigas mis plegarias
sálvame por tu bondad.

{soc}
Yo creo sí, yo creo sí,
Jesús murió, murió por mi,
y en la cruz vertida fue
su sangre carmesí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-269-con-el-alma-entristecida/)' where id = 'sa-himno-269-con-el-alma-entristecida';
update public.songs set title = 'Corazones Inflamados', lyrics = 'Corazones inflamados,
puros, llenos de fervor,
que a sí mismo no adoran,
mas emanan santo amor.
Corazones que valientes,
por vencidos no se dan,
a su rey desean gloria
y la lucha ganarán.

Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.
Corazones que palpitan
fieles siempre a Jesús,
que a la humanidad proclaman
el mensaje de la cruz.
Corazones abnegados
cuyo lema es amor,
todos alegres lo consagran
a la gloria del Señor.

{soc}
Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.
Corazones que palpitan
fieles siempre a Jesús,
que a la humanidad proclaman
el mensaje de la cruz.
Corazones abnegados
cuyo lema es amor,
todos alegres lo consagran
a la gloria del Señor.
Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.
{eoc}

Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.

Corazones nobles que aman
al caído y le dan luz,
no son tibios, ni cobardes,
sino fieles a Jesús.
Corazones que con gozo
dando todo con amor,
y con Cristo participan
sufrimientos con valor.

{soc}
Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.
Corazones que palpitan
fieles siempre a Jesús,
que a la humanidad proclaman
el mensaje de la cruz.
Corazones abnegados
cuyo lema es amor,
todos alegres lo consagran
a la gloria del Señor.
Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.
{eoc}

Ellos alzan la bandera,
do la lucha arde ya;
ya no ceden al peligro,
pues su rey con ellos va.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-270-corazones-inflamados/)' where id = 'sa-himno-270-corazones-inflamados';
update public.songs set title = 'Cuando El Verbo Terminó', lyrics = 'Cuando el verbo terminó
de formar la creación,
formó al hombre y la mujer,
y en ella los colocó:
sin tener que trabajar,
adorando sólo a Dios,
y por desobedecer
la muerte se ejecutó.

{soc}
Oh, qué triste es el morir,
oh, qué dicha es el pensar,
ver que Cristo nos redime
para su gloria reinar.
{eoc}

Dios al mundo iluminó
con sus luces brujular,
con estrellas, luna y sol
a toda la humanidad.
Y de un árbol les vedó
que no pudieran probar.
Cuando el Señor los llamó
desnudos los encontró.

{soc}
Oh, qué triste es el morir,
oh, qué dicha es el pensar,
ver que Cristo nos redime
para su gloria reinar.
{eoc}

La tierra ensoberbeció,
con todo el reino animal;
el hombre que la labró
hubo espinas cosechar,
en la frente su sudor
hubo de comer su pan,
y así paga la pena
todo mísero mortal.

{soc}
Oh, qué triste es el morir,
oh, qué dicha es el pensar,
ver que Cristo nos redime
para su gloria reinar.
{eoc}

La serpiente que engañó
a nuestro padre Adán,
cantó gloria en la mujer
para el infierno ganar.
Mas, un hijo que engendró
una virgen en Belén,
su cabeza quebrantó
para nunca más volver.

{soc}
Oh, qué triste es el morir,
oh, qué dicha es el pensar,
ver que Cristo nos redime
para su gloria reinar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-271-cuando-el-verbo-termino/)' where id = 'sa-himno-271-cuando-el-verbo-termino';
update public.songs set title = 'De La Tierra De Egipto', lyrics = 'De la tierra de Egipto yo vengo,
desde allá me sacó mi Señor;
mensajero enviado a mi pueblo,
el mensaje de eterna salvación.

{soc}
Bendito el Señor, bendito es su amor,
que tuvo de mí compasión;
enfermo me encontraba,
desamparado me hallaba
cuando vino mi bendito salvador.
{eoc}

Ya mi vida se estaba terminando,
en este mundo de tanto dolor;
aburrido e intranquilo me hallaba,
cuando vino mi bendito salvador.

{soc}
Bendito el Señor, bendito es su amor,
que tuvo de mí compasión;
enfermo me encontraba,
desamparado me hallaba
cuando vino mi bendito salvador.
{eoc}

De la tierra del martirio vengo
a pedirle perdón al Señor;
el pecado me tenía atado
a este mundo de tanto dolor.

{soc}
Bendito el Señor, bendito es su amor,
que tuvo de mí compasión;
enfermo me encontraba,
desamparado me hallaba
cuando vino mi bendito salvador.
{eoc}

Hoy vivimos felices y contentos,
con su sangre lavó mi corazón,
esperando que cuando él nos llame,
gozaremos con Él en la mansión.

{soc}
Bendito el Señor, bendito es su amor,
que tuvo de mí compasión;
enfermo me encontraba,
desamparado me hallaba
cuando vino mi bendito salvador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-272-de-la-tierra-de-egipto/)' where id = 'sa-himno-272-de-la-tierra-de-egipto';
update public.songs set title = 'De Jesús Escucha el Tierno Llamamiento', lyrics = 'De Jesús escucha el tierno llamamiento
ven a él, pecador;
quiere darte su perdón, paz y contento,
ven a él, pecador.

{soc}
Te llama con un tierno acento,
tu vida quiere redimir;
oye de Jesús el tierno llamamiento;
ven a él, ven a él.
{eoc}

Sólo él puede pleno gozo concederte,
ven a él, pecador;
en odiosa cruz por ti encontró la muerte,
ven a él, pecador.

{soc}
Te llama con un tierno acento,
tu vida quiere redimir;
oye de Jesús el tierno llamamiento;
ven a él, ven a él.
{eoc}

No su voz de amor escuches, con desprecio
ven a él, pecador;
por tu salvación pagó divino precio;
ven a él, pecador.

{soc}
Te llama con un tierno acento,
tu vida quiere redimir;
oye de Jesús el tierno llamamiento;
ven a él, ven a él.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-274-de-jesus-escucha-el-tierno/)' where id = 'sa-himno-274-de-jesus-escucha-el-tierno';
update public.songs set title = 'El Evangelio', lyrics = 'El evangelio es nuestro lema,
la ley de Cristo es nuestro honor.
Del sacrificio somos cristianos
y evangelistas de la nación,
si el mal acecha nuestra doctrina
por la ignorancia y la corrupción
vamos sin miedo contra el pecado
somos de Cristo el rey de amor.

Nuestro estandarte flamea el viento,
somos gigantes de la verdad,
nuestros mensajes son el acento,
con que las almas se salvarán.

Triste es la vida de los que ignoran
el evangelio de salvación,
sus almas sufren, sus ojos lloran,
porque desprecian al salvador.
Sigue adelante evangelista
sin preocuparte de Satanás,
lleva el mensaje de Jesucristo
y vida eterna recibirás.

Adiós amigos, adiós hermanos,
ustedes quedan en oración,
yo voy en busca de almas perdidas
para traerlas al salvador.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-275-el-evangelio/)' where id = 'sa-himno-275-el-evangelio';
update public.songs set title = 'El Calvario', lyrics = 'En Calvario horrenda cruz se vio,
la cruz de mi Señor.
El pecado de mi corazón
lo llevó mi salvador.

{soc}
Oh, la sangre divina,
oh, la sangre eficaz,
derramada fue por ti.
El murió por mí, pecador, por ti.
Mi Jesús murió por mí.
{eoc}

El redentor su sangre dio,
rescate fue por mí.
A mis culpas todas puso fin
y me redimió así.

{soc}
Oh, la sangre divina,
oh, la sangre eficaz,
derramada fue por ti.
El murió por mí, pecador, por ti.
Mi Jesús murió por mí.
{eoc}

Yo te alabo, salvador tan fiel,
y te tengo que llorar
al mirarte en esa cruz tan cruel,
tú moriste por salvar.

{soc}
Oh, la sangre divina,
oh, la sangre eficaz,
derramada fue por ti.
El murió por mí, pecador, por ti.
Mi Jesús murió por mí.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-276-el-calvario/)' where id = 'sa-himno-276-el-calvario';
update public.songs set title = 'En El Cielo Una Morada', lyrics = 'En el cielo una morada
Cristo fue a preparar
para todo aquel que hiciere
su divina voluntad.

{soc}
Gozo eterno hay en el cielo.
Allí cantan de alegría
los salvados por Jesús
que han sido fieles en la vida.
{eoc}

Somos fieles los cristianos,
somos fieles a Jesús.
Abracemos con el alma
el evangelio de salud.

{soc}
Gozo eterno hay en el cielo.
Allí cantan de alegría
los salvados por Jesús
que han sido fieles en la vida.
{eoc}

Somos probados los cristianos
como el oro en el crisol,
y la sangre de Jesucristo
lava y limpia el corazón.

{soc}
Gozo eterno hay en el cielo.
Allí cantan de alegría
los salvados por Jesús
que han sido fieles en la vida.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-277-en-el-cielo-una-morada/)' where id = 'sa-himno-277-en-el-cielo-una-morada';
update public.songs set title = 'Ha Nacido El Salvador', lyrics = 'Ha nacido el salvador
en los campos de Belén,
que oyó con esplendor
la canción del nuevo Edén.
Luz resplandeció en el cielo
anunciando al salvador.
Se cumplieron los anhelos
que viniera al redentor.

Ningún santo que ha nacido
fue anunciado como él,
el mesías prometido
el divino Emmanuel.
En el cielo se ha sentido
regocijo angelical,
ya en la tierra se ha cumplido
la promesa eternal.

Se alegraron los pastores
al sentir la bendición,
gloria a Dios en las alturas
fue la celeste canción.
A los reyes del oriente
ha guiado con su luz
una estrella esplendente
al pesebre de Jesús.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-278-ha-nacido-el-salvador/)' where id = 'sa-himno-278-ha-nacido-el-salvador';
update public.songs set title = 'Hubo Uno', lyrics = 'Hubo uno que quiso por mí padecer
y morir por mi alma salvar,
el camino más cruel a la cruz recorrer
para así mis pecados lavar.

{soc}
En la cruz, en la cruz mis pecados lavó
cuando quiso por mí padecer.
Con angustias en la cruz
fue el benigno Jesús
que por siempre mis culpas borró.
{eoc}

Él es tierno y amante cual nadie lo fue
pues convierte al infiel corazón
y por esa paciencia y ternura yo sé
que soy libre de condenación.

{soc}
En la cruz, en la cruz mis pecados lavó
cuando quiso por mí padecer.
Con angustias en la cruz
fue el benigno Jesús
que por siempre mis culpas borró.
{eoc}

Es mi anhelo constante a Cristo seguir
mi camino su ejemplo marcó
y por darme la vida Él quiso morir
en la cruz mis pecados lavó.

{soc}
En la cruz, en la cruz mis pecados lavó
cuando quiso por mí padecer.
Con angustias en la cruz
fue el benigno Jesús
que por siempre mis culpas borró.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-279-hubo-uno/)' where id = 'sa-himno-279-hubo-uno';
update public.songs set title = 'Hay Un Canto Nuevo', lyrics = 'Hay un canto nuevo en mi ser,
es la voz de mi Jesús,
que me dice:
“ven a descansar.
Tu paz conquisté en Jesús”.

{soc}
Cristo, Cristo, Cristo,
nombre sin igual.
Llena siempre mi alma
de esa nota celestial.
Náufrago en pecado me encontré,
sin paz en mi corazón,
más en Cristo, mi Señor, hallé
dulce paz y protección.
{eoc}

{soc}
Cristo, Cristo, Cristo,
nombre sin igual.
Llena siempre mi alma
de esa nota celestial.
{eoc}

Tengo de su gracia celestial
bajo sus alas de amor,
riquezas que fluye a raudal
desde el trono del Señor.

{soc}
Cristo, Cristo, Cristo,
nombre sin igual.
Llena siempre mi alma
de esa nota celestial.
{eoc}

Cristo en las nubes volverá,
bajo el bello cielo azul,
Él entonces mi alma llevará
a vivir en gloria y luz.

{soc}
Cristo, Cristo, Cristo,
nombre sin igual.
Llena siempre mi alma
de esa nota celestial.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-281-hay-un-canto-nuevo/)' where id = 'sa-himno-281-hay-un-canto-nuevo';
update public.songs set title = 'La Patria Necesita', lyrics = 'La patria necesita
privarse de maldad,
para que en sus hogares
reine felicidad.

{soc}
Para entrar al cielo
y estar con el Señor
se le previene al hombre
limpiar su corazón.
{eoc}

Alerta, mis hermanos,
pidamos a Jesús
que Chile todo entero
conozca su virtud.

{soc}
Para entrar al cielo
y estar con el Señor
se le previene al hombre
limpiar su corazón.
{eoc}

Porque ya el fin se acerca
y a cuentas llamará,
y toda alma sucia
al cielo no entrará.

{soc}
Para entrar al cielo
y estar con el Señor
se le previene al hombre
limpiar su corazón.
{eoc}

Ya estamos convencidos
con nuestro salvador,
que quita nuestras penas
con su ferviente amor.

{soc}
Para entrar al cielo
y estar con el Señor
se le previene al hombre
limpiar su corazón.
{eoc}

Lávate en la sangre
del Señor Jesús
porque ella es la que tiene
toda la virtud.

{soc}
Para entrar al cielo
y estar con el Señor
se le previene al hombre
limpiar su corazón.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-283-la-patria-necesita/)' where id = 'sa-himno-283-la-patria-necesita';
update public.songs set title = 'Muy Triste En Pecado', lyrics = 'Muy triste en pecado y en noches me vi,
mas yo vivo alegre: Jesús me salvó;
y todos los días yo canto a Jesús,
yo ando con Cristo, mi Maestro y Rey.

{soc}
Yo voy con Jesús, aleluya,
yo ando con Cristo el Rey;
no vago ya más: yo quiero seguir
a Cristo mi Rey y Señor.
{eoc}

Por años y años sin Cristo viví
y nunca en la vida feliz yo me vi.
Mas hoy con las aves elevo mi voz
y canto feliz, pues yo voy con el Rey.

{soc}
Yo voy con Jesús, aleluya,
yo ando con Cristo el Rey;
no vago ya más: yo quiero seguir
a Cristo mi Rey y Señor.
{eoc}

Oh alma que estás en el valle sin luz,
si miras arriba, verás a Jesús.
Ven pronto, más cerca, ven pronto a la luz,
es Cristo la luz aún más fuerte que el sol.

{soc}
Yo voy con Jesús, aleluya,
yo ando con Cristo el Rey;
no vago ya más: yo quiero seguir
a Cristo mi Rey y Señor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-285-muy-triste-en-pecado/)' where id = 'sa-himno-285-muy-triste-en-pecado';
update public.songs set title = 'Habrá Grandes Lluvias', lyrics = 'Habrá grandes lluvias de bendición
si traemos diezmos hoy al alfolí,
demostrando así la consagración
si traemos nuestros diezmos.

{soc}
Diezmos sí, de amor y servicio
y también de oro y plata;
si traemos nuestros diezmos,
si traemos nuestros diezmos,
bendiciones grandes abundarán
si traemos nuestros diezmos
El dará triunfos a su grey acá,
Dios la librará de toda maldad,
a reinar el príncipe de paz vendrá
si traemos nuestros diezmos.
{eoc}

{soc}
Diezmos sí, de amor y servicio
y también de oro y plata;
si traemos nuestros diezmos,
si traemos nuestros diezmos,
bendiciones grandes abundarán
si traemos nuestros diezmos
{eoc}

No robemos nunca más a nuestro rey.
Mas no demos nada por obligación,
que el amor nos constriñe más que la ley
a traer todos los diezmos.

{soc}
Diezmos sí, de amor y servicio
y también de oro y plata;
si traemos nuestros diezmos,
si traemos nuestros diezmos,
bendiciones grandes abundarán
si traemos nuestros diezmos
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-286-habra-grandes-lluvias/)' where id = 'sa-himno-286-habra-grandes-lluvias';
update public.songs set title = 'Sal a Sembrar', lyrics = 'Sal a sembrar, sembrador de paz,
sigue las huellas del buen Jesús,
muy ricos frutos tendrás, si fiel
sigues la senda de paz y luz.

Ve, ve, ve, sembrador,
ve, ve, siembra la paz,
habla doquiera del Señor
y de su santa paz.

Vasto es el campo, sal a sembrar,
siembra el terreno doquiera vas.
Si siembras siempre confiando en Dios
Él tus fuerzas coronará.

No desperdicies el tiempo, ve,
siembra palabras de vida y paz,
semilla eterna que dé su mies,
rica semilla que no es fugaz.

Dios lo ha mandado, sal a sembrar
nuevas de vida, de amor y paz,
tal vez te cueste dolores mil,
mas en los cielos tendrás solaz.

Voy, voy, voy, salvador.
Voy, voy, siembro la paz,
hablando siempre del Señor,
y de su santa paz.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-287-sal-a-sembrar/)' where id = 'sa-himno-287-sal-a-sembrar';
update public.songs set title = 'Son Verdades Reveladas', lyrics = 'Son verdades reveladas:
que existe un Dios creador,
y la gloria dará al justo,
el infierno al pecador.

{soc}
Creo en Dios, en Dios espero,
amo a Dios mi redentor.
Creo en Dios que me salvó,
en el cual hay salvación.
{eoc}

Es un Dios en tres personas
iguales en perfección:
Padre, hijo y Espíritu Santo,
no hay más que un solo Dios.

{soc}
Creo en Dios, en Dios espero,
amo a Dios mi redentor.
Creo en Dios que me salvó,
en el cual hay salvación.
{eoc}

El hijo se hizo hombre
sin dejar de ser Dios,
en la cruz su sangre dio
para nuestra redención.

{soc}
Creo en Dios, en Dios espero,
amo a Dios mi redentor.
Creo en Dios que me salvó,
en el cual hay salvación.
{eoc}

Predico el santo evangelio
y clavado en la cruz murió.
Para lavarnos a todos
él su sangre derramó.

{soc}
Creo en Dios, en Dios espero,
amo a Dios mi redentor.
Creo en Dios que me salvó,
en el cual hay salvación.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-288-son-verdades-reveladas/)' where id = 'sa-himno-288-son-verdades-reveladas';
update public.songs set title = 'Señor de los Cielos', lyrics = 'Señor de los cielos, dame hoy a mí
la paz, a mi alma que quiero de ti.
Sólo en ti yo encuentro la paz y el amor.
Y tú le das vida a mi corazón.

{soc}
Señor, te imploro la paz a mi alma,
y quema el pecado de mi corazón,
yo quiero la dicha, la paz y el consuelo,
y vivir tranquilo en tu santo amor.
{eoc}

Alégrate, alma, en noches de amor,
que Cristo ya viene a tu corazón,
si estás angustiado por algún pesar,
hoy clama a Cristo, y él te salvará.

{soc}
Señor, te imploro la paz a mi alma,
y quema el pecado de mi corazón,
yo quiero la dicha, la paz y el consuelo,
y vivir tranquilo en tu santo amor.
No tengo más penas, ya te conocí;
viniste a mí cuando yo te busqué.
Quisiera ya nunca dejarte, Señor,
quisiera que todos sintieran tu amor.
{eoc}

{soc}
Señor, te imploro la paz a mi alma,
y quema el pecado de mi corazón,
yo quiero la dicha, la paz y el consuelo,
y vivir tranquilo en tu santo amor.
Así mis hermanos, Cristo, ya vendrá,
y el alma angustiada Cristo avivará,
seguir el camino que Cristo trazó,
lavaos en la sangre que nos rescató.
{eoc}

{soc}
Señor, te imploro la paz a mi alma,
y quema el pecado de mi corazón,
yo quiero la dicha, la paz y el consuelo,
y vivir tranquilo en tu santo amor.
>
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-290-senor-de-los-cielos/)' where id = 'sa-himno-290-senor-de-los-cielos';
update public.songs set title = 'Quisiera Contarles', lyrics = 'Quisiera contarles en esta canción,
¿usted sabe, hermano, quién era sansón?
Dotado de fuerza sin comparación,
terrible, valiente y de gran corazón.
Sentía en su pecho un loca pasión:
amaba a su pueblo, el pueblo de Dios.

{soc}
Humildes como el Señor,
valientes como sansón,
prediquemos sin temor,
digamos al pecador
en la cruz murió el Señor
por darnos la redención.
{eoc}

Tampoco ignoramos aquel amor,
sabemos la causa de la traición,
por eso sabemos al siervo de Dios
matar filisteos sin comparación.
Luchaba por causa de aquel gran amor,
luchaba por causa de la redención.

{soc}
Humildes como el Señor,
valientes como sansón,
prediquemos sin temor,
digamos al pecador
en la cruz murió el Señor
por darnos la redención.
{eoc}

Quisiera contaros en esta canción
la historia completa de este gran varón,
pero usted sabe toda la pasión.
Pasemos al caso de nuestro Señor:
el nuevo caudillo, el hijo de Dios,
valiente y humilde sin comparación.

{soc}
Humildes como el Señor,
valientes como sansón,
prediquemos sin temor,
digamos al pecador
en la cruz murió el Señor
por darnos la redención.
{eoc}

Sabemos de Cristo toda la pasión,
también conocemos a judas traidor,
también pedro niega al buen salvador,
tenemos al mundo en contra de Dios.
Sabemos de Cristo lo que padeció,
yo tuve la culpa, un vil pecador.

{soc}
Humildes como el Señor,
valientes como sansón,
prediquemos sin temor,
digamos al pecador
en la cruz murió el Señor
por darnos la redención.
{eoc}

Amor más sublime el de nuestro Señor,
nadie lo ha sentido, ni el mismo sansón;
¿con qué pagaremos aquel gran amor?
Seamos humildes, como fue el Señor,
luchemos por Cristo, nuestro salvador.

{soc}
Humildes como el Señor,
valientes como sansón,
prediquemos sin temor,
digamos al pecador
en la cruz murió el Señor
por darnos la redención.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-291-quisiera-contarles/)' where id = 'sa-himno-291-quisiera-contarles';
update public.songs set title = 'Oh, Cristo Mío', lyrics = 'Oh, Cristo mío,
eres tú mi amigo fiel;
seguro amparo
sólo en ti tendré,
y en mis aflicciones,
buen Jesús, a ti iré
y consuelo y dicha
me darás a mí.

{soc}
Cristo, ven más cerca:
dame paz, gozo, perdón,
cerca, sí, más cerca
de mi corazón.
{eoc}

Cuando en la noche
vea yo estrellas mil,
tu voz divina
pueda mi alma oír.
Haz que yo medite
en tu tierno y dulce amor,
y que así te alabe
lleno de fervor.

{soc}
Cristo, ven más cerca:
dame paz, gozo, perdón,
cerca, sí, más cerca
de mi corazón.
{eoc}

Cuando esta vida
tenga yo que abandonar,
corona hermosa
tú me ceñirás;
y en tu dulce canto
tu bondad alabaré,
y en tu santa gloria
siempre moraré.

{soc}
Cristo, ven más cerca:
dame paz, gozo, perdón,
cerca, sí, más cerca
de mi corazón.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-294-oh-cristo-mio/)' where id = 'sa-himno-294-oh-cristo-mio';
update public.songs set title = 'Oh, Yo Quiero Andar Con Cristo', lyrics = 'Oh, yo quiero andar con Cristo
quiero oír su tierna voz,
meditar en su palabra,
y cumplir su voluntad,
consagrar a Él mi vida,
mis dolores y mi afán;
y algún día con mi Cristo
gozaré la claridad.

{soc}
Oh, sí, yo quiero andar con Cristo
oh, sí, yo quiero vivir con Cristo,
oh, sí, yo quiero morir con Cristo,
quiero serle un testigo fiel.
{eoc}

Oh, yo quiero andar con Cristo.
Él es mi ejemplo fiel;
en la Biblia yo lo leo,
y yo sé que es la verdad.
Cristo era santo en todo,
el cordero de la cruz,
y yo anhelo ser cristiano,
seguidor de mi Jesús.

{soc}
Oh, sí, yo quiero andar con Cristo
oh, sí, yo quiero vivir con Cristo,
oh, sí, yo quiero morir con Cristo,
quiero serle un testigo fiel.
{eoc}

Oh, yo quiero andar con Cristo,
de mi senda él es la luz,
dejaré el penoso mundo
para ir al salvador,
este mundo nada ofrece,
Cristo ofrece salvación;
y es mi única esperanza
vida eterna hallar en Dios

{soc}
Oh, sí, yo quiero andar con Cristo
oh, sí, yo quiero vivir con Cristo,
oh, sí, yo quiero morir con Cristo,
quiero serle un testigo fiel.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-295-oh-yo-quiero-andar-con-cristo/)' where id = 'sa-himno-295-oh-yo-quiero-andar-con-cristo';
update public.songs set title = 'Por ti, Oh Cristo', lyrics = 'Por ti, oh Cristo, yo tengo salvación,
por ti, oh Cristo, mi alma tiene paz.
Con tu muerte para mí se abrió el cielo,
y con amor perdonaste mi maldad.

{soc}
Y es por eso que yo digo al mundo
que en tu sangre hay salvación
Y remisión de pecados,
que tú diste tu vida allí en la cruz
por el justo y por el malvado.
{eoc}

Yo te ruego que guardes a tu iglesia
y bendigas a tus hijos, oh Señor,
que la llenes de tu Espíritu Santo,
para que así se convierta el pecador.

{soc}
Y es por eso que yo digo al mundo
que en tu sangre hay salvación
Y remisión de pecados,
que tú diste tu vida allí en la cruz
por el justo y por el malvado.
{eoc}

Yo te alabo porque me sacaste
de este mundo de vicios y de errores,
te prometo, serte fiel hasta muerte,
de no cumplirte, córtame, antes, oh Señor.

{soc}
Y es por eso que yo digo al mundo
que en tu sangre hay salvación
Y remisión de pecados,
que tú diste tu vida allí en la cruz
por el justo y por el malvado.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-296-por-ti-oh-cristo/)' where id = 'sa-himno-296-por-ti-oh-cristo';
update public.songs set title = 'Moro Yo En Las Alturas', lyrics = 'Moro yo en las alturas
donde encuentro gozo y paz,
en el país de la belleza
donde tú vivir podrás.
Es el país de la hermosura
do se cortan bellas flores
que derraman sus olores
en el alma del dolor.

{soc}
Nos será el país de beulah,
país feliz de luz y gozo
donde cantan aleluya
a Jesús, quien nos salvó.
{eoc}

Puedo ver de las alturas
como anduve en el error,
extraviado en las tinieblas
y las sombras del terror.
Dudas, votos quebrantados
sólo tuve en esa vida,
mas Jesús me conducía
a este país donde llegué.

{soc}
Nos será el país de beulah,
país feliz de luz y gozo
donde cantan aleluya
a Jesús, quien nos salvó.
{eoc}

Tomo de la fuente viva
ya gusté del río de vida,
satisfecha mi alma está
donde siempre quiero estar.
No apetezco los placeres
de este mundo en que moro,
porque en Cristo hay más tesoro,
yo en camino al cielo voy.

{soc}
Nos será el país de beulah,
país feliz de luz y gozo
donde cantan aleluya
a Jesús, quien nos salvó.
{eoc}

No me digas de las cruces
que no puedo yo cargar,
porque en Cristo habrá victoria,
en las que soportar.
Quiero yo seguir a Cristo
las vergüenzas despreciando,
los honores desechando
por las glorias de la cruz.

{soc}
Nos será el país de beulah,
país feliz de luz y gozo
donde cantan aleluya
a Jesús, quien nos salvó.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-298-moro-yo-en-las-alturas/)' where id = 'sa-himno-298-moro-yo-en-las-alturas';
update public.songs set title = 'Jesucristo Descendió', lyrics = 'Jesucristo descendió
a nacer en un pesebre
para hacer las almas libres
de la eterna perdición.

{soc}
Allá en Belén, nació la luz,
trajo también la paz Jesús.
De Israel el guiador
llegó con el amor.
{eoc}

Una sagrada canción
se oyó de voces puras,
gloria a Dios en las alturas
por la eterna redención.

{soc}
Allá en Belén, nació la luz,
trajo también la paz Jesús.
De Israel el guiador
llegó con el amor.
{eoc}

Hoy estamos en la luz
porque Dios es con nosotros;
vida eterna no hay en otros,
solamente en Jesús.

{soc}
Allá en Belén, nació la luz,
trajo también la paz Jesús.
De Israel el guiador
llegó con el amor.
{eoc}

Jesucristo ya subió
hacia el trono de su padre
y te llama que consagres
tu cuitado corazón.

{soc}
Allá en Belén, nació la luz,
trajo también la paz Jesús.
De Israel el guiador
llegó con el amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-299-jesucristo-descendio/)' where id = 'sa-himno-299-jesucristo-descendio';
update public.songs set title = 'Un Día Cristo Volverá', lyrics = 'Un día Cristo volverá.
Promesa fiel, faltar jamás,
como se fue, así vendrá
y su pueblo ha de ver al rey Jesús.

{soc}
Muy pronto, sí, Jesús vendrá
y alegre le verá su pueblo.
Velad, orad, el rey vendrá,
los suyos arrebatará.
{eoc}

Los mensajeros del Señor
afirman que vendrá Jesús;
el buen y fiel consolador
las promesas ya sacó a plena luz.

{soc}
Muy pronto, sí, Jesús vendrá
y alegre le verá su pueblo.
Velad, orad, el rey vendrá,
los suyos arrebatará.
{eoc}

Oh, gloria sin comparación
será mirar a nuestro rey,
reciban todos bendición
esperando ese día su grey.

{soc}
Muy pronto, sí, Jesús vendrá
y alegre le verá su pueblo.
Velad, orad, el rey vendrá,
los suyos arrebatará.
{eoc}

Oh, bien venido rey Jesús,
tu iglesia te espera aquí,
muy pronto ha de ver tu faz
y gozar de tus laureles siempre allí.

{soc}
Muy pronto, sí, Jesús vendrá
y alegre le verá su pueblo.
Velad, orad, el rey vendrá,
los suyos arrebatará.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-301-un-dia-cristo-volvera/)' where id = 'sa-himno-301-un-dia-cristo-volvera';
update public.songs set title = 'Ven Pecador', lyrics = 'Ven pecador que Dios te está llamado
y él te espera que vengas a su lado,
te librará el alma del sepulcro
siéndole fiel soldado.

{soc}
Dios te ilumina que dejes el pecado,
que te arrepientas y vuelvas a tu lado
y así saldrás de aquel oscuro abismo
y serás coronado.
{eoc}

Se ve vagar la misteriosa sombra
de Satanás, el cual destruye el alma,
pero aquel Dios a quien tú le desprecias
lleno de amor te aguarda.

{soc}
Dios te ilumina que dejes el pecado,
que te arrepientas y vuelvas a tu lado
y así saldrás de aquel oscuro abismo
y serás coronado.
{eoc}

Si somos fieles en sus santos caminos
recibiremos consagración del cielo,
y Dios guiará con su ángel nuestros pasos
donde quiera que andemos.

{soc}
Dios te ilumina que dejes el pecado,
que te arrepientas y vuelvas a tu lado
y así saldrás de aquel oscuro abismo
y serás coronado.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-302-ven-pecador/)' where id = 'sa-himno-302-ven-pecador';
update public.songs set title = 'Un Príncipe Tenemos', lyrics = 'Un príncipe tenemos,
en él todos confiamos,
su palabra es suave y fuerte
y su orden, no ceder.
Lucharemos por la gloria
todos juntos como hermanos
y triunfantes entraremos
en la gloria del Edén.

Aunque turbe nuestros pasos,
hierros, penas o cadenas,
seguiremos adelante
por la gracia del Señor.
En conquista de otras almas,
en conquista de otras tierras
para trono, honra y gloria
del precioso Salvador.

Trataremos de ser fieles
y luchar con gran anhelo
por el evangelio santo
que es dictado por amor
para remisión del mundo
y para gloria del cielo,
para consuelo del triste
y perdón del pecador.

Bienaventurado el triste
porque él tendrá consuelo
en la gloria de mi padre,
en la gloria de Jehová.
Esa ha sido la promesa
de Jesús nazareno,
y es por ello que luchamos
en la vida terrenal.

Jesucristo el Nazareno
el mesías prometido,
que naciste en un pesebre
en un establo de Belén.
Ten piedad, misericordia,
para tu hijo arrepentido,
para que así te alabemos
en el celestial Edén.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-305-un-principe-tenemos/)' where id = 'sa-himno-305-un-principe-tenemos';
update public.songs set title = 'Junto Al Templo De La Hermosa', lyrics = 'Junto al templo de la hermosa
un mendigo una limosna cada día imploraba,
y subía pedro y juan a orar
y en ellos le fijó una mirada.

{soc}
No tengo plata ni oro,
mas lo que tengo te doy
en el nombre de Jesús de Nazaret
levántate y anda y alaba a tu Dios.
{eoc}

Hoy el mundo está afligido
y ha caído en la desesperación,
y no encuentra una mano protectora
que le diga que en Jesús hay salvación.

{soc}
No tengo plata ni oro,
mas lo que tengo te doy
en el nombre de Jesús de Nazaret
levántate y anda y alaba a tu Dios.
{eoc}

Si Satán, nuestro enemigo,
a tu hermano hiciere caer
y quedarte tendido en el camino
dale auxilio con presteza y con placer.

{soc}
No tengo plata ni oro,
mas lo que tengo te doy
en el nombre de Jesús de Nazaret
levántate y anda y alaba a tu Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-306-junto-al-templo-de-la-hermosa/)' where id = 'sa-himno-306-junto-al-templo-de-la-hermosa';
update public.songs set title = 'Sembrad Con Amor', lyrics = 'Sembrad con amor
la palabra dulce del Señor.
Cantad con fe
porque pronto viene nuestro rey.
Saldrá el sol
y en sus alas traerá salud.
Pues, sedles fiel
y veremos pronto a Jesús.

Señor, venid
a morar en nuestros corazón.
Queremos ir
de la tierra a celestial Sión.
A nuestro Dios
elevemos pura oración.
Guardad a él
siempre limpio vuestro corazón.

Señor, aquí
nos juntamos en su santo amor,
a dar a ti alabanzas gratas a tu honor.
Deseamos hoy
que en un cercano día allí,
estar feliz
en un trono celestial de amor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-307-sembrad-con-amor/)' where id = 'sa-himno-307-sembrad-con-amor';
update public.songs set title = 'Tiernas Canciones', lyrics = 'Tiernas canciones alzad al Señor,
himnos que lleven del alma la fe
y hablen muy alto del férvido amor
que hay en el pecho del hombre que cree.
Vengan trayendo ferviente canción
niños y ancianos de Dios al altar,
traigan a Él su corazón,
único don que podrá aceptar.

{soc}
Cielo y tierra canten ala Señor de las naciones,
cielo y tierra canten al Señor de las naciones,
y los hombres todos, con alegres corazones,
sirvan al Señor que vida y paz siempre les da.
{eoc}

Cielo y tierra canten al Señor de las naciones,
cielo y tierra canten al Señor de las naciones,
y los hombres todos, con alegres corazones,
sirvan al Señor que vida y paz siempre les da.

Es la fuente de toda bondad,
es de la vida la luz y el calor,
sólo Él nos libra de cruel ansiedad,
sólo Él aleja del alma el dolor.
Digno es por tanto que el hombre de dé
gloria y honor que resuene doquier;
vamos a Él llenos de fe.
Nos salvará con su gran poder.

{soc}
Cielo y tierra canten ala Señor de las naciones,
cielo y tierra canten al Señor de las naciones,
y los hombres todos, con alegres corazones,
sirvan al Señor que vida y paz siempre les da.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-309-tiernas-canciones/)' where id = 'sa-himno-309-tiernas-canciones';
update public.songs set title = 'Sufrió Por Mí El Salvador', lyrics = 'Por mí sufrió el salvador
¡gloria, gloria! A mi Jesús;
load conmigo al redentor,
¡gloria, gloria! A mi Jesús.

{soc}
Jesús, Jesús el salvador
el dulce nombre del Señor;
él me rodea con santo amor,
¡gloria, gloria!, a mi Jesús.
{eoc}

Con mis maldades él cargó
¡gloria, gloria! A mi Jesús;
él, en la cruz me rescató.
¡gloria, gloria! A mi Jesús.

{soc}
Jesús, Jesús el salvador
el dulce nombre del Señor;
él me rodea con santo amor,
¡gloria, gloria!, a mi Jesús.
{eoc}

Yo sé que perdonado estoy,
¡gloria, gloria! A mi Jesús,
y con certeza al cielo voy,
¡gloria, gloria! A mi Jesús.

{soc}
Jesús, Jesús el salvador
el dulce nombre del Señor;
él me rodea con santo amor,
¡gloria, gloria!, a mi Jesús.
{eoc}

Y al concluir la lucha aquí,
¡gloria, gloria! A mi Jesús;
a mejor patria iré a cantar,
¡gloria, gloria! A mi Jesús.

{soc}
Jesús, Jesús el salvador
el dulce nombre del Señor;
él me rodea con santo amor,
¡gloria, gloria!, a mi Jesús.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-310-sufrio-por-mi-el-salvador/)' where id = 'sa-himno-310-sufrio-por-mi-el-salvador';
update public.songs set title = '¡Oh, Amor De Dios!', lyrics = '¡Oh, amor de Dios! Su inmensidad
el hombre no podría contar;
que Dios al hombre pudo amar
cuando el pecado entró al hogar
de Adán y Eva en Edén,
Dios les sacó, más prometió
un salvador también.

{soc}
¡Oh, amor de Dios! Brotando está
inmensurable, eternal,
por las edades durará
inagotable raudal.
{eoc}

Si fuera tinta todo el mar
y todo el cielo un gran papel
y todo hombre un escritor,
y cada hoja un pincel
para escribir de su existir,
no bastarían jamás.
Él me salvó y me lavó,
y me da el cielo, además.

{soc}
¡Oh, amor de Dios! Brotando está
inmensurable, eternal,
por las edades durará
inagotable raudal.
{eoc}

Y cuando el mundo pasará,
con cada trama y plan carnal
y todo reino caerá,
con cada trono mundanal,
el gran amor del redentor
por siempre perdurará.
La gran canción de salvación
su pueblo entonará.

{soc}
¡Oh, amor de Dios! Brotando está
inmensurable, eternal,
por las edades durará
inagotable raudal.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-311-oh-amor-de-dios/)' where id = 'sa-himno-311-oh-amor-de-dios';
update public.songs set title = 'Gratitud A Nuestro Dios', lyrics = 'Lleno de gozo y gratitud
henchido está mi corazón,
porque he hallado sólo en Jesús
para mi alma la salvación.

{soc}
Gratitud, gratitud
gratitud, a nuestro Dios
por la salud, por la salud
que a mi alma Jesús le dio.
Noble, puro y tan santo
es el amor del salvador
y tan bendito es ese manto
extendido al pecador.
{eoc}

Gratitud, gratitud
gratitud, a nuestro Dios
por la salud, por la salud
que a mi alma Jesús le dio.

Por gratitud yo te alabo
porque tu amor me ha constreñido
honra tan grande tú me has dado
siendo yo un vil perdido.

{soc}
Gratitud, gratitud
gratitud, a nuestro Dios
por la salud, por la salud
que a mi alma Jesús le dio.
Noble, puro y tan santo
es el amor del salvador
y tan bendito es ese manto
extendido al pecador.
{eoc}

Gratitud, gratitud
gratitud, a nuestro Dios
por la salud, por la salud
que a mi alma Jesús le dio.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-312-gratitud-a-nuestro-dios/)' where id = 'sa-himno-312-gratitud-a-nuestro-dios';
update public.songs set title = 'Marcho Siempre Al Frente', lyrics = 'Marcho siempre al frente con mi salvador,
dando a los del mundo ejemplo y valor;
pues somos cristianos por la redención
de esos que en el mundo van tras el dolor.

{soc}
Soldado valiente de Cristo yo soy;
pues llevo en el alma celestial valor
y cantando llegaré a la gloria.
Alabando al cordero de Dios.
Porque Cristo me dio, porque Cristo me dio
con su muerte el más puro vivir.
{eoc}

Hoy que ya es tiempo que el Señor vendrá
llevemos al hombre un poco de paz.
Si el mundo en sus cuitas no lo quiere oír,
clamemos a Cristo por el porvenir.

{soc}
Soldado valiente de Cristo yo soy;
pues llevo en el alma celestial valor
y cantando llegaré a la gloria.
Alabando al cordero de Dios.
Porque Cristo me dio, porque Cristo me dio
con su muerte el más puro vivir.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-313-marcho-siempre-al-frente/)' where id = 'sa-himno-313-marcho-siempre-al-frente';
update public.songs set title = 'Cristo Nuestro Jefe', lyrics = 'Cristo, nuestro jefe, nos lleva a la lid;
nunca cederemos si él nos dice: id.
En su justa causa se suele ignorar;
mas, le seguiremos fiel.

{soc}
¡adelante, es la orden del Señor!
¡adelante, vamos sin temor!
¡adelante, canta ya su grey!
¡la victoria es cierta con el rey!
{eoc}

La furiosa lucha, larga no será
y a los vencedores nos congregarán;
donde cantaremos un himno triunfal,
sí, le seguiremos fiel.

{soc}
¡adelante, es la orden del Señor!
¡adelante, vamos sin temor!
¡adelante, canta ya su grey!
¡la victoria es cierta con el rey!
{eoc}

Nuestro estandarte luce por doquier
con poder y gloria, siempre se ha de ver;
Cristo, nuestro jefe, al mundo venció,
sí, le seguiremos fiel.

{soc}
¡adelante, es la orden del Señor!
¡adelante, vamos sin temor!
¡adelante, canta ya su grey!
¡la victoria es cierta con el rey!
{eoc}

Chile para Cristo, Cristo para él,
nuestras peticiones, siempre han de ser
y la gran victoria, nuestra Dios dará.
Sí, le seguiremos fiel.

{soc}
¡adelante, es la orden del Señor!
¡adelante, vamos sin temor!
¡adelante, canta ya su grey!
¡la victoria es cierta con el rey!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-315-cristo-nuestro-jefe/)' where id = 'sa-himno-315-cristo-nuestro-jefe';
update public.songs set title = 'Allá En Las Playas De Galilea', lyrics = 'Allá en las playas de Galilea
humildes hombres llamó el Señor.
Fuego inflamado por la Judea,
la dulce llama de gran amor.

{soc}
Dulce evangelio inmaculado
del cual emana felicidad;
que de los cielos ha sido enviado
a dar al mundo la claridad.
{eoc}

Al dar Jesús su gran doctrina,
con rapidez se dio a entender
y conmovíose la palestina,
al ver un nuevo amanecer.

{soc}
Dulce evangelio inmaculado
del cual emana felicidad;
que de los cielos ha sido enviado
a dar al mundo la claridad.
{eoc}

De vida eterna echó simiente
junto al lago de Genesaret,
bellas palabras de amor ardiente
por el profeta de Nazaret.

{soc}
Dulce evangelio inmaculado
del cual emana felicidad;
que de los cielos ha sido enviado
a dar al mundo la claridad.
{eoc}

Quiero que me hagas noble y sincero,
para en tu viña fiel trabajar;
ser decidido, fiel mensajero
y tu bandera, en la cumbre alzar.

{soc}
Dulce evangelio inmaculado
del cual emana felicidad;
que de los cielos ha sido enviado
a dar al mundo la claridad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-316-alla-en-las-playas-de-galilea/)' where id = 'sa-himno-316-alla-en-las-playas-de-galilea';
update public.songs set title = 'Es Jesucristo Mi Todo', lyrics = 'Es Jesucristo mi todo,
grato es cantar su loor,
¡oh! Cuán sublime e infinito
es su divino amor.
Cuando me vio errabundo
cual hijo pródigo,
vino a buscarme y salvarme;
a su redil me llevó.

{soc}
¡Cristo, Cristo!
Tú eres mi salvador
¡Cristo, Cristo!
Tuyo seré Señor
te seguiré donde quieras
si tú guiándome vas
y al terminar mi carrera,
en gloria, veré tu faz.
{eoc}

Cristo es el lirio del valle,
la rosa es de sarón,
Cristo es el astro esplendente
la roca de salvación.
El es la fuente de la vida
y gozo eternal;
ya satisface mi alma
con el maná celestial.

{soc}
¡Cristo, Cristo!
Tú eres mi salvador
¡Cristo, Cristo!
Tuyo seré Señor
te seguiré donde quieras
si tú guiándome vas
y al terminar mi carrera,
en gloria, veré tu faz.
{eoc}

Cristo nació en un pesebre;
la amarga copa bebió;
cual inocente cordero
en el Calvario murió.
Resucitó de la tumba
y al cielo ascendió,
mas, pronto viene en gloria,
esta promesa nos dio.

{soc}
¡Cristo, Cristo!
Tú eres mi salvador
¡Cristo, Cristo!
Tuyo seré Señor
te seguiré donde quieras
si tú guiándome vas
y al terminar mi carrera,
en gloria, veré tu faz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-318-es-jesucristo-mi-todo/)' where id = 'sa-himno-318-es-jesucristo-mi-todo';
update public.songs set title = 'Viene Otra Vez El Salvador', lyrics = 'Viene otra vez nuestro Salvador
¡oh, que si fuera hoy!
Para reinar con su poder y amor,
¡oh, que si fuera hoy!
Ya por su esposa viene otra vez,
purificada en su amor
del mundo por la redondez,
¡oh, que si fuera hoy!

{soc}
¡gloria, gloria! Gozo sin fin traerá,
¡gloria, gloria! Al coronarle rey;
¡gloria, gloria! La senda preparad,
¡gloria, gloria! Fuerte viene otra vez.
Terminará el poder de Satán,
¡oh, que si fuera hoy!
No más tristezas aquí habrá,
¡oh, que si fuera hoy!
Multiplicadas señales hay;
en el oriente se ve el alba,
ya muy cercano el tiempo está,
¡oh, que si fuera hoy!
{eoc}

{soc}
¡gloria, gloria! Gozo sin fin traerá,
¡gloria, gloria! Al coronarle rey;
¡gloria, gloria! La senda preparad,
¡gloria, gloria! Fuerte viene otra vez.
{eoc}

Fieles y leales nos debe hallar
¡como si fuera hoy!
Siempre velando con gozo y paz
¡como si fuera hoy!
Todos los muertos en Cristo irán
arrebatados por su Señor,
¿cuándo estas cosas aquí se harán?
¡ojalá fuera hoy!

{soc}
¡gloria, gloria! Gozo sin fin traerá,
¡gloria, gloria! Al coronarle rey;
¡gloria, gloria! La senda preparad,
¡gloria, gloria! Fuerte viene otra vez.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-319-viene-otra-vez-el-salvador/)' where id = 'sa-himno-319-viene-otra-vez-el-salvador';
update public.songs set title = 'Yo Oigo Decir', lyrics = 'Yo oigo decir que más allá
Hay un buen hogar,
hay un buen hogar;
en donde el alma
Para siempre pueda morar,
en donde la muerte
Nunca entra, nunca jamás,
sino que allá con el Señor
Es todo solaz,
es todo solaz.

{soc}
Allá quiero estar, allá quiero estar,
ver a Jesús el salvador y con él morar,
con él morar.
Allá quiero estar, allá quiero estar
allí alabanzas a Jesús podré entonar.
{eoc}

No puedo dejar de anunciar
Que salva Jesús
que salva Jesús;
que trae al perdido en la noche,
A su gran luz,
a su gran luz.
Que calma dará al peregrino
En la tempestad,
en la tempestad.
Y canto, por duelo, le dará
Por su gran bondad,
por su gran bondad.

{soc}
Allá quiero estar, allá quiero estar,
ver a Jesús el salvador y con él morar,
con él morar.
Allá quiero estar, allá quiero estar
allí alabanzas a Jesús podré entonar.
{eoc}

Yo voy tan feliz en medio
De las pruebas de aquí,
las pruebas de aquí;
porque yo bien sé, que voy
A ver a Cristo allí,
a Cristo allí.
En donde por siglos y por siglos
Un mundo sin fin,
un mundo sin fin;
loores daré allí a Dios
Con arpa y clarín,
con arpa y clarín.

{soc}
Allá quiero estar, allá quiero estar,
ver a Jesús el salvador y con él morar,
con él morar.
Allá quiero estar, allá quiero estar
allí alabanzas a Jesús podré entonar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-320-yo-oigo-decir/)' where id = 'sa-himno-320-yo-oigo-decir';
update public.songs set title = 'Fieles Soldados', lyrics = 'Fieles soldados de Cristo Jesús
sin vacilar, a la lucha salid
obedeciendo al gran capitán,
el avivamiento, tendrá que venir.

{soc}
Ha de venir, sí, ha de venir,
el avivamiento tendrá que venir.
Obedezcamos, tengamos fe,
que el avivamiento tendrá que venir.
{eoc}

Con bendiciones Jesús nos colmó;
nos revistió con divino poder,
el hasta aquí la victoria nos dio
y al enemigo podremos vencer.

{soc}
Ha de venir, sí, ha de venir,
el avivamiento tendrá que venir.
Obedezcamos, tengamos fe,
que el avivamiento tendrá que venir.
{eoc}

Tú nos amaste, ¡oh buen Salvador!
Y por salvarnos viniste a sufrir.
Danos tu Espíritu Santo, Señor,
y así podremos amarnos y servir.

{soc}
Ha de venir, sí, ha de venir,
el avivamiento tendrá que venir.
Obedezcamos, tengamos fe,
que el avivamiento tendrá que venir.
{eoc}

Nada del mundo queremos amar,
sólo por ti anhelamos vivir
y así seguiremos orando con fe,
el avivamiento, tendrá que venir.

{soc}
Ha de venir, sí, ha de venir,
el avivamiento tendrá que venir.
Obedezcamos, tengamos fe,
que el avivamiento tendrá que venir.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-321-fieles-soldados/)' where id = 'sa-himno-321-fieles-soldados';
update public.songs set title = 'Ven Amigo Ven', lyrics = 'Ven, amigo, ven,
Jesucristo te llama con amor,
ven, amigo, ven,
no deseches tan dulce invitación.
Ven, amigo, ven,
no tardes por más tiempo en venir,
que mañana puede ser
demasiado tarde para ti.

{soc}
Obedece, amigo, al llamado del Señor,
no digas, no digas: mañana iré;
ven ahora mismo, te llama el salvador,
decídete y dice: del Señor seré;
y en brazos gozarás de su amor.
{eoc}

Ven, amigo, ven,
no endurezcas por más tiempo el corazón.
Ven, amigo, ven,
no deseches el llamado del Señor.
Ven, amigo, ven,
las puertas están abiertas para ti
y en los brazos de Jesús,
para siempre, tú serás feliz.

{soc}
Obedece, amigo, al llamado del Señor,
no digas, no digas: mañana iré;
ven ahora mismo, te llama el salvador,
decídete y dice: del Señor seré;
y en brazos gozarás de su amor.
{eoc}

Ven, amigo, ven,
Jesucristo te ofrece un galardón,
ven, amigo, ven,
no deseches el cariño del Señor.
Ven, amigo, ven,
en el cielo hay moradas para ti
y si vienes, gozarás
de una dicha que no tiene fin.

{soc}
Obedece, amigo, al llamado del Señor,
no digas, no digas: mañana iré;
ven ahora mismo, te llama el salvador,
decídete y dice: del Señor seré;
y en brazos gozarás de su amor.
{eoc}

Ven, amigo, ven,
el Señor te quiere perdonar.
Ven, amigo, ven,
y su sangre a tu alma puede entrar.
Ven, amigo, ven,
y por fe probarás el gran poder
que Jesús da al pecador,
si te arrepientes de todo corazón.

{soc}
Obedece, amigo, al llamado del Señor,
no digas, no digas: mañana iré;
ven ahora mismo, te llama el salvador,
decídete y dice: del Señor seré;
y en brazos gozarás de su amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-323-ven-amigo-ven/)' where id = 'sa-himno-323-ven-amigo-ven';
update public.songs set title = 'Eres Mansión de Confraternidad', lyrics = 'Eres mansión de confraternidad,
tu magno triunfo pronto se ha de ver.
Somos soldados de la libertad,
con Jesucristo sabemos vencer.

{soc}
¡Gloria a Jesús, gloria a Jesús!
¡Oh! Pecador, vuelve al Dios de amor;
¡Gloria a Jesús, gloria a Jesús!
Por su sangre limpio soy, ¡gloria a Jesús!
{eoc}

Luchas y pruebas nos han de costar
las nuevas almas que a Cristo se den.
La nueva aurora pronto ha de brillar
del mundo nuevo, copia del Edén.

{soc}
¡Gloria a Jesús, gloria a Jesús!
¡Oh! Pecador, vuelve al Dios de amor;
¡Gloria a Jesús, gloria a Jesús!
Por su sangre limpio soy, ¡gloria a Jesús!
{eoc}

El evangelio pronto brillará;
como lucero dará resplandor
la iglesia, libre por doquiera irá
diciendo al mundo que Dios es amor.

{soc}
¡Gloria a Jesús, gloria a Jesús!
¡Oh! Pecador, vuelve al Dios de amor;
¡Gloria a Jesús, gloria a Jesús!
Por su sangre limpio soy, ¡gloria a Jesús!
{eoc}

Chile será para Cristo Jesús
por el trabajo de nuestra misión,
cada soldado llevará la luz
del evangelio, para salvación.

{soc}
¡Gloria a Jesús, gloria a Jesús!
¡Oh! Pecador, vuelve al Dios de amor;
¡Gloria a Jesús, gloria a Jesús!
Por su sangre limpio soy, ¡gloria a Jesús!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-324-eres-mansion-de-confraternidad/)' where id = 'sa-himno-324-eres-mansion-de-confraternidad';
update public.songs set title = 'Quiero Ver a Jesucristo', lyrics = 'Quiero ver a Jesucristo,
mi precioso salvador:
ver la faz de mi maestro
quien por mí su vida dio,
quiero ver el alto cielo,
ver el trono de mi Dios;
viviré en esa patria,
de eterno gozo y paz.

{soc}
Quiero ver aquella tierra
donde sombras ya no habrá;
quiero estar en las moradas
de Jesús, mi salvador.
{eoc}

Por obra redentora
de Jesús, mi salvador,
viviré por las edades
en la casa celestial.
Por la sangre del cordero,
aunque indigno yo lo soy,
con los muchos redimidos
gloria entonaré a Dios.

{soc}
Quiero ver aquella tierra
donde sombras ya no habrá;
quiero estar en las moradas
de Jesús, mi salvador.
{eoc}

Por amor a Jesucristo
y su obra eternal,
quiero dejar el mundo
y consagrarme a orar.
Quiero ser un mensajero
conduciendo al pecador,
a la cruz de Jesucristo
y la patria celestial.

{soc}
Quiero ver aquella tierra
donde sombras ya no habrá;
quiero estar en las moradas
de Jesús, mi salvador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-325-quiero-ver-a-jesucristo/)' where id = 'sa-himno-325-quiero-ver-a-jesucristo';
update public.songs set title = 'Varios Años He Luchado', lyrics = 'Varios años he luchado por ser bueno
y no puedo, ni he podido ser mejor;
mas, no puedo hacer bien lo que yo quiero,
porque es malo y perverso el corazón.

{soc}
“ven a mí, ven a mí,
quiero hacerte descansar;
dice Cristo, invitando al pecador;
“si tu carga es tan pesada y no puedes,
hijo mío, dame hoy tu corazón”.
{eoc}

En el mundo he querido sin reproche,
presentarme con un limpio corazón;
mas, engaños y fracasos he tenido
y no puedo, sin la ayuda del Señor.

{soc}
“ven a mí, ven a mí,
quiero hacerte descansar;
dice Cristo, invitando al pecador;
“si tu carga es tan pesada y no puedes,
hijo mío, dame hoy tu corazón”.
{eoc}

Sólo Cristo y su sangre derramada,
por tan vil y malvado pecador,
da perdón, da la vida, paz y gozo
y prepara para Dios el corazón.

{soc}
“ven a mí, ven a mí,
quiero hacerte descansar;
dice Cristo, invitando al pecador;
“si tu carga es tan pesada y no puedes,
hijo mío, dame hoy tu corazón”.
{eoc}

Yo no quiero, yo no quiero por más tiempo
estar lejos, estar lejos del Señor;
nos invita hoy, que todos le busquemos
en espíritu y perfecta, comunión.

{soc}
“ven a mí, ven a mí,
quiero hacerte descansar;
dice Cristo, invitando al pecador;
“si tu carga es tan pesada y no puedes,
hijo mío, dame hoy tu corazón”.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-326-varios-anos-he-luchado/)' where id = 'sa-himno-326-varios-anos-he-luchado';
update public.songs set title = 'Alma Escucha a Tu Señor', lyrics = 'Alma escucha a tu Señor
a Jesús, mi Salvador;
él te dice con amor;
¿Me amas tú, oh pecador?

{soc}
¡Oh! Qué bello y dulce es
el amor de mi Jesús;
el amor que de mí tuvo,
gratamente alabaré.
{eoc}

Vine al mundo
por tu amor,
preso estabas, te libré;
moribundo, te salvé,
¿Me amas tú, oh pecador?

{soc}
¡Oh! Qué bello y dulce es
el amor de mi Jesús;
el amor que de mí tuvo,
gratamente alabaré.
{eoc}

Vives tú por mi dolor;
de mi gracia gozarás,
vida eterna, si tendrás,
¿Me amas tú, oh pecador?

{soc}
¡Oh! Qué bello y dulce es
el amor de mi Jesús;
el amor que de mí tuvo,
gratamente alabaré.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-329-alma-escucha-a-tu-senor/)' where id = 'sa-himno-329-alma-escucha-a-tu-senor';
update public.songs set title = 'Estrella De La Mañana', lyrics = 'Dios mío, consuela mi tímida alma
que triste camina de culpas cargada;
en busca de Jesucristo,
estrella de la mañana.

{soc}
De ti separada, vagando alejada
por valle de muerte, pecado y desgracia;
sin pensar en Jesucristo,
estrella de la mañana.
{eoc}

Cosecha de males en horas amargas,
un llanto de fuego me cegó por su parte;
ausente de Jesucristo,
estrella de la mañana.

{soc}
De ti separada, vagando alejada
por valle de muerte, pecado y desgracia;
sin pensar en Jesucristo,
estrella de la mañana.
{eoc}

Mas pronto, Dios mío, tu santa palabra,
mostróse dulce, suave, eficaz;
en el nombre de Jesucristo,
estrella de la mañana.

{soc}
De ti separada, vagando alejada
por valle de muerte, pecado y desgracia;
sin pensar en Jesucristo,
estrella de la mañana.
{eoc}

Entonces, Dios mío, cobrando esperanza,
humilde se puso, postrada, a tus pies;
en el nombre de Jesucristo,
estrella de la mañana.

{soc}
De ti separada, vagando alejada
por valle de muerte, pecado y desgracia;
sin pensar en Jesucristo,
estrella de la mañana.
{eoc}

¡Oh, buen Jesús! Escucha los halles del alma
que pobre y herida implora tu gracia;
por amor a Jesucristo,
estrella de mañana.

{soc}
De ti separada, vagando alejada
por valle de muerte, pecado y desgracia;
sin pensar en Jesucristo,
estrella de la mañana.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-332-estrella-de-la-manana/)' where id = 'sa-himno-332-estrella-de-la-manana';
update public.songs set title = 'Salimos De La Vida', lyrics = 'Salimos de la vida al ancho mar
y otras barcas vemos ir;
nuestro capitán, Jesús, podrá guiar
nuestra barquilla hasta el fin;
mas, mientras vamos en seguridad
guiados por el buen Jesús,
muchas voces angustiadas
escuchamos de los que bogan sin luz.

{soc}
¡Escuchad!, ved ahí
la barca que va a naufragar;
¡escuchad, id allí!
El pronto socorro a prestar.
{eoc}

Alzad la luz que vaya a señalar,
el rumbo que podrá seguir
al que lucha con el turbulento mar
y del buen sendero se alejó.
Que encuentre en la ruda tempestad
seguro asilo con Jesús;
que tenga al surcar la inmensidad,
los esplendores de su luz.

{soc}
¡Escuchad!, ved ahí
la barca que va a naufragar;
¡escuchad, id allí!
El pronto socorro a prestar.
{eoc}

Salimos de la vida al ancho mar
y solos no podremos ir;
otros hay también que salen a luchar
y ayuda esperan recibir.
La estrella del amor arriba está;
el ancla bien segura es Dios,
adelante, que Jesús espera ya
en la ribera celestial.

{soc}
¡Escuchad!, ved ahí
la barca que va a naufragar;
¡escuchad, id allí!
El pronto socorro a prestar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-334-salimos-de-la-vida/)' where id = 'sa-himno-334-salimos-de-la-vida';
update public.songs set title = 'En La Vergonzosa Cruz', lyrics = 'En la vergonzosa cruz,
padeció por mí, Jesús;
por la sangre que vertió,
mis pecados él expió;
lavará de todo mal
ese rojo manantial;
el que abrió por mí, Jesús,
en la vergonzosa cruz.

{soc}
Si, fue por mí. Sí, fue por mí,
fue por mí; murió Jesús
en la vergonzosa cruz.
{eoc}

¡Oh! ¡Qué amor, qué inmenso amor!
Reveló mi salvador;
la maldad que hice yo,
al suplicio le llevó.
Ahora a ti, mi todo doy,
cuerpo y alma tuyo soy;
mientras permanezca aquí,
hazme siempre fiel a ti.

{soc}
Si, fue por mí. Sí, fue por mí,
fue por mí; murió Jesús
en la vergonzosa cruz.
{eoc}

Yo de Cristo sólo soy;
a seguirle pronto estoy,
al bendito redentor
serviré con firme amor.
Sea mi alma ya su hogar,
y mi corazón su altar;
vida emana, paz y luz
del Calvario, de la cruz.

{soc}
Si, fue por mí. Sí, fue por mí,
fue por mí; murió Jesús
en la vergonzosa cruz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-335-en-la-vergonzosa-cruz/)' where id = 'sa-himno-335-en-la-vergonzosa-cruz';
update public.songs set title = 'Peregrino', lyrics = 'Peregrino, tú que vas al cielo
y te sientes afligido aquí,
será satisfecho tu anhelo:
cantarás con ángeles allí.

{soc}
Y estarás allá
cuando las canciones en la gloria
como ruido de agua fuerte, sonarán;
y estarás allá
cuando los redimidos entrarán
en el cielo y cantarán a Dios.
{eoc}

Oigan cómo tocan las campanas,
son señales que aquí se verán;
oigan cómo el Señor les llama,
pronto los salvados entrarán.

{soc}
Y estarás allá
cuando las canciones en la gloria
como ruido de agua fuerte, sonarán;
y estarás allá
cuando los redimidos entrarán
en el cielo y cantarán a Dios.
{eoc}

Clamen a los siervos que prediquen
el mensaje de la salvación,
y que todos los siervos se dediquen
a la obra de la redención.

{soc}
Y estarás allá
cuando las canciones en la gloria
como ruido de agua fuerte, sonarán;
y estarás allá
cuando los redimidos entrarán
en el cielo y cantarán a Dios.
{eoc}

Cristo con su sangre ha entrado
en los cielos para preparar
un lugar eterno a los salvados
que su alma quieren aquí lavar.

{soc}
Y estarás allá
cuando las canciones en la gloria
como ruido de agua fuerte, sonarán;
y estarás allá
cuando los redimidos entrarán
en el cielo y cantarán a Dios.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-337-peregrino/)' where id = 'sa-himno-337-peregrino';
update public.songs set title = 'Oh Señor Procuro En Vano', lyrics = '¡Oh, Señor! Procuro en vano,
mi conducta reformar;
pues ningún poder humano
santidad me puede dar.
Es mi vida de pecado
diaria ofensa para ti;
pero mi alma ha confiado
en tu sangre carmesí.

En tu reino está el contento,
nada impuro allí entrará;
sin el nuevo nacimiento
ningún alma lo verá.
Mira, pues, mi insuficiencia,
muestra en mí tu gran poder;
manifiesta tu clemencia
y de nuevo hazme nacer.

Ven, Espíritu divino;
ven y escucha mi oración;
ante ti mi frente inclino,
por mi regeneración.
De este modo mi esperanza
no vacila y llego a creer
que la bienaventuranza
en el cielo he de tener.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-338-oh-senor-procuro-en-vano/)' where id = 'sa-himno-338-oh-senor-procuro-en-vano';
update public.songs set title = 'En Tus Afanes Y En Tu Dolor', lyrics = 'En tus afanes y en tu dolor,
Dios cuidará de ti.
Vive amparado en su inmenso amor:
Dios cuidará de ti.

{soc}
Dios cuidará de ti
y por doquier contigo irá;
Dios cuidará de ti
nada te faltará.
{eoc}

Si desfalleces en tu amor;
Dios cuidará de ti.
Si ves peligros en rededor,
Dios cuidará de ti.

{soc}
Dios cuidará de ti
y por doquier contigo irá;
Dios cuidará de ti
nada te faltará.
{eoc}

Cuanto anhelares, él te dará;
Dios cuidará de ti.
Nada que pidas te negará,
Dios cuidará de ti.

{soc}
Dios cuidará de ti
y por doquier contigo irá;
Dios cuidará de ti
nada te faltará.
{eoc}

Nunca en las pruebas sucumbirás;
Dios cuidará de ti.
En su regazo te apoyarás:
Dios cuidará de ti.

{soc}
Dios cuidará de ti
y por doquier contigo irá;
Dios cuidará de ti
nada te faltará.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-341-en-tus-afanes-y-en-tu-dolor/)' where id = 'sa-himno-341-en-tus-afanes-y-en-tu-dolor';
update public.songs set title = 'Más Cual Mi Cristo', lyrics = 'Mas cual mi Cristo, quiero siempre ser;
más mansedumbre, más benignidad,
celo en servirle, fidelidad mostrar;
más consagrado a la obra que él me da.

{soc}
Toma mi ser, tan sólo tuyo es;
todo, toma mi ser, lo doy, Señor, a ti,
mi corazón imploro limpies, sí.
Heme aquí, soy tuyo por la eternidad.
{eoc}

Mas cual mi Cristo, es mi oración;
más fuerza tenga, más resignación,
más serio siempre; más espiritual
y los perdidos traerte al altar.

{soc}
Toma mi ser, tan sólo tuyo es;
todo, toma mi ser, lo doy, Señor, a ti,
mi corazón imploro limpies, sí.
Heme aquí, soy tuyo por la eternidad.
{eoc}

Mas cual mi Cristo, es mi devoción;
de su cariño, grande compasión.
Cual el paciente, humilde y veraz
es mi anhelo, cual Cristo aquí andar.

{soc}
Toma mi ser, tan sólo tuyo es;
todo, toma mi ser, lo doy, Señor, a ti,
mi corazón imploro limpies, sí.
Heme aquí, soy tuyo por la eternidad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-342-mas-cual-mi-cristo/)' where id = 'sa-himno-342-mas-cual-mi-cristo';
update public.songs set title = 'Oid La Voz', lyrics = 'Oíd la voz del Dios de amor:
nace en la tierra el salvador,
hombre, alabadle,
loor cantadle,
¡Gloria Sea a Dios!
“salve” el gran huésped celestial
que viene y salva al mortal;
¡Gloria a su Nombre,
entone el hombre!
¡Gloria al Rey!

{soc}
Ven mortal, cantad al Señor Dios,
ven al hijo, load con vuestra voz;
gozo trajo al mundo, paz y amor,
alabadle, ¡Gloria! Dadle
¡Gloria al Rey!
{eoc}

Ángeles cantan, nació el rey;
fue sin pecado ante la ley;
en la esperanza dadle alabanzas,
¡Gloria Sea a Dios!
Del cielo baña clara luz,
al que después murió en la cruz;
¡Gloria a su Nombre,
entone el hombre!
¡Gloria al Rey!

{soc}
Ven mortal, cantad al Señor Dios,
ven al hijo, load con vuestra voz;
gozo trajo al mundo, paz y amor,
alabadle, ¡Gloria! Dadle
¡Gloria al Rey!
{eoc}

Oíd en la tierra la canción,
van a sus pies pueblo y nación;
grato alabadle, loor cantadle
¡Gloria Sea a Dios!
Id al portal, dad loor
al hijo del Dios de amor;
¡Gloria a su Nombre,
entone el hombre!
¡Gloria al Rey!

{soc}
Ven mortal, cantad al Señor Dios,
ven al hijo, load con vuestra voz;
gozo trajo al mundo, paz y amor,
alabadle, ¡Gloria! Dadle
¡Gloria al Rey!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-343-oid-la-voz/)' where id = 'sa-himno-343-oid-la-voz';
update public.songs set title = 'Es Tiempo De La Siega', lyrics = 'Es el tiempo de la siega y ¿tú sin vacilar
declarando con holgura: no hay que trabajar?
Mientras tanto que el maestro te vuelve a llamar:
joven, joven, ven, trabaja ya.

{soc}
Ven y ve los campos blancos como están,
aguardando manos que los segarán;
joven despierta, hazlo pronto, y alerta;
sé el primero en decirle: ¡heme aquí, Señor!
Por doquier se inclina la madura mies,
que las auras mueven y qué bella es.
Joven, despierta, hazlo pronto y alerta;
pocos días hay que restan para el segador.
{eoc}

Las gavillas que recogen joyas de esplendor,
brillarán en la corona que dará el Señor;
busca pronto eterna joya, Dios es premiador.
¡joven, joven, ven, trabaja ya!

{soc}
Ven y ve los campos blancos como están,
aguardando manos que los segarán;
joven despierta, hazlo pronto, y alerta;
sé el primero en decirle: ¡heme aquí, Señor!
Por doquier se inclina la madura mies,
que las auras mueven y qué bella es.
Joven, despierta, hazlo pronto y alerta;
pocos días hay que restan para el segador.
{eoc}

Va pasando la mañana y nunca volverá;
pues el tiempo de la siega, aquí terminará;
te hallarás al fin vació ante el creador.
¡joven, joven, ven, trabaja ya!

{soc}
Ven y ve los campos blancos como están,
aguardando manos que los segarán;
joven despierta, hazlo pronto, y alerta;
sé el primero en decirle: ¡heme aquí, Señor!
Por doquier se inclina la madura mies,
que las auras mueven y qué bella es.
Joven, despierta, hazlo pronto y alerta;
pocos días hay que restan para el segador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-345-es-tiempo-de-la-siega/)' where id = 'sa-himno-345-es-tiempo-de-la-siega';
update public.songs set title = 'El Oro y La Plata', lyrics = 'El oro y la plata no me han redimido,
mi ser del pecado no pueden librar;
la sangre de Cristo es mi sola esperanza,
su muerte tan sólo me puede salvar.

{soc}
Me redimió; mas no con plata
me compró el Salvador;
con oro no; mas con su sangre;
grande precio de su amor.
{eoc}

El oro y la plata no me han redimido,
la pena terrible no pueden quitar;
la sangre de Cristo es mi sola esperanza,
mi culpa, su muerte la alcanza a borrar.

{soc}
Me redimió; mas no con plata
me compró el Salvador;
con oro no; mas con su sangre;
grande precio de su amor.
{eoc}

El oro y la plata no me han redimido,
la paz no darán ellos al pecador;
la sangre de Cristo es mi sola esperanza,
tan sólo su muerte me quita el temor.

{soc}
Me redimió; mas no con plata
me compró el Salvador;
con oro no; mas con su sangre;
grande precio de su amor.
{eoc}

El oro y la plata no me han redimido,
la entrada a los cielos no pueden comprar
la sangre de Cristo es mi sola esperanza,
su muerte, el rescate consiguió ganar.

{soc}
Me redimió; mas no con plata
me compró el Salvador;
con oro no; mas con su sangre;
grande precio de su amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-346-el-oro-y-la-plata/)' where id = 'sa-himno-346-el-oro-y-la-plata';
update public.songs set title = 'Va Mi Barca', lyrics = 'Va mi barca veloz por el viento,
enfrentando negra tempestad;
mas vislumbra la gloria del puerto
y alivia la furia del mar.

{soc}
No zozobrará…
No zozobrará…
aunque porfié la dificultad;
Cristo al timón va.
{eoc}

Entre pruebas que siegan tu vida
y agobian cual barco en el mar;
va tu fe con el rumbo perdido;
clama a Cristo y él te salvará.

{soc}
No zozobrará…
No zozobrará…
aunque porfié la dificultad;
Cristo al timón va.
{eoc}

No zozobra mi barca ahora,
porque Cristo es mi capitán;
y la Biblia por carta me guía
en mi rumbo hasta el puerto final.

{soc}
No zozobrará…
No zozobrará…
aunque porfié la dificultad;
Cristo al timón va.
{eoc}

Si alguien quiere navegar seguro
y las rocas y bajos salvar,
tripulemos el barco bendito,
que se llama evangelio de paz.

{soc}
No zozobrará…
No zozobrará…
aunque porfié la dificultad;
Cristo al timón va.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-348-va-mi-barca/)' where id = 'sa-himno-348-va-mi-barca';
update public.songs set title = 'La Llamada', lyrics = 'Un amigo muy dulce y amante
hoy te llama con ansias y amor;
ven a mí, te daré vida eterna
en mansiones de eterno esplendor.

{soc}
No rechaces la voz tan amante
de Jesús tu benigno Señor,
a la paz y pureza él te llama;
al Edén del celeste fulgor.
{eoc}

Cuántos hay cuya carga es pesada,
sólo es llanto, dolor y pesar;
hoy escucha tan dulce llamada
ven a mí, yo te haré descansar.

{soc}
No rechaces la voz tan amante
de Jesús tu benigno Señor,
a la paz y pureza él te llama;
al Edén del celeste fulgor.
{eoc}

Aunque vivas aquí sin amarle,
ante el gran tribunal ¿qué será?
Sólo él puede darte esperanza,
él que cree salvado será.

{soc}
No rechaces la voz tan amante
de Jesús tu benigno Señor,
a la paz y pureza él te llama;
al Edén del celeste fulgor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-349-la-llamada/)' where id = 'sa-himno-349-la-llamada';
update public.songs set title = 'El Cordero Inmolado', lyrics = 'Hoy día que soy cristiano
se goza mi corazón;
por la obra tan gloriosa
que hizo mi salvador.
Ese cuerpo tan perfecto
a la cruz tuvo que ir;
mi pecado fue la causa
que tuviese que morir.

Hoy me siento tan contento,
se lo debo al salvador;
esa alegría tan inmensa,
que me inunda el corazón.
Porque hoy día soy salvado
por la muerte de Jesús;
redimido con la sangre
derramada en la cruz.

Muchos fueron los azotes
que el verdugo descargó
sobre el cuerpo que llevaba
el madero de la cruz.
Ese precio tan inmenso
que pagó mi Salvador,
fue un rescate tan bendito,
que libertó al pecador.

De ese cuerpo sacrosanto
el verdugo se ensañó;
y con esos crueles clavos,
pies y manos traspasó.
Por sus labios ni una queja
contra nadie se le oyó;
en el silencio de ese justo
mi pobre alma se salvó.

Por fin sus labios se movieron
con ternura sin igual,
implorando al padre eterno
el perdón por ese mal.
La obra quedó perfecta
por eso, a mí me salvó.
Hoy soy limpio por su sangre,
¡Qué alegría, gloria a Dios!', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-350-el-cordero-inmolado/)' where id = 'sa-himno-350-el-cordero-inmolado';
update public.songs set title = 'Estad por Cristo Firmes', lyrics = '¡Estad por Cristo firmes,
soldados de la cruz!
Alzad hoy la bandera
en nombre de Jesús;
es vuestra la victoria
con él por capitán:
por él serán vencidas,
las huestes de Satán

¡Estad por Cristo firmes!
Os llama él a la lid;
¡con él, pues a la lucha,
soldados todos id!
Probad que sois valientes
luchando contra el mal;
es fuerte el enemigo,
mas Cristo es sin igual.

¡Estad por Cristo firmes!
Las fuerzas vienen de él;
el brazo de los hombres
es débil y es infiel;
vestíos la armadura,
velad en oración,
deberes y peligros
demandan gran tesón.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-360-estad-por-cristo-firmes/)' where id = 'sa-himno-360-estad-por-cristo-firmes';
update public.songs set title = 'Oíd Cómo Resuena', lyrics = 'Oíd como resuena el evangelio
diciendo al mundo que venga al Salvador;
que sólo en Jesucristo encontraremos
la vida y paz para el corazón.

{soc}
¡Sí, resuena; sí resuena!
El evangelio del buen Jesús
para que todo el que en él crea,
aunque esté ciego, vea la luz.
{eoc}

Después, si somos fieles, recibiremos
el traje blanco que podremos vestir
y la hermosa corona resplandeciente,
por haber cumplido hasta el fin.

{soc}
¡Sí, resuena; sí resuena!
El evangelio del buen Jesús
para que todo el que en él crea,
aunque esté ciego, vea la luz.
{eoc}

Y cuando en el cielo nos encontremos
con nuestro hermano, el glorioso Salvador,
a él le adoraremos con toda el alma
por la prueba de su gran amor.

{soc}
¡Sí, resuena; sí resuena!
El evangelio del buen Jesús
para que todo el que en él crea,
aunque esté ciego, vea la luz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-363-oid-como-resuena/)' where id = 'sa-himno-363-oid-como-resuena';
update public.songs set title = 'Con Nosotros Venid', lyrics = 'Con nos, venid por Jesús a pelear,
el enemigo batido será,
Dios con nosotros, gloriosa unión.
¡Adelante con Valor, iglesia del Señor!

{soc}
Triunfarán, triunfarán,
las armas divinas la lid ganarán.
Es invencible la hueste de Sión,
¡Adelante con Valor, iglesia del Señor!
{eoc}

Con nos venid los perdidos a buscar,
Cristo murió, al impío salvar,
ya el infierno se opone, cual león.
¡Adelante con Valor, iglesia del Señor!

{soc}
Triunfarán, triunfarán,
las armas divinas la lid ganarán.
Es invencible la hueste de Sión,
¡Adelante con Valor, iglesia del Señor!
{eoc}

Con nos, venid, con valor a luchar,
firme y fiel es preciso estar,
salvos por Cristo es nuestra canción.
¡Adelante con Valor, iglesia del Señor!

{soc}
Triunfarán, triunfarán,
las armas divinas la lid ganarán.
Es invencible la hueste de Sión,
¡Adelante con Valor, iglesia del Señor!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-367-con-nosotros-venid/)' where id = 'sa-himno-367-con-nosotros-venid';
update public.songs set title = 'La Iglesia del Señor', lyrics = 'Eres la iglesia de la libertad
que Dios llamará por su misma voz,
para cumplir en justicia y verdad,
una sublime y grande misión.

{soc}
¡Gloria a ti, gloria a ti!
¡Oh! Salvador.
Fuente de amor.
¡Gloria a ti, gloria a ti!
Gracia que Jesús nos da
¡Gloria a ti!
{eoc}

Amor y gozo podemos tener
si descansamos en Cristo Jesús.
Él es la fuente de vida y poder,
y su palabra, es del mundo la luz.

{soc}
¡Gloria a ti, gloria a ti!
¡Oh! Salvador.
Fuente de amor.
¡Gloria a ti, gloria a ti!
Gracia que Jesús nos da
¡Gloria a ti!
{eoc}

Pueblo escogido para que anuncies
la gran virtud que nos trajo el Señor;
dice a la gente que ya libre seréis
si os libertare el hijo de Dios

{soc}
¡Gloria a ti, gloria a ti!
¡Oh! Salvador.
Fuente de amor.
¡Gloria a ti, gloria a ti!
Gracia que Jesús nos da
¡Gloria a ti!
{eoc}

Y hoy que elevamos a ti nuestra voz
llenos de amor y de luz celestial,
nuevos raudales de paz al Señor
imploremos, con honda ansiedad.

{soc}
¡Gloria a ti, gloria a ti!
¡Oh! Salvador.
Fuente de amor.
¡Gloria a ti, gloria a ti!
Gracia que Jesús nos da
¡Gloria a ti!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-368-la-iglesia-del-senor/)' where id = 'sa-himno-368-la-iglesia-del-senor';
update public.songs set title = '¡Qué Dios Tan Bondadoso!', lyrics = '¡Qué Dios tan bondadoso!
Valor pues alma mía,
tú le verás un día
en su feliz mansión.

{soc}
Un Dios, un Dios,
un Dios por galardón;
un Dios, un Dios,
un Dios por galardón.
{eoc}

De Dios es la sonrisa,
palabra tan sublime;
haz que por ti me anime
a entera conversión.

{soc}
Un Dios, un Dios,
un Dios por galardón;
un Dios, un Dios,
un Dios por galardón.
{eoc}

Me espera una corona
¡Oh! Qué dichosa suerte,
si sirvo hasta la muerte
a mi buen salvador.

{soc}
Un Dios, un Dios,
un Dios por galardón;
un Dios, un Dios,
un Dios por galardón.
{eoc}

Es grande mi esperanza
¡Oh! Mundo cruel y necio;
qué importa tu desprecio
a mi fiel corazón.

{soc}
Un Dios, un Dios,
un Dios por galardón;
un Dios, un Dios,
un Dios por galardón.
{eoc}

Un Dios por galardón,
marchemos pues hermanos;
mostrémonos cristianos
de todo corazón.

{soc}
Un Dios, un Dios,
un Dios por galardón;
un Dios, un Dios,
un Dios por galardón.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-370-que-dios-tan-bondadoso/)' where id = 'sa-himno-370-que-dios-tan-bondadoso';
update public.songs set title = 'El Banquete', lyrics = 'Desde el día que acepté el evangelio,
para mí todo ha sido una alegría.
¡cuán precioso es el reino de los cielos;
si mil años son contados como un día!

Hoy empieza el banquete en esta tierra,
para el alma que ha aceptado al Señor,
ya no hay dolores ni miseria;
quien las quita, es Jesús el salvador.

La presencia de su espíritu da gozo
y es gozo que conmueve el corazón,
busca a Cristo y saldrás victorioso;
en tus manos está la salvación.

Cada día doy un paso hacia delante,
implorando de Jesús el perdón;
de este modo saldré triunfante
y llegaré al trono del Señor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-372-el-banquete/)' where id = 'sa-himno-372-el-banquete';
update public.songs set title = 'Ved que Avanzan Las Huestes', lyrics = 'Ved que avanzan las huestes del rey
entonando himnos a Jesús;
al triunfo, guía él su grey.
¡Victoria, Victoria!
Ellos cantarán.

{soc}
Por un mundo de justicia;
¡adelante, ganaremos victoria!
Anunciad el mundo nuevo,
depurado de pecado.
¡Firmes, que Jesús nos guía,
escuchad su voz!
{eoc}

Nueva aurora le amanecerá
al mundo de tinieblas y materia;
con júbilo se anunciará:
¡Victoria, Victoria!
Para el Dios de amor.

{soc}
Por un mundo de justicia;
¡adelante, ganaremos victoria!
Anunciad el mundo nuevo,
depurado de pecado.
¡Firmes, que Jesús nos guía,
escuchad su voz!
{eoc}

Una estrella dará resplandor
sobre el alma que Cristo salvó;
inflamada del primer amor,
¡Victoria, Victoria!
Cantará a su Dios.

{soc}
Por un mundo de justicia;
¡adelante, ganaremos victoria!
Anunciad el mundo nuevo,
depurado de pecado.
¡Firmes, que Jesús nos guía,
escuchad su voz!
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-376-ved-que-avanzan-las-huestes/)' where id = 'sa-himno-376-ved-que-avanzan-las-huestes';
update public.songs set title = 'Perdón', lyrics = 'Perdón, padre mío, sí, perdón,
reconozco, gran Dios, que te ofendí,
sé que es grande mi negro borrón,
pequé con ardiente frenesí.
Mas imploro, Señor, tu bendición
y levanto las manos a ti
contrito de todo corazón.

Jesús bondadoso salvador,
pan de Dios, santa vara de David;
fuente eterna de vida y amor
sé tú mi maestro y adalid;
sólo tú Jesucristo, mi Señor,
si me llevas contigo a la lid
harás que yo vuelva vencedor.

Habita mi triste corazón
que hasta hoy en tinieblas conservé,
Santo Espíritu, célico don,
aviva mi poca y débil fe,
haz que crea con santa devoción
los misterios que siempre ignoré;
no hunda mi alma la aflicción.

Padre mío, devuélveme tu amor;
Jesucristo intercede junto a él,
Santo Espíritu dame vigor,
deseo vivir con Emmanuel.
Gracias doy a Jesús mi salvador
que me guía al divino vergel.
¡Hosanna! Al glorioso redentor.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-377-perdon/)' where id = 'sa-himno-377-perdon';
update public.songs set title = 'Es La Biblia Gran Tesoro', lyrics = 'Es la Biblia gran tesoro,
el apoyo de la fe;
es preciosa más que el oro
y lumbrera a nuestro pie.
Cuando vienen las tristezas,
hay en ella dulce paz;
son inmensas sus riquezas,
está en ella el solaz.

Es la Biblia blanco lirio
de fragante inspiración;
es consuelo en el martirio,
camino de salvación.
Es un faro en el océano
tenebroso del error;
del futuro es el arcano
revelado al pecador.

Es la Biblia pura fuente
de aguas vivas de salud,
donde encuentra el indigente
a su angustia, paz, quietud.
Es el pan para el hambriento,
al perdido ofrece hogar;
el cansado cobra aliento
en sus promesas sin par.

Es la Biblia fuerte escudo,
armadura es contra el mal;
en el combate más rudo
surge la Biblia triunfal.
Áurea espada de dos filos,
penetra hasta el corazón;
y corta los negros hilos
del pecado y la pasión.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-378-es-la-biblia-gran-tesoro/)' where id = 'sa-himno-378-es-la-biblia-gran-tesoro';
update public.songs set title = 'Por Las Arpas y Las Voces', lyrics = 'Por las arpas y las voces
se alcen notas de loor;
Cristo reina, el cielo goza,
Cristo reina, el Dios de amor
ver su trono donde está,
solo al mundo regirá:
¡Aleluya, aleluya, aleluya, amén!

{soc}
Cristo, Cristo reina,
Cristo, Cristo reina
¡Gloria, gloria! entonad al rey,
¡Gloria, Gloria! A nuestro Dios de amor.
{eoc}

Rey de gloria, reina siempre,
eternal tu potestad;
nadie de tu mano quite
los que son tu propiedad
dicha tiene el escogido
destinado a ver tu faz;
¡Aleluya, aleluya, aleluya, amén!

{soc}
Cristo, Cristo reina,
Cristo, Cristo reina
¡Gloria, gloria! entonad al rey,
¡Gloria, Gloria! A nuestro Dios de amor.
{eoc}

Apresura tu venida
en las nubes, ¡Oh, Señor!
Nuevos cielos, nueva vida,
danos Cristo, por tu amor.
Áureas arpas de tu grey,
¡Gloria! entonarán, ¡oh, rey!
¡Aleluya, aleluya, aleluya, amén!

{soc}
Cristo, Cristo reina,
Cristo, Cristo reina
¡Gloria, gloria! entonad al rey,
¡Gloria, Gloria! A nuestro Dios de amor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-379-por-las-arpas-y-las-voces/)' where id = 'sa-himno-379-por-las-arpas-y-las-voces';
update public.songs set title = 'Mi Redentor', lyrics = 'Mi redentor murió en la cruz,
quien le reciba tendrá la luz;
por pecadores todo él pagó,
ya sus maldades Jesús perdonó.

{soc}
Cuando Dios la sangre ve,
cuando Dios la sangre ve
en la cual el pecador
se lavó, le verá con favor.
{eoc}

A los más malos él salvará;
como promete así lo hará;
en él confía ¡oh! Pecador
vida eterna te dará el Señor.

{soc}
Cuando Dios la sangre ve,
cuando Dios la sangre ve
en la cual el pecador
se lavó, le verá con favor.
{eoc}

El juicio viene, allí estará,
si le rechazas, triste saldrás;
no te detengas ven a Jesús
quien tus pecados llevó a la cruz.

{soc}
Cuando Dios la sangre ve,
cuando Dios la sangre ve
en la cual el pecador
se lavó, le verá con favor.
{eoc}

¡Qué maravilla de gran amor!
Cristo mostró por el pecador;
el que creyere salvo será;
goces eternos el disfrutará.

{soc}
Cuando Dios la sangre ve,
cuando Dios la sangre ve
en la cual el pecador
se lavó, le verá con favor.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-384-mi-redentor/)' where id = 'sa-himno-384-mi-redentor';
update public.songs set title = 'Bajo de Las Estrellas', lyrics = 'Bajo las estrellas, donde
anduvo mi Jesús
en el jardín de Getsemaní
donde luz no se vio,
Cristo se arrodilló
cuando oró bajo el olivar.

{soc}
Bajo el olivar, bajo el olivar,
fue mi Cristo a solas a orar.
Sea tu voluntad, oh padre celestial
cuando oró bajo el olivar.
{eoc}

Cuando al Padre oró, muy triste se sintió;
fue amarga la copa que él bebió.
Vino un ángel del cielo y le confortó,
cuando oró bajo el olivar.

{soc}
Bajo el olivar, bajo el olivar,
fue mi Cristo a solas a orar.
Sea tu voluntad, oh padre celestial
cuando oró bajo el olivar.
{eoc}

Siempre desea mi corazón
el amor que me dio
mi Jesús, cuando oró en el jardín.
¡Gloria sea dad a él;
mis culpas él llevó
cuando oró bajo el olivar!

{soc}
Bajo el olivar, bajo el olivar,
fue mi Cristo a solas a orar.
Sea tu voluntad, oh padre celestial
cuando oró bajo el olivar.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-387-bajo-de-las-estrellas/)' where id = 'sa-himno-387-bajo-de-las-estrellas';
update public.songs set title = 'Los Hijos del Reino', lyrics = 'Los hijos del reino preséntense ya:
resuena guerrera la voz del Señor,
conflicto terrible Satán provocó
las armas tomemos que ya comenzó.

{soc}
Vamos marchando, tengamos valor
armas no sobran, nos manda el Señor,
conflicto terrible Satán provocó
las armas tomemos, que ya comenzó.
{eoc}

La hueste contraria se apresta a la lid:
mas no la temáis; con valor embestid;
es Dios nuestra fuerza, sea nuestra canción;
resueltos marchemos alzando pendón.

{soc}
Vamos marchando, tengamos valor
armas no sobran, nos manda el Señor,
conflicto terrible Satán provocó
las armas tomemos, que ya comenzó.
{eoc}

Por toda la vida mortal, militar
con Cristo por jefe, ¿quién se ha de cansar?
La espada blandiendo con resolución,
cantando marchemos, soldados de Sión.

{soc}
Vamos marchando, tengamos valor
armas no sobran, nos manda el Señor,
conflicto terrible Satán provocó
las armas tomemos, que ya comenzó.
{eoc}

Mil luchas y pruebas nos han de costar
las áureas coronas que nos han de dar
empero, seguros de hallarlas están
aquellos que ha Cristo sin falta se dan.

{soc}
Vamos marchando, tengamos valor
armas no sobran, nos manda el Señor,
conflicto terrible Satán provocó
las armas tomemos, que ya comenzó.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-390-los-hijos-del-reino/)' where id = 'sa-himno-390-los-hijos-del-reino';
update public.songs set title = 'Somos Soldados Guerreros', lyrics = 'Somos soldados guerreros que luchar necesitamos
para dejar nuestros vicios que con Satán encontramos
¡Oh, patria mía, Chile querido!
Hay que luchar por nuestro Dios y que podamos
dejar los vicios de Satanás,
arrepentirnos de los pecados que nos dominan,
y en nuestras almas reine la paz.

{soc}
Viva la gracia que el Señor me ha dado.
Viva su reino para siempre jamás.
Seré soldado fiel hasta la muerte,
porque en Jesús he encontrado paz.
Porque en Jesús he encontrado paz.
{eoc}

Vamos luchando, hermanos por el Señor toda la vida
para darle gloria y honra, y estar firme en su venida.
Sé buen soldado en su caminos
y que podamos serle fiel hasta la muerte
y tributarle eterno honor,
para pagarle de las miserias que nos ha sacado
y ser guerrero con fiel amor.

{soc}
Viva la gracia que el Señor me ha dado.
Viva su reino para siempre jamás.
Seré soldado fiel hasta la muerte,
porque en Jesús he encontrado paz.
Porque en Jesús he encontrado paz.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-392-somos-soldados-guerreros/)' where id = 'sa-himno-392-somos-soldados-guerreros';
update public.songs set title = 'Señor, Mi Dios', lyrics = 'Señor, mi Dios, al contemplar los cielos
el firmamento y las estrellas mil,
al oír tu voz en los potentes truenos
y ver brillar el sol en su cenit.

{soc}
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
{eoc}

Al recorrer los montes y los valles
y ver las bellas flores al pasar,
al escuchar el canto de las aves
y el murmurar del claro manantial

{soc}
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
{eoc}

Cuando recuerdo del amor divino
que desde el cielo el salvador envío,
aquel Jesús que por salvarme vino
y en una cruz sufrió por mí, y murió.

{soc}
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
{eoc}

Cuando el Señor me llame a su presencia
al dulce hogar, al cielo de esplendor,
le adoraré cantando su grandeza
de su poder y su infinito amor.

{soc}
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
Mi corazón entona la canción
cuán grande es él, cuán grande es él.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-393-senor-mi-dios/)' where id = 'sa-himno-393-senor-mi-dios';
update public.songs set title = 'Callad, ¿No Oís?', lyrics = 'Callad, ¿No oís?, suena un cantar,
es un rumor angelical;
el cielo ved se iluminó
con claridad que pasa el sol.

{soc}
A Dios sea la gloria
los ángeles cantaron
y paz sobre la tierra,
al hombre ha visitado.
Jesús el hijo eterno
del Dios que es todo amor,
Jesús que vino a dar
salud al pecador.
{eoc}

De un monte al otro el eco va
pasando el canto angelical:
paz en la tierra, plena paz,
al hombre buena voluntad.

{soc}
A Dios sea la gloria
los ángeles cantaron
y paz sobre la tierra,
al hombre ha visitado.
Jesús el hijo eterno
del Dios que es todo amor,
Jesús que vino a dar
salud al pecador.
{eoc}

Oyen pastores la canción
y van corriendo a Betlehem,
en un establo de un mesón
en un pesebre a un niño ven.

{soc}
A Dios sea la gloria
los ángeles cantaron
y paz sobre la tierra,
al hombre ha visitado.
Jesús el hijo eterno
del Dios que es todo amor,
Jesús que vino a dar
salud al pecador.
{eoc}

Todos los fieles hoy también,
a Jesús nuestro salvador,
rindamos todo nuestro ser,
démosle nuestro corazón.

{soc}
A Dios sea la gloria
los ángeles cantaron
y paz sobre la tierra,
al hombre ha visitado.
Jesús el hijo eterno
del Dios que es todo amor,
Jesús que vino a dar
salud al pecador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-399-callad-no-ois/)' where id = 'sa-himno-399-callad-no-ois';
update public.songs set title = 'Despertad, Soldados Bravos', lyrics = 'Despertad, soldados bravos,
suena la marcial, alarma
para Dios, tomad las armas
a la lid marchad;
no soñéis en la pereza,
miles yacen en tristeza,
o se lanzan con presteza
hacia perdición.

{soc}
Pregonad al mundo
esta buena nueva:
hay perdón y salvación
de Dios la gracia plena.
No temáis ningún peligro,
no huyáis del enemigo
Dios es nuestro fiel amigo,
con valor luchad.
{eoc}

Acudid a la proclama
sed valientes, Dios nos llama,
contra nos el diablo brama,
lleno de furor.
No cedáis, ni tengáis miedo,
combatid con gran denuedo,
romperemos el asedio
del usurpador.

{soc}
Pregonad al mundo
esta buena nueva:
hay perdón y salvación
de Dios la gracia plena.
No temáis ningún peligro,
no huyáis del enemigo
Dios es nuestro fiel amigo,
con valor luchad.
{eoc}

Escuchad, ya se alegran
nuestras tropas y celebran
el triunfo en que llevan
almas al Señor.
Libráremos las del grillo
y del yugo del maligno.
¡viva nuestro gran caudillo!
¡a Jesús loor!

{soc}
Pregonad al mundo
esta buena nueva:
hay perdón y salvación
de Dios la gracia plena.
No temáis ningún peligro,
no huyáis del enemigo
Dios es nuestro fiel amigo,
con valor luchad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-411-despertad-soldados-bravos/)' where id = 'sa-himno-411-despertad-soldados-bravos';
update public.songs set title = 'Hoy es Día de Reposo', lyrics = 'Hoy es día de reposo,
el gran día de solaz;
es el día venturoso
que nos trae dulce paz.
Es el día señalado
con el sello del amor;
nuestro Dios lo ha designado,
es el día del Señor.

Celebremos a porfía
el autor de aquel buen don;
que nos da el festivo día,
y se goza en el perdón.
Aceptemos hoy con gusto
el descanso semanal,
esperando el día augusto
del reposo celestial.

Trabajar es la sentencia
de la antigua creación;
y morir, la consecuencia
de la prevaricación.
Mas reposo y vida estable
Dios nos da quitando el mal
y su amor inescrutable
de la gracia es el raudal.

Los que a ti nos acercamos
por Jesús, Dios de verdad,
hoy alegres proclamamos
tu justicia y tu bondad.
En los fastos de la historia
siempre se celebrará,
y en los cielos su memoria
por los siglos durará.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-412-hoy-es-dia-de-reposo/)' where id = 'sa-himno-412-hoy-es-dia-de-reposo';
update public.songs set title = 'A Nuestro Padre Dios', lyrics = 'A nuestro Padre Dios
demos en alta voz
¡Gloria a Él!
Tal nos amó que dio
al Hijo que murió
y en quien confío yo;
¡Gloria a Él!

A nuestro salvador
demos con fe loor;
¡Gloria a Él!
Su sangre derramó
con ella me lavó,
el cielo me abrió
¡Gloria a Él!

Espíritu de Dios,
yo elevo a ti mi voz;
¡Gloria a Él!
Con celestial fulgor,
¡oh! Muéstrame el amor
de Cristo, mi Señor;
¡Gloria a Él!

Con gozo y amor
cantemos con fervor
al trino Dios.
En la eternidad
mora la Trinidad,
por siempre alabad
al trino Dios.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-413-a-nuestro-padre-dios/)' where id = 'sa-himno-413-a-nuestro-padre-dios';
update public.songs set title = 'Señor, Yo Me Encuentro', lyrics = 'Señor yo me encuentro feliz y contento
siguiendo el camino de verdad y amor
que tú lo has dejado trazando en la tierra
para aquel que sufre de angustia y dolor. (Bis)

Señor tú lo sabes que yo me encontraba
enfermo en mi lecho sin hallar que hacer
clamé a tu sangre gloriosa y bendita
y tú me sanaste y hoy soy feliz. (Bis)

Señor tú lo sabes que en mi hogar había
tristeza y desdicha dolor y aflicción
más tú lo has cambiado por su santa obra
oh gloria a tu sangre bendita Señor. (Bis)

Le doy yo mil gracias al cordero santo
que me halla librado de todo mi mal
prometo seguir en tu santo evangelio
que grande es la obra que has hecho en mi hogar. (Bis)', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-418-senor-yo-me-encuentro/)' where id = 'sa-himno-418-senor-yo-me-encuentro';
update public.songs set title = 'De La Cumbre Del Calvario', lyrics = 'De la cumbre del Calvario
donde el salvador murió
un sonido melodioso
viene a nuestro corazón.

{soc}
El rescate está pagado
ya eres libre pecador.
{eoc}

De Jesús la sangre pura
el pecado ya bebió
si hay quien gime es porque ignora
la divina redención.

{soc}
El rescate está pagado
ya eres libre pecador.
{eoc}

El Señor nos justifica
pues su sangre ya vertió
de las penas estamos libres
si aceptamos el perdón.

{soc}
El rescate está pagado
ya eres libre pecador.
{eoc}

Con sus llagas queda hecha
de la culpa expiación
descarriado ve a Cristo
y seguirle con amor.

{soc}
El rescate está pagado
ya eres libre pecador.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-419-de-la-cumbre-del-calvario/)' where id = 'sa-himno-419-de-la-cumbre-del-calvario';
update public.songs set title = 'Guerreros Fieles Somos', lyrics = 'Guerreros fieles somos de Dios y la verdad
Llevamos por emblema virtud y santidad
El mundo para Cristo es nuestro noble fin
Salgamos valerosos pues ya suena el clarín.

{soc}
Sin vacilar marchad soldados de Jesús
Y por la cruz luchad armados de virtud
Sin descansar corred las almas a salvar
Los perdidos en maldad al salvador llevad.
{eoc}

Las almas por millones sin Dios ni salvación
Se lanzan al abismo de eterna perdición
Aunque estén sumidas en vicios y en maldad
Jesús murió por rescatarles y darles libertad.

{soc}
Sin vacilar marchad soldados de Jesús
Y por la cruz luchad armados de virtud
Sin descansar corred las almas a salvar
Los perdidos en maldad al salvador llevad.
{eoc}

Las huestes enemigas en orden ya están
Sus tropas infernales enviadas por Satán
Valor pues compañeros Jesús con nosotros está
Aquel que nunca lid perdió victoria nos dará.

{soc}
Sin vacilar marchad soldados de Jesús
Y por la cruz luchad armados de virtud
Sin descansar corred las almas a salvar
Los perdidos en maldad al salvador llevad.
{eoc}', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/himno-420-guerreros-fieles-somos/)' where id = 'sa-himno-420-guerreros-fieles-somos';
update public.songs set title = 'Como Un Relámpago', lyrics = 'Como un relámpago
Como un relámpago
así será la venida del Señor
Como un relámpago
Como un relámpago
así será la venida del Señor
Mira a tu pueblo que clamando está
dejales sentir el Espíritu de Dios
Mira a tu pueblo que clamando está
dejales sentir el Espíritu de Dios.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/como-un-relampago/)' where id = 'sa-como-un-relampago';
update public.songs set title = 'Déjame Beber de Tu Río, Señor', lyrics = 'Déjame beber de tu río Señor
Déjame beber de tu río Señor
Déjame beber de tu río Señor
Déjame beber, déjame beber de tu río Señor
Déjame sentir tu presencia Señor
Déjame sentir tu presencia Señor
Déjame sentir tu presencia Señor
Déjame sentir, déjame sentir de tu presencia Señor
Déjame abrazar a mi hermano Señor
Déjame abrazar a mi hermano Señor
Déjame abrazar a mi hermano Señor
Déjame abrazar, déjame abrazar a mi hermano Señor', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/dejame-beber-de-tu-rio-senor/)' where id = 'sa-dejame-beber-de-tu-rio-senor';
