Manda fuego Señor, manda fuego Señor y bautízanos con tu poder.', notes = 'Fuente: Senda Angosta (https://sendangosta.wordpress.com/senor-unenos/)' where id = 'sa-senor-unenos';
update public.songs set title = 'Toma Por Favor', lyrics = 'Toma por favor, mi mano Señor
